//! Layout — integer fixed-point (1/64 px) CSS 2.2 visual formatting: block flow with margin collapsing,
//! inline formatting with greedy line breaking, floats, tables (auto layout), flexbox (single-axis),
//! absolute/fixed positioning, list markers, replaced elements. Emits a flat display list with absolute
//! coordinates plus a border box per element (for hit testing and for scoring against Chrome's bounds).
use crate::dom::{Dom, Kind, NONE};
use crate::font::{FontId, Fonts};
#[path = "oracle_laws.rs"] mod oracle_laws; // GENERATED by tools/emit_laws.py from Chrome black-box laws
use crate::style::{Display, Len, Style, Styled, FX};
use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq)]
pub enum Item {
    Rect { x: i32, y: i32, w: i32, h: i32, color: u32 },
    /// one run of glyphs on a line in one face: glyph id << 16 | x offset in ¼ px (4 bytes per glyph)
    Text { x: i32, y: i32, px: i32, color: u32, face: FontId, glyphs: Vec<u32>, deco: u8, w: i32 },
    /// mode 0 = replaced element (stretched to the box); 1.. = the node's background image
    /// (1 repeat, 2 no-repeat, 3 repeat-x, 4 repeat-y; +8 cover, +16 contain; +32 centered)
    Image { x: i32, y: i32, w: i32, h: i32, node: u32, mode: u8 },
    /// a box that paints more than flat rectangles: rounded corners, shadows, gradients, backdrop blur (paint.rs; P2 "Orbit")
    Box(Box<crate::paint::Deco>),
}

impl Item {
    fn shift(&mut self, dx: i32, dy: i32) {
        match self {
            Item::Rect { x, y, .. } | Item::Text { x, y, .. } | Item::Image { x, y, .. } => { *x += dx; *y += dy; }
            Item::Box(d) => { d.x += dx; d.y += dy; if d.clip != crate::paint::NO_CLIP { d.clip[0] += dx; d.clip[1] += dy; d.clip[2] += dx; d.clip[3] += dy; } }
        }
    }
    pub fn bounds(&self) -> (i32, i32, i32, i32) {
        match self {
            Item::Rect { x, y, w, h, .. } | Item::Image { x, y, w, h, .. } => (*x, *y, *w, *h),
            Item::Text { x, y, px, w, .. } => (*x, *y - *px, *w, *px * 5 / 4),
            Item::Box(d) => (d.x, d.y, d.w, d.h),
        }
    }
    /// What the raster must cover: the box plus anything it paints outside it (outer shadows).
    pub fn paint_bounds(&self) -> (i32, i32, i32, i32) { if let Item::Box(d) = self { d.paint_bounds() } else { self.bounds() } }
}

#[derive(Default)]
pub struct Out { pub items: Vec<Item>, pub boxes: Vec<(u32, [i32; 4])>,
    /// inline element fragments, one per line they occupy: (element, index of the owning block's entry in `boxes`, rect relative
    /// to that box's origin) — for hit testing inline links (BROWSER-BODY-0). A side channel: `boxes` (scored against Chrome) is unchanged.
    pub inline: Vec<(u32, u32, [i32; 4])> }

impl Out {
    /// The inline fragments in page coordinates (after every shift the owning boxes received).
    pub fn inline_abs(&self) -> Vec<(u32, [i32; 4])> {
        self.inline.iter().filter_map(|(e, bi, r)| self.boxes.get(*bi as usize).map(|(_, b)| (*e, [b[0] + r[0], b[1] + r[1], r[2], r[3]]))).collect()
    }
}

impl Out {
    fn shift_from(&mut self, it: usize, bx: usize, dx: i32, dy: i32) {
        let w = crate::why::watched();
        if w != u32::MAX && (dx != 0 || dy != 0) && self.boxes[bx..].iter().any(|b| b.0 == w) {
            let by = self.boxes.last().map(|b| b.0).unwrap_or(u32::MAX);
            crate::why::note("move", format!("subtree shift ({}, {}) — relative/translate/bottom-inset of node {by} or an ancestor", crate::why::px(dx), crate::why::px(dy)));
        }
        for i in &mut self.items[it..] { i.shift(dx, dy); }
        for b in &mut self.boxes[bx..] { b.1[0] += dx; b.1[1] += dy; }
    }
}

pub struct Layout<'a> {
    fcache: std::cell::RefCell<HashMap<(u32, u8), String>>,
    ccache: std::cell::RefCell<HashMap<u32, std::rc::Rc<Vec<u32>>>>,
    kmemo: std::cell::RefCell<HashMap<(u32, &'static str), i32>>,
    pub dom: &'a Dom,
    pub st: &'a Styled,
    pub fonts: &'a Fonts,
    pub img_size: &'a dyn Fn(u32) -> Option<(u32, u32)>,
    pub vw: i32,
    pub vh: i32,
    font_cache: HashMap<(u16, u16, bool), FontId>,
    intrinsic: HashMap<u32, (i32, i32)>,
    floats: Vec<Float>,
    abs: Vec<(u32, i32, i32, u32)>,      // deferred absolute boxes: node, static x, static y, containing-block node
    pos_stack: Vec<u32>,                  // positioned ancestors (containing blocks for absolute descendants)
    cbh: Vec<Option<i32>>,                // definite content heights of containing blocks (percentage heights)
    forced_h: Option<(u32, i32)>,         // border-box height imposed on an abs box with top+bottom set
    pad_cb: Option<(u32, i32)>,           // the containing-block width the caller laid box n out in (percent padding, CSS 2.2 §8.4)
    last_base: Option<i32>,              // baseline of the most recent line box (for inline-block baselines)
    algebra: bool,                       // inline min-content via the Seg monoid (default; OMR_ALGEBRA=0 = old per-item max for A/B)
    pub out: Out,
    /// INCR-R3 S2: layout memo for BFC-root subtrees (None = plain full layout)
    pub memo: Option<LayoutMemo>,
    /// inline fragments waiting for their owning block's box (element, owner, absolute rect at line flush)
    inl_pending: Vec<(u32, u32, [i32; 4])>,
    sub: Vec<u64>,                       // per-node subtree content hash (only with a memo)
}

/// INCR-R3 S2 — the layout change trit. A block box that starts a new block formatting context saves and clears the outer
/// floats, so its layout is a function of: its subtree (DOM content + interned style ids), its border-box width, the
/// parent's definite content height, flex/grid-item status, the knob features its parent and siblings feed (parent style
/// + tag, element position), quirks, viewport, and the sub-pixel phase of (x, y). Key hit = trit 0: items, boxes and the
/// last line baseline are replayed translated to (x, y) (node ids stored relative to the subtree root); miss = trit ±:
/// laid out and stored (its height vs the old one = shrank / grew for the boxes after it). Subtrees that queue absolute
/// boxes are not stored. Gotcha: replaced sizes come from `img_size(node)`; the key covers the node's attributes (src),
/// valid while one src keeps one size within a session.
#[derive(Default)]
pub struct LayoutMemo { map: HashMap<u128, LEnt>, pub hits: usize, pub misses: usize, pub reused_nodes: usize, stored_items: usize, pub calls: usize, pub rej: [usize; 4], pub unstored: usize }
struct LEnt { items: Vec<Item>, boxes: Vec<(u32, [i32; 4])>, h: i32, lb: Option<Option<i32>> }
const LMEMO_CAP_ITEMS: usize = 4_000_000;
#[inline] fn lmix(mut z: u64) -> u64 { z = (z ^ (z >> 30)).wrapping_mul(0xbf58476d1ce4e5b9); z = (z ^ (z >> 27)).wrapping_mul(0x94d049bb133111eb); z ^ (z >> 31) }
fn lbytes(mut h: u64, s: &[u8]) -> u64 {
    h = lmix(h ^ s.len() as u64);
    let mut c = s.chunks_exact(8);
    for w in &mut c { h = lmix(h ^ u64::from_le_bytes(w.try_into().unwrap())); }
    let r = c.remainder(); if !r.is_empty() { let mut t = [0u8; 8]; t[..r.len()].copy_from_slice(r); h = lmix(h ^ u64::from_le_bytes(t) ^ 0xff); }
    h
}
fn lkey(parts: &[u64]) -> u128 {
    let (mut a, mut b) = (0x243f6a8885a308d3u64, 0x13198a2e03707344u64);
    for &p in parts { a = lmix(a ^ p.wrapping_mul(0x9e3779b97f4a7c15)); b = lmix(b.rotate_left(17) ^ p.wrapping_add(0xa4093822299f31d0)); }
    ((a as u128) << 64) | b as u128
}

#[derive(Clone, Copy)]
struct Float { left: bool, x0: i32, x1: i32, y0: i32, y1: i32 }

pub(crate) fn res(l: Len, base: i32) -> Option<i32> {
    match l { Len::Px(v) => Some(v), Len::Pct(p) => Some((base as i64 * p as i64 / 10000) as i32), Len::Mix(v, p) => Some(v + (base as i64 * p as i64 / 10000) as i32), Len::Expr(id) => crate::style::expr_eval(id, base), _ => None }
}
pub(crate) fn res0(l: Len, base: i32) -> i32 { res(l, base).unwrap_or(0) }

/// Min-content of inline content as a monoid (CSS Sizing 3 §5.1 / CSS Text 3 §5): a run of inline pieces is described by
/// its leading and trailing unbreakable widths, its widest unbreakable piece, and whether it may break at its start/end.
/// Joining two runs with no break opportunity between them fuses `a.trail + b.lead` into one unbreakable piece.
#[derive(Clone, Copy, Debug, Default)]
struct Seg { lead: i32, trail: i32, mn: i32, solid: bool, empty: bool, bs: bool, be: bool }
impl Seg {
    fn empty(brk: bool) -> Seg { Seg { empty: true, solid: true, bs: brk, be: brk, ..Default::default() } }
    fn solid(w: i32, bs: bool, be: bool) -> Seg { Seg { lead: w, trail: w, mn: w, solid: true, empty: false, bs, be } }
    fn cat(a: Seg, b: Seg) -> Seg {
        if a.empty { return Seg { bs: a.bs || b.bs, be: if b.empty { a.be || b.be } else { b.be }, ..b }; }
        if b.empty { return Seg { be: a.be || b.be, ..a }; }
        let (lead, trail, mn, solid) = if a.be || b.bs { (a.lead, b.trail, a.mn.max(b.mn), false) }
            else if a.solid && b.solid { let w = a.lead + b.lead; (w, w, w, true) }
            else if a.solid { let l = a.lead + b.lead; (l, b.trail, b.mn.max(l), false) }
            else if b.solid { let t = a.trail + b.lead; (a.lead, t, a.mn.max(t), false) }
            else { (a.lead, b.trail, a.mn.max(b.mn).max(a.trail + b.lead), false) };
        Seg { lead, trail, mn, solid, empty: false, bs: a.bs, be: b.be }
    }
    /// an inline box's margin+border+padding attach to its first and last pieces
    fn widen(self, fl: i32, fr: i32) -> Seg {
        if self.empty { return if fl + fr > 0 { Seg::solid(fl + fr, self.bs, self.be) } else { self }; }
        if self.solid { return Seg::solid(self.lead + fl + fr, self.bs, self.be); }
        let (lead, trail) = (self.lead + fl, self.trail + fr);
        Seg { lead, trail, mn: self.mn.max(lead).max(trail), ..self }
    }
}

/// Named terms of a line's max-content (the core's program vector indexes these).
pub const INLINE_TERMS: usize = 7;
pub const INLINE_TERM_NAMES: [&str; INLINE_TERMS] = ["text", "lead_space_at_line_start", "lead_space_mid_line", "space_before_text", "inline_items", "space_before_item", "flex_gaps"];

/// Decision points the core may rewrite: (point, term names). Each point's value is a ternary-weighted use of its terms.
pub const POINTS: &[(&str, &[&str])] = &[
    ("intrinsic.inline", &INLINE_TERM_NAMES),
    ("flow.margins", &["first_child_top_gap", "last_child_bottom_margin"]),
    ("flex.main", &["grow_share", "shrink_share", "auto_min_clamp", "max_clamp"]),
];

/// The engine's program vector: ternary weights {-1, 0, +1} on named terms per (decision point, context), written by the
/// self-repair core (`omni-render core`) and read here; absent = the hand-written rules (every weight +1).
pub struct Program { w: HashMap<String, HashMap<String, Vec<i8>>>, k: HashMap<String, HashMap<String, i8>>, c: HashMap<String, Vec<CClause>>, bits: HashMap<String, KBits>, jit: HashMap<String, crate::jit::x86::Exec> }
/// A knob clause compiled once when the program is set (WebKit selector-JIT lesson: the generic work happens at compile time):
/// base context split from its literals, literals resolved to feature indices, ordered most specific first.
pub struct CClause { base: String, lits: Vec<(usize, bool, String)>, w: i8 }
fn compile_k(k: &HashMap<String, HashMap<String, i8>>) -> HashMap<String, Vec<CClause>> {
    k.iter().map(|(key, m)| {
        let mut v: Vec<CClause> = m.iter().map(|(c, w)| { let mut it = c.split('&'); let base = it.next().unwrap_or("").to_string();
            let lits = it.filter_map(|l| if let Some((f, x)) = l.split_once("!=") { FEATURES.iter().position(|q| *q == f).map(|i| (i, true, x.to_string())) } else { l.split_once('=').and_then(|(f, x)| FEATURES.iter().position(|q| *q == f).map(|i| (i, false, x.to_string()))) }).collect();
            CClause { base, lits, w: *w } }).collect();
        v.sort_by(|a, b| b.lits.len().cmp(&a.lits.len()).then(a.base.cmp(&b.base)));
        (key.clone(), v)
    }).collect()
}

/// Program verifier (eBPF-verifier idea, clean-room: a program written by the core is checked before the engine runs it).
/// Valid knob keys are read from this file's own source at compile time, so the list cannot drift from the code.
pub fn known_keys() -> std::collections::BTreeSet<String> {
    const SRC: &str = include_str!("layout.rs");
    let mut out = std::collections::BTreeSet::new();
    for (i, _) in SRC.match_indices("\"") { let rest = &SRC[i + 1..]; if let Some(e) = rest.find('"') { let k = &rest[..e];
        if let Some((a, b)) = k.split_once('.') { if ["box", "flow", "line", "table", "grid", "flex", "move", "size", "rule", "patch"].contains(&a) && !b.is_empty() && b.chars().all(|c| c.is_ascii_lowercase() || c == '_') { out.insert(k.to_string()); } } } }
    for p in ["flex.main", "flow.margins", "line.atomic_mid"] { out.remove(p); }
    out
}
const DISPLAYS: &[&str] = &["None", "Block", "Inline", "InlineBlock", "ListItem", "Table", "InlineTable", "TableRow", "TableCell", "TableRowGroup", "TableHeaderGroup", "TableFooterGroup", "TableCaption", "TableColumn", "TableColumnGroup", "Flex", "InlineFlex", "Grid", "InlineGrid", "Contents"];
pub fn verify_program(k: &HashMap<String, HashMap<String, i8>>, w: &HashMap<String, HashMap<String, Vec<i8>>>) -> Vec<String> {
    let keys = known_keys(); let mut err = Vec::new();
    for (key, m) in k {
        if !keys.contains(key) { err.push(format!("unknown knob key {key}")); }
        for (c, wt) in m {
            if !(-1..=1).contains(wt) { err.push(format!("{key}[{c}]: weight {wt} not ternary")); }
            let mut it = c.split('&'); let base = it.next().unwrap_or("");
            if base != "*" && !DISPLAYS.contains(&base.trim_end_matches("@q")) { err.push(format!("{key}[{c}]: unknown context {base}")); }
            let lits: Vec<&str> = it.collect();
            if lits.len() > 3 { err.push(format!("{key}[{c}]: {} literals (max 3)", lits.len())); }
            for l in lits { let f = l.split(['=', '!']).next().unwrap_or(""); if !FEATURES.contains(&f) || !l.contains('=') { err.push(format!("{key}[{c}]: bad literal {l}")); } }
        }
    }
    for (pt, m) in w { let n = Program::terms(pt); if n == 0 { err.push(format!("unknown point {pt}")); } for (c, v) in m { if v.len() != n || v.iter().any(|x| !(-1..=1).contains(x)) { err.push(format!("{pt}[{c}]: bad weights {v:?}")); } } }
    err
}
/// Keyed check over the canonical program (SipHash-2-4, std's keyed implementation; SOURCE-3b's approved form): a program
/// whose signature does not verify under OMR_PROGRAM_KEY is refused, so a forged or corrupted program cannot run unattended.
pub fn program_sig(k: &HashMap<String, HashMap<String, i8>>, w: &HashMap<String, HashMap<String, Vec<i8>>>) -> Option<String> {
    let key = std::env::var("OMR_PROGRAM_KEY").ok()?; let kb = u128::from_str_radix(key.trim(), 16).ok()?;
    let canon = serde_json::to_string(&(k.iter().map(|(a, m)| (a.clone(), m.iter().map(|(c, x)| (c.clone(), *x)).collect::<std::collections::BTreeMap<_, _>>())).collect::<std::collections::BTreeMap<_, _>>(),
        w.iter().map(|(a, m)| (a.clone(), m.iter().map(|(c, x)| (c.clone(), x.clone())).collect::<std::collections::BTreeMap<_, _>>())).collect::<std::collections::BTreeMap<_, _>>())).ok()?;
    #[allow(deprecated)] let mut h = std::hash::SipHasher::new_with_keys(kb as u64, (kb >> 64) as u64);
    use std::hash::Hasher; h.write(canon.as_bytes()); Some(format!("{:016x}", h.finish()))
}

/// Value interner shared by compiled forms: a feature value (or context name) → u32 code.
pub fn intern(v: &str) -> u32 {
    static T: std::sync::OnceLock<std::sync::Mutex<HashMap<String, u32>>> = std::sync::OnceLock::new();
    let t = T.get_or_init(Default::default); let mut m = t.lock().unwrap();
    let n = m.len() as u32 + 1; *m.entry(v.to_string()).or_insert(n)
}
/// Node code slots read by the bitmask and stencil forms: 0 = context with `@q`, 1 = plain display, 2 = quirks, 3+i = FEATURES[i].
pub const SLOT_CTX: usize = 0; pub const SLOT_DISP: usize = 1; pub const SLOT_Q: usize = 2; pub const SLOT_F0: usize = 3;

/// QuickScorer-style clause evaluation (clean-room from Lucchese et al., SIGIR 2015: feature-wise bitvectors ANDed, instead of
/// testing clause by clause) with a Hyperscan-style prefilter (the cheapest literal — the base context — selects candidates first).
/// ≤ 64 clauses per key; bit i = clause i (most specific first).
pub struct KBits { base2: HashMap<u32, u64>, base1: HashMap<u32, u64>, star: u64, feats: Vec<(usize, u64, HashMap<u32, u64>, Vec<(u32, u64)>)>, score: Vec<usize>, w: Vec<i8> }
fn build_bits(v: &[CClause]) -> Option<KBits> {
    if v.len() > 64 { return None; }
    if v.iter().any(|c| { let mut f: Vec<usize> = c.lits.iter().map(|l| l.0).collect(); f.sort(); f.windows(2).any(|w| w[0] == w[1]) }) { return None; } // two literals on one feature → compiled path
    let mut kb = KBits { base2: HashMap::new(), base1: HashMap::new(), star: 0, feats: Vec::new(), score: v.iter().map(|c| c.lits.len() * 4).collect(), w: v.iter().map(|c| c.w).collect() };
    for (i, c) in v.iter().enumerate() {
        let bit = 1u64 << i;
        if c.base == "*" { kb.star |= bit; } else { *kb.base2.entry(intern(&c.base)).or_default() |= bit; if !c.base.ends_with("@q") { *kb.base1.entry(intern(&c.base)).or_default() |= bit; } }
    }
    let used: std::collections::BTreeSet<usize> = v.iter().flat_map(|c| c.lits.iter().map(|l| l.0)).collect();
    for f in used {
        let mut free = 0u64; let mut eq: HashMap<u32, u64> = HashMap::new(); let mut neq = Vec::new();
        for (i, c) in v.iter().enumerate() { let bit = 1u64 << i; let ls: Vec<_> = c.lits.iter().filter(|l| l.0 == f).collect();
            if ls.is_empty() { free |= bit; continue; }
            if ls.len() == 1 { if ls[0].1 { neq.push((intern(&ls[0].2), bit)); } else { *eq.entry(intern(&ls[0].2)).or_default() |= bit; } }
            // two literals on one feature: rare; keep them exact by leaving the clause out of the bitmask path (never set)
        }
        kb.feats.push((SLOT_F0 + f, free, eq, neq));
    }
    Some(kb)
}
fn eval_bits(kb: &KBits, codes: &[u32]) -> i32 {
    let quirks = codes[SLOT_Q] == intern("1");
    let m2 = kb.base2.get(&codes[SLOT_CTX]).copied().unwrap_or(0) | if !quirks { kb.base2.get(&codes[SLOT_DISP]).copied().unwrap_or(0) } else { 0 };
    let m1 = if quirks { kb.base1.get(&codes[SLOT_DISP]).copied().unwrap_or(0) } else { 0 };
    let mut cand = m2 | m1 | kb.star;
    for (slot, free, eq, neq) in &kb.feats { if cand == 0 { break; }
        let v = codes[*slot]; let mut ok = *free | eq.get(&v).copied().unwrap_or(0);
        for (x, bit) in neq { if *x != v { ok |= bit; } }
        cand &= ok; }
    let mut best: Option<(usize, i32)> = None;
    while cand != 0 { let i = cand.trailing_zeros() as usize; cand &= cand - 1;
        let rank = if m2 >> i & 1 == 1 { 2 } else if m1 >> i & 1 == 1 { 1 } else { 0 };
        let sc = kb.score[i] + rank; if best.map_or(true, |b| sc > b.0) { best = Some((sc, kb.w[i] as i32)); } }
    best.map_or(1, |b| b.1)
}
/// Copy-and-patch stencils (clean-room from Xu & Kjolstad, OOPSLA 2021: pre-made machine-code pieces copied and patched with
/// constants, no optimiser). Per key: every clause becomes, most specific first, a run of
///   mov eax,[rdi+4·slot] / cmp eax,imm32 / jne|je next      (8B 87 d32 · 3D i32 · 0F 85|84 r32)
/// then mov eax,weight / ret (B8 i32 · C3); fall-through returns 1 (the hand rule). Signature: extern "C" fn(*const u32) -> i32.
fn build_jit(v: &[CClause]) -> crate::jit::x86::Exec {
    // variants: (score, checks [(slot, code, equal?)], weight) — base context expanded into its exact-match forms
    let mut vars: Vec<(usize, Vec<(usize, u32, bool)>, i8)> = Vec::new();
    for c in v {
        let lits: Vec<(usize, u32, bool)> = c.lits.iter().map(|l| (SLOT_F0 + l.0, intern(&l.2), !l.1)).collect();
        if c.base == "*" { vars.push((c.lits.len() * 4, lits, c.w)); continue; }
        let mut a = lits.clone(); a.insert(0, (SLOT_CTX, intern(&c.base), true)); vars.push((c.lits.len() * 4 + 2, a, c.w));
        if !c.base.ends_with("@q") { let mut b = lits.clone(); b.insert(0, (SLOT_Q, intern("1"), true)); b.insert(0, (SLOT_DISP, intern(&c.base), true)); vars.push((c.lits.len() * 4 + 1, b, c.w)); }
    }
    vars.sort_by(|a, b| b.0.cmp(&a.0));
    let mut code: Vec<u8> = Vec::new();
    for (_, checks, w) in &vars {
        let mut fixups = Vec::new();
        for (slot, val, eq) in checks {
            code.extend([0x8B, 0x87]); code.extend(((slot * 4) as u32).to_le_bytes());   // mov eax, [rdi + 4·slot]
            code.push(0x3D); code.extend(val.to_le_bytes());                           // cmp eax, imm32
            code.extend([0x0F, if *eq { 0x85 } else { 0x84 }]); fixups.push(code.len()); code.extend([0, 0, 0, 0]); // jne/je next
        }
        code.push(0xB8); code.extend((*w as i32).to_le_bytes()); code.push(0xC3);       // mov eax, w ; ret
        let next = code.len();
        for f in fixups { let rel = (next - (f + 4)) as i32; code[f..f + 4].copy_from_slice(&rel.to_le_bytes()); }
    }
    code.push(0xB8); code.extend(1i32.to_le_bytes()); code.push(0xC3);                  // mov eax, 1 ; ret
    crate::jit::x86::Exec::new(&code)
}
impl Program {
    pub fn terms(point: &str) -> usize { if point.starts_with("k:") { return 1; } POINTS.iter().find(|p| p.0 == point).map(|p| p.1.len()).unwrap_or(0) }
    /// Lookup order: the exact context (e.g. `TableCell@q` = quirks mode), then the plain context, then `*`.
    fn find<'s>(&'s self, point: &str, ctx: &str) -> Option<&'s Vec<i8>> {
        let m = self.w.get(point)?;
        m.get(ctx).or_else(|| ctx.strip_suffix("@q").and_then(|c| m.get(c))).or_else(|| m.get("*"))
    }
    pub fn weights(&self, point: &str, ctx: &str) -> Vec<i8> { self.find(point, ctx).cloned().unwrap_or_else(|| vec![1; Self::terms(point)]) }
    pub fn weight(&self, point: &str, ctx: &str, term: usize) -> i32 { self.find(point, ctx).and_then(|v| v.get(term)).map(|x| *x as i32).unwrap_or(1) }
    pub fn inline_weights(&self, ctx: &str) -> [i8; INLINE_TERMS] { let v = self.weights("intrinsic.inline", ctx); let mut a = [1i8; INLINE_TERMS]; for (i, x) in v.iter().enumerate().take(INLINE_TERMS) { a[i] = *x; } a }
    /// Points named `k:<stage.term>` are ledger knobs (one weight each); the rest are POINTS.
    pub fn from_map(m: HashMap<String, HashMap<String, Vec<i8>>>) -> Program {
        let (mut w, mut k) = (HashMap::new(), HashMap::new());
        for (pt, c) in m { if let Some(key) = pt.strip_prefix("k:") { k.insert(key.to_string(), c.into_iter().map(|(cx, v)| (cx, v.first().copied().unwrap_or(1))).collect()); } else { w.insert(pt, c); } }
        let c = compile_k(&k); let bits = c.iter().filter_map(|(key, v)| build_bits(v).map(|b| (key.clone(), b))).collect(); let jit = c.iter().map(|(key, v)| (key.clone(), build_jit(v))).collect(); Program { w, k, c, bits, jit }
    }
    /// Compiled lookup: same answer as `knob_at` (checked by `core --check-compiled`), without parsing or string building.
    #[inline]
    pub fn has_key(&self, key: &str) -> bool { self.c.contains_key(key) }
    pub fn knob_fast(&self, key: &str, disp: &str, quirks: bool, feat: &dyn Fn(usize) -> String) -> i32 {
        let Some(v) = self.c.get(key) else { return 1 };
        let mut best: Option<(usize, i32)> = None;
        for cl in v {
            let rank = if cl.base == disp && !quirks { 2 } else if quirks && cl.base.strip_suffix("@q") == Some(disp) { 2 } else if cl.base == disp { 1 } else if cl.base == "*" { 0 } else { continue };
            if !cl.lits.iter().all(|(i, neg, x)| (feat(*i) == *x) != *neg) { continue; }
            let score = cl.lits.len() * 4 + rank;
            if best.map_or(true, |b| score > b.0) { best = Some((score, cl.w as i32)); }
        }
        best.map_or(1, |b| b.1)
    }
    /// Feature indices any clause reads (code arrays fill only these slots).
    pub fn used_features(&self) -> Vec<usize> { let s: std::collections::BTreeSet<usize> = self.c.values().flatten().flat_map(|c| c.lits.iter().map(|l| l.0)).collect(); s.into_iter().collect() }
    pub fn knob_bits(&self, key: &str, codes: &[u32]) -> i32 { self.bits.get(key).map_or(1, |b| eval_bits(b, codes)) }
    pub fn knob_jit(&self, key: &str, codes: &[u32]) -> i32 {
        let Some(e) = self.jit.get(key) else { return 1 };
        let f: extern "C" fn(*const u32) -> i32 = unsafe { std::mem::transmute(e.ptr()) }; f(codes.as_ptr())
    }
    pub fn map(&self) -> HashMap<String, HashMap<String, Vec<i8>>> {
        let mut m = self.w.clone();
        for (key, c) in &self.k { m.insert(format!("k:{key}"), c.iter().map(|(cx, v)| (cx.clone(), vec![*v])).collect()); }
        m
    }
    /// Ledger knob weight for (stage.term, context): exact context, then without `@q`, then `*`; absent = 1 (the hand rule).
    pub fn knob(&self, key: &str, ctx: &str) -> i32 {
        let Some(m) = self.k.get(key) else { return 1 };
        m.get(ctx).or_else(|| ctx.strip_suffix("@q").and_then(|c| m.get(c))).or_else(|| m.get("*")).map_or(1, |v| *v as i32)
    }
    pub fn has_knobs(&self) -> bool { !self.k.is_empty() }
    /// The knob table as Horn clauses: (key, context-with-literals, weight).
    pub fn clauses(&self) -> Vec<(String, String, i8)> { let mut v: Vec<_> = self.k.iter().flat_map(|(k, m)| m.iter().map(move |(c, w)| (k.clone(), c.clone(), *w))).collect(); v.sort(); v }
    /// Knob weight with CONDITIONS (SAT station): a context may carry literals, `TableCell&tag=td&quirks!=1`; the entry whose
    /// base context matches and whose literals all hold on the node wins, most literals first; plain contexts as `knob`.
    pub fn knob_at(&self, key: &str, ctx: &str, feat: &dyn Fn(&str) -> String) -> i32 {
        let Some(m) = self.k.get(key) else { return 1 };
        let mut best: Option<(usize, i32)> = None;
        for (c, w) in m {
            let mut parts = c.split('&');
            let base = parts.next().unwrap_or("");
            let rank = if base == ctx { 2 } else if ctx.strip_suffix("@q") == Some(base) { 1 } else if base == "*" { 0 } else { continue };
            let lits: Vec<&str> = parts.collect();
            if !lits.iter().all(|l| if let Some((f, v)) = l.split_once("!=") { feat(f) != v } else if let Some((f, v)) = l.split_once('=') { feat(f) == v } else { false }) { continue; }
            let score = lits.len() * 4 + rank;
            if best.map_or(true, |b| score > b.0) { best = Some((score, *w as i32)); }
        }
        best.map_or(1, |b| b.1)
    }
    pub fn load(path: &str) -> Program { Self::load_checked(path, true) }
    /// `check_sig = false` only for the signing tool (an unsigned program being signed by its owner).
    pub fn load_checked(path: &str, check_sig: bool) -> Program {
        let mut w: HashMap<String, HashMap<String, Vec<i8>>> = HashMap::new();
        if let Ok(j) = std::fs::read(path).map(|b| serde_json::from_slice::<serde_json::Value>(&b).unwrap_or_default()) {
            for (point, names) in POINTS {
                if let Some(o) = j[*point].as_object() {
                    for (k, v) in o {
                        let mut ws = vec![1i8; names.len()];
                        for (i, x) in v.as_array().into_iter().flatten().enumerate().take(names.len()) { ws[i] = x.as_i64().unwrap_or(1).clamp(-1, 1) as i8; }
                        w.entry(point.to_string()).or_default().insert(k.clone(), ws);
                    }
                }
            }
        }
        let mut k: HashMap<String, HashMap<String, i8>> = HashMap::new();
        if let Ok(j) = std::fs::read(path).map(|b| serde_json::from_slice::<serde_json::Value>(&b).unwrap_or_default()) {
            if let Some(o) = j["knobs"].as_object() { for (key, c) in o { if let Some(c) = c.as_object() { k.insert(key.clone(), c.iter().map(|(cx, v)| (cx.clone(), v.as_i64().unwrap_or(1).clamp(-1, 1) as i8)).collect()); } } }
        }
        let errs = verify_program(&k, &w);
        let sig_ok = !check_sig || match program_sig(&k, &w) { None => true, Some(s) => std::fs::read(path).ok().and_then(|b| serde_json::from_slice::<serde_json::Value>(&b).ok()).map_or(false, |j| j["sig"].as_str() == Some(s.as_str())) };
        if !errs.is_empty() || !sig_ok {
            eprintln!("program {path} REFUSED ({}) — running the hand rules", if !sig_ok { "signature does not verify".to_string() } else { errs.join("; ") });
            return Program::from_map(HashMap::new());
        }
        let c = compile_k(&k); let bits = c.iter().filter_map(|(key, v)| build_bits(v).map(|b| (key.clone(), b))).collect(); let jit = c.iter().map(|(key, v)| (key.clone(), build_jit(v))).collect(); Program { w, k, c, bits, jit }
    }
    pub fn save(&self, path: &str) {
        let mut out = serde_json::Map::new();
        for (point, names) in POINTS {
            if let Some(m) = self.w.get(*point) { out.insert(point.to_string(), serde_json::json!(m)); out.insert(format!("{point}.terms"), serde_json::json!(names)); }
        }
        if !self.k.is_empty() { out.insert("knobs".into(), serde_json::json!(self.k)); }
        if let Some(sig) = program_sig(&self.k, &self.w) { out.insert("sig".into(), serde_json::json!(sig)); }
        std::fs::write(path, serde_json::to_string_pretty(&serde_json::Value::Object(out)).unwrap()).ok();
    }
}
thread_local! { static PROGRAM: std::cell::RefCell<Option<std::rc::Rc<Program>>> = const { std::cell::RefCell::new(None) }; }
pub fn program() -> std::rc::Rc<Program> {
    PROGRAM.with(|p| p.borrow_mut().get_or_insert_with(|| { let pr = Program::load(&std::env::var("OMR_PROGRAM").unwrap_or_else(|_| "omr.program.json".into())); KNOBS_ON.with(|k| k.set(pr.has_knobs())); std::rc::Rc::new(pr) }).clone())
}
/// Swap the program in-process (the core evaluating a candidate).
/// DOCTOR transplant v2 guard (step 3a): a dormant switch usable anywhere (free fns, hosts without a node) — on only when the
/// program carries the clause `patch.e<id>[*] = −1`. The node-bound `Layout::patch` stays for context-conditioned ports.
#[allow(dead_code)]

// STATEMENT COVERAGE (author 10-06: box tree ↔ code AST, statement level): `cov(line!())` at the head of every branch block charges
// that source line to the box currently being laid out (the top of CUR_NODE, entered in block_box_full); recorded in the term
// ledger as ("line", line) only while the ledger is on.
thread_local! { static CUR_NODE: std::cell::RefCell<Vec<u32>> = const { std::cell::RefCell::new(Vec::new()) }; }
pub struct CurNode;
impl CurNode { pub fn enter(n: u32) -> CurNode { CUR_NODE.with(|c| c.borrow_mut().push(n)); CurNode } }
impl Drop for CurNode { fn drop(&mut self) { CUR_NODE.with(|c| { c.borrow_mut().pop(); }); } }
#[inline] pub fn cov(line: u32) {
    if LEDGER_ON.with(|o| o.get()) { if let Some(n) = CUR_NODE.with(|c| c.borrow().last().copied()) { LEDGER.with(|l| l.borrow_mut().push((n, "line", line as i32))); } }
}

// COUNTERFACTUAL INJECTION (doctor B2; author 10-06 "if we change the roots we'll see a cascade — do we adapt or does it adapt to us?"):
// a node in INJECT is laid out at Chrome's border-box width / height, everything else as usual, so the probe can count who adapts.
thread_local! { pub static INJECT: std::cell::RefCell<HashMap<u32, (i32, i32)>> = std::cell::RefCell::new(HashMap::new()); }
pub fn inject_set(m: HashMap<u32, (i32, i32)>) { INJECT.with(|i| *i.borrow_mut() = m); }
fn injected(n: u32) -> Option<(i32, i32)> { INJECT.with(|i| { let b = i.borrow(); if b.is_empty() { None } else { b.get(&n).copied() } }) }
// RESTRUCTURE (doctor-core route 2, author 10-07 "at 97 %+ geometric fit we begin to restructure to fit our needs"): per document, a
// node is laid out at the doctor's exact geometry — its border box offset by (dx, dy) and, when w ≥ 0, given width w — so its
// subtree and paint follow it (children placed from the new origin, text re-wrapped at the new width). Keyed by the document's
// node buffer (stable while the document lives), so cached documents laid out later still get their own table.
thread_local! { static GEO: std::cell::RefCell<HashMap<usize, HashMap<u32, (i32, i32, i32)>>> = std::cell::RefCell::new(HashMap::new()); }
pub fn geo_set(dom: &Dom, m: Option<HashMap<u32, (i32, i32, i32)>>) {
    let k = dom.nodes.as_ptr() as usize;
    GEO.with(|g| { let mut g = g.borrow_mut(); match m { Some(m) if !m.is_empty() => { g.insert(k, m); } _ => { g.remove(&k); } } });
}
fn geo_of(dom: &Dom, n: u32) -> Option<(i32, i32, i32)> {
    GEO.with(|g| { let g = g.borrow(); if g.is_empty() { None } else { g.get(&(dom.nodes.as_ptr() as usize)).and_then(|m| m.get(&n).copied()) } })
}
fn geo_any(dom: &Dom) -> bool { GEO.with(|g| { let g = g.borrow(); !g.is_empty() && g.contains_key(&(dom.nodes.as_ptr() as usize)) }) }
/// switches read outside this file (style.rs): their keys live here so the program verifier sees them
pub const PATCH_TRACK_MATH: &str = "patch.track_math";
pub const PATCH_SIZE_ADJUST: &str = "patch.size_adjust";
pub const PATCH_FONT_SHORTHAND: &str = "patch.font_shorthand";
pub const PATCH_VAR_FONT: &str = "patch.var_font";
pub const PATCH_PSEUDO_VARS: &str = "patch.pseudo_vars";
pub const PATCH_UNICODE_RANGE: &str = "patch.unicode_range";
pub const PATCH_SHADOW_STYLES: &str = "patch.shadow_styles";
pub const PATCH_HAS: &str = "patch.has";
pub const PATCH_CQ_UNITS: &str = "patch.cq_units";
pub const PATCH_IS_SPEC: &str = "patch.is_spec";
pub const PATCH_CSS_NESTING: &str = "patch.css_nesting";
// the program loads lazily: a patch read before the first layout call (CSS parse of the first page) must load it, or the
// switch reads as off for that page only (seen 10-06: `:has()` dormant on the first oracle case, live on the rest)
pub fn patch_on(key: &str) -> bool { if PROGRAM.with(|p| p.borrow().is_none()) { program(); } KNOBS_ON.with(|k| k.get()) && { let p = program(); p.has_key(key) && p.knob(key, "*") < 0 } }
/// Width of one unbreakable text piece: advances + letter-spacing, plus OpenType pair kerning between adjacent glyphs of one
/// face when `patch.kern` is on (DOCNEXT-S5; omni-spec `otshape`). Blink shapes word by word, so no kerning across spaces.
pub fn piece_w(fonts: &Fonts, f: FontId, w: &str, px: i32, ls: i32, kern: bool) -> i32 {
    let mut tot = 0;
    let mut prev: Option<(FontId, u16)> = None;
    for ch in w.chars() {
        let (fid, g, a) = fonts.advance(f, ch, px);
        if kern { if let Some((pf, pg)) = prev { if pf == fid { tot += fonts.kern(fid, pg, g, px); } } }
        tot += a + ls;
        prev = Some((fid, g));
    }
    tot
}
/// Unbreakable pieces of one whitespace-free word: the UAX #14 break opportunities inside it (e.g. after a hyphen,
/// around an em dash, between ideographs) when `patch.linebreak` is on (DOCNEXT-S5; omni-spec `uax14`); else the whole word.
pub fn pieces(w: &str, on: bool) -> Vec<&str> {
    if !on || w.is_ascii() && !w.bytes().any(|b| matches!(b, b'-' | b'?' | b'!' | b'}' | b')' | b']' | b'%' | b'|')) { return vec![w]; }
    let mut out = Vec::new();
    let mut a = 0;
    for b in omni_spec::uax14::break_opportunities(w) {
        if b.index <= a || b.index >= w.len() { continue; }
        // tailoring (observed Chrome behaviour on the frozen corpus: `/dev/swap_partition` stays whole): no break after a solidus
        if w.as_bytes()[b.index - 1] == b'/' { continue; }
        out.push(&w[a..b.index]); a = b.index;
    }
    out.push(&w[a..]);
    out
}
pub fn set_program(p: Program) { KNOBS_ON.with(|k| k.set(p.has_knobs())); PROGRAM.with(|x| *x.borrow_mut() = Some(std::rc::Rc::new(p))); }

// ── term ledger (REPAIR-CORE M1/A′): every additive layout term goes through `Layout::term`, which records (node, key, value)
// when the ledger is on and weighs it by the program's knob for (key, the node's display context). With no knobs and no ledger
// it is two thread-local Cell loads — the hand-written rules run unchanged.
thread_local! {
    static KNOBS_ON: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    static LEDGER_ON: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    static LEDGER: std::cell::RefCell<Vec<(u32, &'static str, i32)>> = const { std::cell::RefCell::new(Vec::new()) };
}
pub fn ledger_start() { LEDGER.with(|l| l.borrow_mut().clear()); LEDGER_ON.with(|o| o.set(true)); }
pub fn ledger_take() -> Vec<(u32, &'static str, i32)> { LEDGER_ON.with(|o| o.set(false)); LEDGER.with(|l| std::mem::take(&mut *l.borrow_mut())) }

/// Node features the SAT station builds conditions from (and `knob_at` evaluates): structural + style facts, never page
/// specifics such as class names or ids (a condition must generalise across pages).
pub const FEATURES: &[&str] = &["disp", "tag", "ptag", "pdisp", "quirks", "pos", "float", "ovf", "bbox", "ws", "va", "text", "h_set", "w_set", "bt", "bb", "pt", "pb", "pflexdir", "nkids", "mt", "mb", "first", "last", "ppb", "pbb", "hasblock"];
pub fn node_feature(d: &Dom, st: &Styled, n: u32, f: &str) -> String {
    let el = |x: u32| x != NONE && d.nodes[x as usize].kind == Kind::Element;
    if !el(n) { return String::new(); }
    let s = &st.table[st.ids[n as usize] as usize];
    let p = d.nodes[n as usize].parent;
    let b = |x: bool| if x { "1".to_string() } else { "0".to_string() };
    let nz = |l: Len| !matches!(l, Len::Px(0) | Len::Auto);
    match f {
        "disp" => format!("{:?}", s.display),
        "tag" => d.tag(n).to_string(),
        "ptag" => if el(p) { d.tag(p).to_string() } else { String::new() },
        "pdisp" => if el(p) { format!("{:?}", st.table[st.ids[p as usize] as usize].display) } else { String::new() },
        "pflexdir" => if el(p) { st.table[st.ids[p as usize] as usize].flex_dir.to_string() } else { String::new() },
        "quirks" => b(d.quirks),
        "pos" => s.position.to_string(), "float" => s.float.to_string(), "ovf" => s.overflow.to_string(), "bbox" => b(s.border_box),
        "ws" => s.white_space.to_string(), "va" => s.vertical_align.to_string(),
        "text" => b(d.children(n).any(|c| d.nodes[c as usize].kind == Kind::Text && !d.text(c).trim().is_empty())),
        "h_set" => b(!matches!(s.height, Len::Auto)), "w_set" => b(!matches!(s.width, Len::Auto)),
        "bt" => b(s.border_w[0] > 0), "bb" => b(s.border_w[2] > 0), "pt" => b(nz(s.padding[0])), "pb" => b(nz(s.padding[2])),
        "mt" | "mb" => match s.margin[if f == "mt" { 0 } else { 2 }] { Len::Px(0) => "0".into(), Len::Px(v) if v > 0 => "+".into(), Len::Px(_) => "-".into(), Len::Auto => "a".into(), _ => "%".into() },
        "first" | "last" => { if !el(p) { return "1".into(); } let sib: Vec<u32> = d.children(p).filter(|&c| el(c)).collect(); b(if f == "first" { sib.first() == Some(&n) } else { sib.last() == Some(&n) }) }
        "ppb" => if el(p) { b(nz(st.table[st.ids[p as usize] as usize].padding[2])) } else { "0".into() },
        "pbb" => if el(p) { b(st.table[st.ids[p as usize] as usize].border_w[2] > 0) } else { "0".into() },
        "hasblock" => b(d.children(n).any(|c| el(c) && matches!(st.table[st.ids[c as usize] as usize].display, Display::Block | Display::Flex | Display::Grid | Display::Table | Display::ListItem))),
        "nkids" => { let k = d.children(n).filter(|&c| el(c)).count(); (if k > 3 { 3 } else { k }).to_string() }
        _ => String::new(),
    }
}

/// Collapse two adjoining margins: largest positive + most negative.
fn combine(a: i32, b: i32) -> i32 { a.max(b).max(0) + a.min(b).min(0) }

fn is_block_level(d: Display) -> bool {
    matches!(d, Display::Block | Display::ListItem | Display::Table | Display::Flex | Display::Grid | Display::TableCaption
        | Display::TableRowGroup | Display::TableHeaderGroup | Display::TableFooterGroup | Display::TableRow | Display::TableCell)
}

enum Inl { Text(u32), Atomic(u32), Br, Open(u32), Close(u32) }

impl<'a> Layout<'a> {
    pub fn new(dom: &'a Dom, st: &'a Styled, fonts: &'a Fonts, img_size: &'a dyn Fn(u32) -> Option<(u32, u32)>, vw: i32, vh: i32) -> Self {
        Layout { fcache: Default::default(), ccache: Default::default(), kmemo: Default::default(), dom, st, fonts, img_size, vw: vw * FX, vh: vh * FX, font_cache: HashMap::new(), intrinsic: HashMap::new(),
                 floats: Vec::new(), abs: Vec::new(), pos_stack: Vec::new(), cbh: Vec::new(), forced_h: None, pad_cb: None, last_base: None, algebra: std::env::var("OMR_ALGEBRA").map_or(true, |v| v != "0"), out: Out::default(),
                 memo: None, sub: Vec::new(), inl_pending: Vec::new() }
    }

    fn s(&self, n: u32) -> &'a Style { &self.st.table[self.st.ids[n as usize] as usize] }
    fn disp(&self, n: u32) -> Display {
        let k = self.dom.nodes[n as usize].kind;
        if k == Kind::Text { return Display::Inline; }
        if k != Kind::Element { return Display::None; }
        self.s(n).display
    }
    fn font(&mut self, s: &Style) -> FontId {
        let k = (s.font_family, s.font_weight, s.italic);
        if let Some(&f) = self.font_cache.get(&k) { return f; }
        let f = self.fonts.resolve(&self.st.families[s.font_family as usize], s.font_weight, s.italic);
        self.font_cache.insert(k, f);
        f
    }
    /// Pair kerning on for text whose parent element is `n`: `patch.kern` and the face is the one the page asked for (DOCNEXT-S5).
    fn kern_on(&self, n: u32, s: &Style) -> bool { self.patch(n, "patch.kern") && self.fonts.is_primary(&self.st.families[s.font_family as usize], s.font_weight, s.italic) }
    fn line_h(&mut self, s: &Style) -> i32 {
        match s.line_height {
            Len::Px(v) => v,
            Len::Pct(p) => (s.font_size as i64 * p as i64 / 10000) as i32,
            _ => { let f = self.font(s); self.fonts.normal_line(f, s.font_size) }
        }
    }

    /// Lay out the document; returns total height.
    pub fn run(&mut self) -> i32 {
        let t_run = std::time::Instant::now(); // E1: the T25 doctor core fires at the end of every pass (jit::t25::fire)
        let root = self.dom.children(0).find(|&c| self.dom.nodes[c as usize].kind == Kind::Element).unwrap_or(NONE);
        if root == NONE { return 0; }
        if self.memo.is_some() { self.subtree_hashes(); }
        self.cbh.push(Some(self.vh));
        // `:root { scrollbar-gutter: stable }` reserves the classic scrollbar (15 px in Chrome) even when nothing overflows
        // (CSS Overflow 4 §3.1; MDN: Chrome's root is 1,265 px wide in a 1,280 px viewport)
        let gutter = if self.s(root).sb_gutter && self.patch(root, "patch.sb_gutter") { 15 * FX } else { 0 };
        let h = self.block(root, 0, 0, self.vw - gutter, true);
        // absolutely positioned boxes, laid out against their containing block's padding box
        let mut index: HashMap<u32, [i32; 4]> = HashMap::new();
        let mut indexed = 0;
        let mut k = 0;
        while k < self.abs.len() {
            cov(line!());
            for b in &self.out.boxes[indexed..] { index.entry(b.0).or_insert(b.1); }
            indexed = self.out.boxes.len();
            let (n, sx, sy, cbn) = self.abs[k];
            let cb = if cbn == NONE { None } else { index.get(&cbn).copied() };
            let it0 = self.out.items.len();
            self.place_abs(n, sx, sy, cbn, cb);
            // opacity of every ancestor (CSS Color 4 §3.2: a group effect on the whole subtree) — positioned boxes are placed
            // after their ancestors' own opacity pass, so it is applied here (P2: Orbit's hidden panels showed their knobs)
            let mut op = 255u32;
            let mut a = self.dom.nodes[n as usize].parent;
            let mut guard = 0;
            while a != NONE && (a as usize) < self.dom.nodes.len() && a != n && guard < 4096 {
                guard += 1;
                if self.dom.nodes[a as usize].kind == Kind::Element { op = op * self.s(a).opacity as u32 / 255; }
                a = self.dom.nodes[a as usize].parent;
            }
            if op == 0 { self.out.items.truncate(it0); }
            else if op < 255 {
                for it in &mut self.out.items[it0..] {
                    match it { Item::Rect { color, .. } | Item::Text { color, .. } => { *color = (*color & !0xff) | ((*color & 0xff) * op / 255); }
                        Item::Box(d) => d.alpha = (d.alpha as u32 * op / 255) as u8, Item::Image { .. } => {} }
                }
            }
            k += 1;
        }
        // scrollable height = the document's overflow extent (content may overflow a 100%-height root)
        // painted content sets the extent (boxes clipped away inside scroll containers must not lengthen the page)
        let extent = self.out.items.iter().map(|i| { let (_, y, _, h) = i.bounds(); y + h }).max().unwrap_or(0);
        let total = h.max(extent).max(self.vh);
        // CSS 2.2 §14.2 / Backgrounds 3 §2.11.2: the root's background (else body's, when the root has none) paints the whole
        // canvas — under everything, the full scroll extent. A body of only positioned children is 0 px tall but still colours the page.
        let body = self.dom.children(root).find(|&c| self.dom.nodes[c as usize].kind == Kind::Element && self.dom.tag(c) == "body");
        let canvas = if self.s(root).bg & 0xff != 0 { self.s(root).bg } else { body.map(|b| self.s(b).bg).unwrap_or(0) };
        if canvas & 0xff != 0 { self.out.items.insert(0, Item::Rect { x: 0, y: 0, w: self.vw, h: total, color: canvas }); }
        let us = t_run.elapsed().as_secs_f64() * 1e6;
        crate::jit::t25::fire(self, us);
        crate::jit::t25::fire_pristine(self, us);
        total
    }

    /// Move every record laid out in a span — paint items, boxes AND queued out-of-flow boxes' static positions — as one
    /// translation. Every "laid out here, moved there" path goes through this, so no record kind can be left behind.
    fn shift_span(&mut self, it: std::ops::Range<usize>, bx: std::ops::Range<usize>, ab: std::ops::Range<usize>, dx: i32, dy: i32) {
        if dx == 0 && dy == 0 { return; }
        self.out.shift_range(it, bx, dx, dy);
        for a in &mut self.abs[ab] { a.1 += dx; a.2 += dy; }
    }

    /// Program-vector context for a display type: `@q` marks quirks-mode documents so the core can learn quirk-only rules.
    /// A hand-written rule as a switch knob: recorded with value 1; weight 0 (or −1) turns the rule off in that context.
    #[inline]
    fn rule(&self, n: u32, key: &'static str) -> bool { self.term(n, key, 1) > 0 }
    /// DOCTOR patch switch: code ported by the PATCH station (src/doctor.rs) is DORMANT by default — absent / weight 1 = the
    /// hand rule (port off), 0 = off; only weight −1 ("invert the hand rule") turns it on, and only through the core's gate.
    #[allow(dead_code)]
    fn patch(&self, n: u32, key: &'static str) -> bool { n != NONE && KNOBS_ON.with(|k| k.get()) && program().has_key(key) && self.knob(n, key) < 0 }
    /// Knob weight only (no ledger record) — for terms whose ledger entry is a tropical marginal instead of the value.
    #[inline]
    fn kw(&self, n: u32, key: &'static str) -> i32 {
        if n == NONE || !KNOBS_ON.with(|k| k.get()) { return 1; }
        self.knob(n, key)
    }
    /// The node's code slots (context, display, quirks, every feature) interned once per layout.
    pub fn codes(&self, n: u32) -> std::rc::Rc<Vec<u32>> {
        if let Some(c) = self.ccache.borrow().get(&n) { return c.clone(); }
        let disp = format!("{:?}", self.disp(n));
        let mut v = vec![intern(&if self.dom.quirks { format!("{disp}@q") } else { disp.clone() }), intern(&disp), intern(if self.dom.quirks { "1" } else { "0" })];
        v.resize(SLOT_F0 + FEATURES.len(), 0);
        for i in program().used_features() { v[SLOT_F0 + i] = intern(&node_feature(self.dom, self.st, n, FEATURES[i])); }
        let r = std::rc::Rc::new(v); self.ccache.borrow_mut().insert(n, r.clone()); r
    }
    /// Knob lookup. Mode (OMR_KNOB_MODE): interp | compiled (default) | bits | jit — all four checked identical by
    /// `core --check-compiled`. Results are memoised per (box, key) for the layout (the program and the box's features are
    /// constants during one layout: Truffle-style specialisation on observed constants, clean-room).
    fn knob(&self, n: u32, key: &'static str) -> i32 {
        let pr = program();
        if !pr.has_key(key) { return 1; }
        if let Some(w) = self.kmemo.borrow().get(&(n, key)) { return *w; }
        thread_local! { static MODE: u8 = match std::env::var("OMR_KNOB_MODE").as_deref() { Ok("interp") => 0, Ok("bits") => 2, Ok("jit") => 3, _ => 1 }; }
        let w = match MODE.with(|m| *m) {
            0 => pr.knob_at(key, &self.pctx(self.disp(n)), &|f| node_feature(self.dom, self.st, n, f)),
            2 => pr.knob_bits(key, &self.codes(n)),
            3 => pr.knob_jit(key, &self.codes(n)),
            _ => self.knob_compiled(&pr, n, key),
        };
        self.kmemo.borrow_mut().insert((n, key), w); w
    }
    fn knob_compiled(&self, pr: &Program, n: u32, key: &'static str) -> i32 {
        let disp = format!("{:?}", self.disp(n));
        let feat = |i: usize| -> String {
            if let Some(v) = self.fcache.borrow().get(&(n, i as u8)) { return v.clone(); }
            let v = node_feature(self.dom, self.st, n, FEATURES[i]); self.fcache.borrow_mut().insert((n, i as u8), v.clone()); v
        };
        pr.knob_fast(key, &disp, self.dom.quirks, &feat)
    }
    #[inline]
    fn note(&self, n: u32, key: &'static str, v: i32) { if LEDGER_ON.with(|o| o.get()) { LEDGER.with(|l| l.borrow_mut().push((n, key, v))); } }
    #[inline]
    /// AST-path marker (author 10-06 "the box tree and the code AST share the parent-tree format"): the code branch that computes box
    /// n is recorded in the term ledger as `path.<branch>` (value 0), so each box carries the code path that laid it out
    #[inline] fn mark(&self, n: u32, key: &'static str) { if LEDGER_ON.with(|o| o.get()) { LEDGER.with(|l| l.borrow_mut().push((n, key, 0))); } }
    fn term(&self, n: u32, key: &'static str, v: i32) -> i32 {
        if LEDGER_ON.with(|o| o.get()) { LEDGER.with(|l| l.borrow_mut().push((n, key, v))); }
        if n == NONE || !KNOBS_ON.with(|k| k.get()) { return v; }
        v * self.knob(n, key)
    }
    fn pctx(&self, d: Display) -> String { if self.dom.quirks { format!("{d:?}@q") } else { format!("{d:?}") } }

    fn cb_node(&self) -> u32 { *self.pos_stack.last().unwrap_or(&NONE) }

    fn place_abs(&mut self, n: u32, sx: i32, sy: i32, cbn: u32, cb_border: Option<[i32; 4]>) {
        let s = self.s(n).clone();
        // containing block: padding box of the nearest positioned ancestor; fixed / none → the viewport
        let (cx, cy, cw, ch) = match (s.position, cb_border) {
            (3, _) | (_, None) => (0, 0, self.vw, self.vh),
            (_, Some(b)) => { let c = self.s(cbn); (b[0] + c.border_w[3], b[1] + c.border_w[0], b[2] - c.border_w[1] - c.border_w[3], b[3] - c.border_w[0] - c.border_w[2]) }
        };
        let (l, r, t, bo) = (res(s.inset[3], cw), res(s.inset[1], cw), res(s.inset[0], ch), res(s.inset[2], ch));
        let (ml, mr, mt, mb) = (res0(s.margin[3], cw), res0(s.margin[1], cw), res0(s.margin[0], cw), res0(s.margin[2], cw));
        let frame = self.hframe(&s, cw);
        let w = match (res(s.width, cw), l, r) {
            (None, Some(l), Some(r)) if matches!(s.width, Len::Auto) => (cw - l - r - ml - mr).max(0),
            _ => self.fit_width(&s, n, cw),
        };
        let _ = frame;
        let w = self.clamp_w(&s, w, cw);
        let x = match (l, r) { (Some(l), _) => cx + l + ml, (None, Some(r)) => cx + cw - r - mr - w, _ => sx + ml };
        let y = match t { Some(t) => cy + t + mt, None => if bo.is_some() { cy } else { sy + mt } };
        crate::why!(n, "abs", "containing block {} at ({}, {}) {}×{}; insets l {:?} r {:?} t {:?} b {:?}; static ({}, {}); width {} → at ({}, {})",
            if s.position == 3 || cb_border.is_none() { "viewport".to_string() } else { format!("node {cbn} padding box") }, crate::why::px(cx), crate::why::px(cy), crate::why::px(cw), crate::why::px(ch),
            l.map(crate::why::px), r.map(crate::why::px), t.map(crate::why::px), bo.map(crate::why::px), crate::why::px(sx), crate::why::px(sy), crate::why::px(w), crate::why::px(x), crate::why::px(y));
        if res(s.height, ch).is_none() { if let (Some(t), Some(b)) = (t, bo) { self.forced_h = Some((n, (ch - t - b - mt - mb).max(0))); } }
        let saved = std::mem::take(&mut self.floats);
        let it = self.out.items.len();
        let bx = self.out.boxes.len();
        let ab = self.abs.len();
        self.cbh.push(Some(ch));
        let h = self.block_box(n, x, y, w, true);
        self.cbh.pop();
        if t.is_none() { if let Some(b) = bo { let (ie, be, ae) = (self.out.items.len(), self.out.boxes.len(), self.abs.len()); self.shift_span(it..ie, bx..be, ab..ae, 0, cy + ch - b - mb - h - y); } }
        self.floats = saved;
    }

    /// Apply min-width / max-width to a border-box width (CSS 2.2 §10.4), for every sizing path.
    fn clamp_w(&self, s: &Style, w: i32, cw: i32) -> i32 {
        let frame = if s.border_box { 0 } else { self.hframe(s, cw) };
        let mut w = w;
        if let Some(mx) = res(s.max_w, cw) { w = w.min(mx + frame); }
        if let Some(mn) = res(s.min_w, cw) { w = w.max(mn + frame); }
        w.max(0)
    }

    fn hframe(&self, s: &Style, cw: i32) -> i32 {
        res0(s.padding[1], cw) + res0(s.padding[3], cw) + s.border_w[1] + s.border_w[3]
    }

    /// Border-box width of a shrink-to-fit box (floats, inline-blocks, abs boxes, flex static positions): the specified
    /// width, an intrinsic keyword, a replaced element's size, else shrink-to-fit — one rule for every such path.
    fn fit_width(&mut self, s: &Style, c: u32, cw: i32) -> i32 {
        let frame = self.hframe(s, cw);
        match s.width {
            Len::MinContent => self.intrinsic_w(c).0,
            Len::MaxContent => self.intrinsic_w(c).1,
            Len::FitContent => self.shrink_to_fit(c, cw),
            _ => match res(s.width, cw) {
                Some(w) => if s.border_box { w } else { w + frame },
                None => match self.replaced(c) { Some((iw, _)) => iw + frame, None => self.shrink_to_fit(c, cw) },
            },
        }
    }

    /// Shrink-to-fit width (CSS 2.2 §10.3.5): min(max(min-content, available), max-content), border box.
    fn shrink_to_fit(&mut self, n: u32, avail: i32) -> i32 {
        self.mark(n, "path.shrink_to_fit");
        let (mn, mx) = self.intrinsic_w(n);
        let s = self.s(n);
        let m = res0(s.margin[1], avail) + res0(s.margin[3], avail);
        mx.min((avail - m).max(mn)).max(0)
    }

    /// (min-content, max-content) border-box widths.
    fn intrinsic_w(&mut self, n: u32) -> (i32, i32) {
        self.mark(n, "path.intrinsic_w");
        if let Some(&v) = self.intrinsic.get(&n) { return v; }
        let s = self.s(n).clone();
        let frame = self.hframe(&s, 0);
        let r = if let Some(w) = self.ratio_width(&s, n) { (w, w) } else if let Some(w) = res(s.width, 0).filter(|_| !matches!(s.width, Len::Pct(_))) {
            let w = w + if s.border_box { 0 } else { frame };
            (if matches!(s.max_w, Len::Pct(_) | Len::Mix(..)) && self.replaced(n).is_some() { 0 } else { w }, w)
        } else if let Some((iw, _)) = self.replaced(n) {
            cov(line!());
            // a replaced box sized by a percentage is compressible: min-content contribution 0 (CSS Sizing 3 §5.2.2)
            let pct = |l: Len| matches!(l, Len::Pct(_) | Len::Mix(..));
            (if pct(s.width) || pct(s.max_w) { 0 } else { iw + frame }, iw + frame)
        } else if matches!(s.display, Display::Table | Display::InlineTable) && !self.table_rows(n).is_empty() {
            cov(line!());
            // tables: per-column min/max over single-span cells, spanning cells only widen what they must (CSS 2.2 §17.5.2.2)
            let rows = self.table_rows(n);
            let ncol = rows.iter().map(|r| r.1.iter().map(|&c| self.colspan(c)).sum::<usize>()).max().unwrap_or(0);
            let spacing = self.css_spacing(n);
            let (mut cmn, mut cmx) = (vec![0i32; ncol], vec![0i32; ncol]);
            let mut spans: Vec<(usize, usize, i32, i32)> = Vec::new();
            for (_, cells) in &rows {
                cov(line!());
                let mut col = 0;
                for &c in cells {
                    cov(line!());
                    let sp = self.colspan(c).min(ncol.saturating_sub(col)).max(1);
                    let (a, b) = self.intrinsic_w(c);
                    let cs = self.s(c).clone();
                    let b = match cs.width { Len::Px(w) => (if cs.border_box { w } else { w + self.hframe(&cs, 0) }).max(a), _ => b };
                    if sp == 1 { if col < ncol { cmn[col] = cmn[col].max(a); cmx[col] = cmx[col].max(b); } } else { spans.push((col, sp, a, b)); }
                    col += sp;
                }
            }
            for (col, sp, a, b) in spans {
                cov(line!());
                let end = (col + sp).min(ncol);
                let gaps = spacing * (sp as i32 - 1);
                let (hm, hx): (i32, i32) = (cmn[col..end].iter().sum::<i32>() + gaps, cmx[col..end].iter().sum::<i32>() + gaps);
                if a > hm { let add = (a - hm) / sp as i32; for k in col..end { cmn[k] += add; } }
                if b > hx { let add = (b - hx) / sp as i32; for k in col..end { cmx[k] += add; } }
            }
            let sp_total = spacing * (ncol as i32 + 1);
            (cmn.iter().sum::<i32>() + sp_total + frame, cmx.iter().sum::<i32>() + sp_total + frame)
        } else if matches!(s.display, Display::Grid | Display::InlineGrid) && s.grid_cols != 0 {
            cov(line!());
            // grid container with explicit columns (CSS Grid §12, clean-room; DOCTOR open card from justify-items): fixed tracks
            // keep their size, auto-ish tracks take the largest contribution of the items placed in them, flexible tracks get
            // the largest per-fr share times their factor (§12.7.1 "find the size of an fr"; a spanning item divides its
            // contribution over the fr of the tracks it spans), plus the column gaps. Items auto-flow row by row.
            let fs = s.font_size;
            let gap = res0(s.gap[1], 0);
            let cols = parse_tracks(&self.st.families[s.grid_cols as usize], 0, fs, gap);
            let nc = cols.len().max(1);
            let fr_of = |t: &Track| -> i32 { match t { Track::Fr(f) => *f, Track::MinMax(_, b) => if let Track::Fr(f) = **b { f } else { 0 }, _ => 0 } };
            let fixed_of = |t: &Track| -> Option<i32> { match t { Track::Fixed(v) => Some(*v), Track::MinMax(a, b) => if let (Track::Fixed(x), Track::Fixed(y)) = (&**a, &**b) { Some(*x.max(y)) } else { None }, _ => None } };
            let (mut tmn, mut tmx) = (vec![0i32; nc], vec![0i32; nc]);
            let (mut fr_mn, mut fr_mx) = (0i64, 0i64); // largest per-fr share (×1000 for precision)
            let kids: Vec<u32> = self.flat_children(n).into_iter().filter(|&c| !(self.dom.nodes[c as usize].kind == Kind::Text && self.dom.text(c).trim().is_empty()) && !self.is_abs(c) && self.disp(c) != Display::None).collect();
            let mut cur = 0usize;
            for c in kids {
                cov(line!());
                let mut span = 1usize; let mut start: Option<usize> = None;
                if self.dom.nodes[c as usize].kind == Kind::Element {
                    cov(line!());
                    let is = self.s(c);
                    if is.grid_col != 0 { let (a, b) = parse_place(&self.st.families[is.grid_col as usize], nc as i32 + 1, &HashMap::new(), true, &HashMap::new()); start = a; span = b.max(1); }
                }
                let span = span.min(nc);
                let col = match start { Some(k) => k.min(nc - span), None => { if cur + span > nc { cur = 0; } let k = cur; cur = (cur + span) % nc; k } };
                let (a, b) = if self.dom.nodes[c as usize].kind == Kind::Text { self.text_widths(c, n) } else { let (a, b) = self.intrinsic_w(c); let cs = self.s(c); let m = res0(cs.margin[1], 0) + res0(cs.margin[3], 0); (a + m, b + m) };
                let gaps = gap * (span as i32 - 1);
                let frs: i32 = (col..col + span).map(|k| fr_of(&cols[k.min(cols.len().saturating_sub(1))])).sum();
                let fixed: i32 = (col..col + span).filter_map(|k| cols.get(k).and_then(|t| fixed_of(t))).sum();
                if frs > 0 {
                    cov(line!());
                    fr_mn = fr_mn.max(((a - fixed - gaps).max(0) as i64) * 1000 / frs as i64);
                    fr_mx = fr_mx.max(((b - fixed - gaps).max(0) as i64) * 1000 / frs as i64);
                } else if span == 1 && fixed_of(cols.get(col).unwrap_or(&Track::Auto)).is_none() {
                    cov(line!());
                    tmn[col] = tmn[col].max(a); tmx[col] = tmx[col].max(b);
                }
            }
            let minmax_base = self.patch(n, "patch.grid_minmax_base");
            let (mut mn, mut mx) = (gap * (nc as i32 - 1), gap * (nc as i32 - 1));
            for k in 0..nc {
                cov(line!());
                let t = cols.get(k).unwrap_or(&Track::Auto);
                // minmax(a, b) with both fixed (CSS Grid §12.4/§12.6): the base size is a, the growth limit max(a, b); under a
                // min-content constraint there is no free space to maximize into, so the min-content is a (ebay card
                // `minmax(120px,300px)`: min-content 120, the card stretches to its 227 px track; ours took 300 for both)
                if let (Track::MinMax(lo, _), Some(v), true) = (t, fixed_of(t), minmax_base) { if let Track::Fixed(lo) = **lo { mn += lo; mx += v; continue; } }
                if let Some(v) = fixed_of(t) { mn += v; mx += v; }
                else if fr_of(t) > 0 { mn += (fr_mn * fr_of(t) as i64 / 1000) as i32; mx += (fr_mx * fr_of(t) as i64 / 1000) as i32; }
                else { mn += tmn[k]; mx += tmx[k]; }
            }
            (mn + frame, mx + frame)
        } else {
            cov(line!());
            let (mut mn, mut mx) = (0i32, 0i32);
            let (mut line_mn, mut line_mx) = (0i32, 0i32);
            // program vector: the line's max-content is a ternary-weighted sum of named terms; the weights per container
            // context come from the core's program (OMR_PROGRAM), default = the hand-written rule (all +1)
            let mut terms = [0i32; INLINE_TERMS];
            let w = program().inline_weights(&self.pctx(s.display));
            let flush = |terms: &mut [i32; INLINE_TERMS]| -> i32 { let v: i32 = terms.iter().zip(w.iter()).map(|(t, k)| t * *k as i32).sum(); *terms = [0; INLINE_TERMS]; v };
            let kids: Vec<u32> = self.dom.children(n).collect();
            let row_flex = matches!(s.display, Display::Flex | Display::InlineFlex) && s.flex_dir < 2;
            let col_flex = matches!(s.display, Display::Flex | Display::InlineFlex) && s.flex_dir >= 2;
            let is_row = s.display == Display::TableRow;
            let mut ws_pending = false;
            let mut n_items = 0i32;
            let mut seg = Seg::empty(false);   // algebra: the current line's min-content run
            let mut lines_mn = 0i32;
            let space_w = { let f = self.font(&s); self.fonts.advance(f, ' ', s.font_size).2 + s.letter_spacing };
            for c in kids {
                cov(line!());
                let d = self.disp(c);
                if d == Display::None || self.is_abs(c) { continue; } // out-of-flow boxes never size their container
                let k = self.dom.nodes[c as usize].kind;
                if row_flex && !(k == Kind::Text && self.dom.text(c).trim().is_empty()) { n_items += 1; }
                if col_flex {
                    cov(line!());
                    // column flex: every item (text runs too) is its own row → widths take the max, never the sum
                    let (a, b) = if k == Kind::Text { self.text_widths(c, n) } else { let (a, b) = self.intrinsic_w(c); let cs = self.s(c); let m = res0(cs.margin[1], 0) + res0(cs.margin[3], 0); (a + m, b + m) };
                    if a != 0 || b != 0 { crate::why!(n, "intrinsic", "  ⊕ column-flex item {} <{}>: ({} , {})", c, if k == Kind::Text { "text" } else { self.dom.tag(c) }, crate::why::px(a), crate::why::px(b)); }
                    mn = mn.max(a); mx = mx.max(b);
                } else if k == Kind::Text {
                    cov(line!());
                    let t = self.dom.text(c);
                    if t.trim().is_empty() && !row_flex && !is_row && !matches!(s.white_space, 1 | 3) {
                        cov(line!());
                        // collapsible whitespace between inline items = one space, only if content precedes it on the line
                        if line_mx > 0 { ws_pending = true; }
                        continue;
                    }
                    // collapsible spaces between pieces count once: a pending trailing space is dropped when this text
                    // brings its own leading space (text_widths counts that one)
                    let lead_ws = t.starts_with(char::is_whitespace);
                    let trail_ws = t.ends_with(char::is_whitespace) && !matches!(s.white_space, 1 | 3);
                    if ws_pending && !lead_ws { line_mx += space_w; terms[3] += space_w; }
                    ws_pending = false;
                    let (a, b) = self.text_widths(c, n);
                    line_mn = line_mn.max(a);
                    let lead_part = if lead_ws && !t.trim().is_empty() { space_w } else { 0 };
                    terms[0] += b - lead_part;
                    if line_mx == 0 { terms[1] += lead_part; } else { terms[2] += lead_part; }
                    line_mx += b;
                    if trail_ws && !row_flex && !is_row { ws_pending = true; }
                    if self.algebra && !row_flex && !is_row { let sg = self.text_seg(c, n); seg = Seg::cat(seg, sg); }
                } else if self.dom.tag(c) == "br" {
                    ws_pending = false;
                    mx = mx.max(flush(&mut terms)); line_mx = 0;
                    lines_mn = lines_mn.max(seg.mn); seg = Seg::empty(false);
                } else if is_block_level(d) && !row_flex && !is_row && self.s(c).float == 0 {
                    cov(line!());
                    mx = mx.max(flush(&mut terms)); line_mx = 0;
                    lines_mn = lines_mn.max(seg.mn); seg = Seg::empty(false);
                    let (a, b) = self.intrinsic_w(c);
                    // a table caption never widens its table beyond its own min-content (CSS Tables 3 §3.9)
                    let b = if d == Display::TableCaption && matches!(s.display, Display::Table | Display::InlineTable) { a } else { b };
                    let cs = self.s(c);
                    let m = res0(cs.margin[1], 0) + res0(cs.margin[3], 0);
                    crate::why!(n, "intrinsic", "  ⊕ block child {} <{} .{}>: ({} , {}) incl. margins {}", c, self.dom.tag(c), self.dom.attr(c, "class").unwrap_or(""), crate::why::px(a + m), crate::why::px(b + m), crate::why::px(m));
                    mn = mn.max(a + m); mx = mx.max(b + m);
                } else {
                    cov(line!());
                    let (a, b) = self.intrinsic_w(c);
                    let cs = self.s(c);
                    let m = res0(cs.margin[1], 0) + res0(cs.margin[3], 0);
                    if ws_pending && !row_flex && !is_row && self.s(c).float == 0 { line_mx += space_w; terms[5] += space_w; }
                    ws_pending = false;
                    crate::why!(n, "intrinsic", "  {} item {} <{} .{}>: ({} , {}) incl. margins {}", if row_flex || is_row { "⊗" } else { "·" }, c, self.dom.tag(c), self.dom.attr(c, "class").unwrap_or(""), crate::why::px(a + m), crate::why::px(b + m), crate::why::px(m));
                    if row_flex && self.algebra && s.flex_wrap { line_mn = line_mn.max(a + m); } // a wrapping line's min-content is its widest item
                    else if row_flex || is_row { line_mn += a + m; } else { line_mn = line_mn.max(a + m); }
                    line_mx += b + m;
                    terms[4] += b + m;
                    if self.algebra && !row_flex && !is_row { let sg = self.inline_seg(c, n); seg = Seg::cat(seg, sg); }
                }
            }
            // row flex: column gaps sit between items (Flexbox §9.9.1 sums the items plus the gaps)
            if row_flex && n_items > 1 { if let Len::Px(g) = s.gap[1] { if !(self.algebra && s.flex_wrap) { line_mn += g * (n_items - 1); } line_mx += g * (n_items - 1); terms[6] += g * (n_items - 1); } }
            if self.algebra && !row_flex && !is_row && !col_flex {
                cov(line!());
                lines_mn = lines_mn.max(seg.mn);
                crate::why!(n, "intrinsic", "inline runs (Seg monoid): widest unbreakable run {} (per-item max was {})", crate::why::px(lines_mn), crate::why::px(line_mn));
                line_mn = lines_mn;
            }
            mn = mn.max(line_mn);
            let _ = line_mx;
            mx = mx.max(flush(&mut terms));
            (mn + frame, mx.max(mn) + frame)
        };
        // only absolute max-widths cap intrinsic sizes; a percentage of an indefinite size behaves as `none`
        let cap = match s.max_w { Len::Px(v) => v + if s.border_box { 0 } else { frame }, _ => i32::MAX };
        let r = (r.0.min(cap), r.1.min(cap));
        // min-width floors both (and beats max-width, CSS 2.2 §10.4)
        let floor = match s.min_w { Len::Px(v) => v + if s.border_box { 0 } else { frame }, _ => 0 };
        let r = (r.0.max(floor), r.1.max(floor));
        crate::why!(n, "intrinsic", "min-content {} max-content {} (frame {}; max-width cap {}; min-width floor {})", crate::why::px(r.0), crate::why::px(r.1), crate::why::px(frame), crate::why::px(cap), crate::why::px(floor));
        if std::env::var("OMR_INTR").map_or(false, |q| self.dom.attr(n, "class").unwrap_or("").split_whitespace().any(|c| c == q) || (q == "::before" && self.dom.tag(n) == "::before")) {
            let kids: Vec<String> = self.dom.children(n).map(|c| format!("{}:{:?}", if self.dom.nodes[c as usize].kind == Kind::Text { format!("text{:?}", self.dom.text(c)) } else { self.dom.tag(c).to_string() }, self.disp(c))).collect();
            eprintln!("intrinsic <{} .{}> = ({}, {}) disp {:?} dir {} kids {:?}", self.dom.tag(n), self.dom.attr(n, "class").unwrap_or(""), r.0 / 64, r.1 / 64, s.display, s.flex_dir, kids);
        }
        self.intrinsic.insert(n, r);
        r
    }

    fn text_seg(&mut self, t: u32, parent: u32) -> Seg {
        let s = self.s(parent).clone();
        let raw = self.dom.text(t);
        let wrap = matches!(s.white_space, 0 | 3 | 4);
        if raw.trim().is_empty() { return Seg::empty(wrap && !raw.is_empty()); }
        let f = self.font(&s);
        let tt: std::borrow::Cow<str> = match s.text_transform { 1 => raw.to_uppercase().into(), 2 => raw.to_lowercase().into(), _ => raw.into() };
        let ls = s.letter_spacing;
        let (kern, brk) = (self.kern_on(parent, &s), self.patch(parent, "patch.linebreak"));
        let words: Vec<i32> = tt.split_whitespace().map(|w| piece_w(self.fonts, f, w, s.font_size, ls, kern)).collect();
        if !wrap { let (_, tot) = self.text_widths(t, parent); return Seg::solid(tot, false, false); }
        let (bs, be) = (tt.starts_with(char::is_whitespace), tt.ends_with(char::is_whitespace));
        if brk {
            cov(line!());
            // break opportunities inside words: lead = first piece, trail = last piece, min-content = widest piece
            let ps: Vec<Vec<i32>> = tt.split_whitespace().map(|w| pieces(w, true).into_iter().map(|p| piece_w(self.fonts, f, p, s.font_size, ls, kern)).collect()).collect();
            if ps.len() > 1 || ps[0].len() > 1 {
                cov(line!());
                let mn = ps.iter().flatten().copied().max().unwrap_or(0);
                return Seg { lead: ps[0][0], trail: *ps.last().unwrap().last().unwrap(), mn, solid: false, empty: false, bs, be };
            }
        }
        if words.len() == 1 { return Seg::solid(words[0], bs, be); }
        Seg { lead: words[0], trail: *words.last().unwrap(), mn: words.iter().copied().max().unwrap_or(0), solid: false, empty: false, bs, be }
    }

    /// Min-content run of one inline-level child: text and non-atomic inline boxes recurse; atomic boxes (inline-block,
    /// replaced, floats) are unbreakable with break opportunities on both sides (CSS Text 3 §5.1).
    fn inline_seg(&mut self, c: u32, parent: u32) -> Seg {
        if self.dom.nodes[c as usize].kind == Kind::Text { return self.text_seg(c, parent); }
        if self.dom.nodes[c as usize].kind != Kind::Element || self.disp(c) == Display::None || self.is_abs(c) { return Seg::empty(false); }
        let cs = self.s(c).clone();
        let m = |l: Len| res0(l, 0);
        if cs.display == Display::Inline && self.replaced(c).is_none() && !self.inline_with_block(c) && cs.float == 0 {
            cov(line!());
            if self.dom.tag(c) == "br" { return Seg::empty(true); }
            let kids: Vec<u32> = self.dom.children(c).collect();
            let mut run = Seg::empty(false);
            for k in kids { let sg = self.inline_seg(k, c); run = Seg::cat(run, sg); }
            let fl = m(cs.margin[3]) + m(cs.padding[3]) + cs.border_w[3];
            let fr = m(cs.margin[1]) + m(cs.padding[1]) + cs.border_w[1];
            return run.widen(fl, fr);
        }
        let (a, _) = self.intrinsic_w(c);
        Seg::solid(a + m(cs.margin[1]) + m(cs.margin[3]), true, true)
    }

    fn text_widths(&mut self, t: u32, parent: u32) -> (i32, i32) {
        let s = self.s(parent).clone();
        let f = self.font(&s);
        let raw = self.dom.text(t);
        let tt: std::borrow::Cow<str> = match s.text_transform { 1 => raw.to_uppercase().into(), 2 => raw.to_lowercase().into(), _ => raw.into() };
        let txt: &str = &tt;
        let ls = s.letter_spacing;
        let (_, _, sp) = self.fonts.advance(f, ' ', s.font_size);
        let sp = sp + ls;
        let (mut mn, mut tot) = (0, 0);
        let pre = matches!(s.white_space, 1 | 2);
        let (kern, brk) = (self.kern_on(parent, &s), self.patch(parent, "patch.linebreak"));
        for (k, w) in txt.split_whitespace().enumerate() {
            cov(line!());
            let ww: i32 = piece_w(self.fonts, f, w, s.font_size, ls, kern);
            mn = mn.max(if brk { pieces(w, true).into_iter().map(|p| piece_w(self.fonts, f, p, s.font_size, ls, kern)).max().unwrap_or(0) } else { ww });
            tot += ww + if k > 0 { sp } else { 0 };
        }
        if txt.starts_with(char::is_whitespace) && !txt.trim().is_empty() { tot += sp; } // whitespace-only text collapses away
        if pre { mn = tot; }
        (mn, tot)
    }

    fn replaced(&self, n: u32) -> Option<(i32, i32)> {
        let tag = self.dom.tag(n);
        if !matches!(tag, "img" | "video" | "canvas" | "iframe" | "embed" | "object" | "svg" | "input" | "button" | "select" | "textarea" | "meter" | "progress") { return None; }
        let s = self.s(n);
        // meter / progress: Chrome-observed intrinsic size (oracle_synth, exhaustive over font sizes 6–48 px): 5em × 1em and 10em × 1em
        if matches!(tag, "meter" | "progress") {
            if !self.patch(n, "patch.meter_progress_size") { return None; }
            let fs = s.font_size;
            let w = res(s.width, 0).filter(|_| matches!(s.width, Len::Px(_))).unwrap_or(if tag == "meter" { 5 * fs } else { 10 * fs });
            let h = res(s.height, 0).filter(|_| matches!(s.height, Len::Px(_))).unwrap_or(fs);
            return Some((w, h));
        }
        let attr = |a: &str| self.dom.attr(n, a).and_then(|v| v.trim().trim_end_matches("px").parse::<f32>().ok()).map(|v| (v * FX as f32) as i32);
        let mut nat = if tag == "img" || tag == "svg" { (self.img_size)(n).map(|(w, h)| (w as i32 * FX, h as i32 * FX)) } else { None };
        if matches!(tag, "input" | "select" | "textarea") {
            // Chrome black-box laws apply where they were measured: the UA default control font (13.333 px)
            let law_ok = (s.font_size - 853).abs() <= 2 && self.patch(n, "patch.oracle_laws");
            let hframe = res0(s.padding[1], 0) + res0(s.padding[3], 0) + s.border_w[1] + s.border_w[3];
            let vframe = res0(s.padding[0], 0) + res0(s.padding[2], 0) + s.border_w[0] + s.border_w[2];
            // form controls size from their font (HTML §15.5.15–16): text fields `size` × average char, buttons their label
            let f = self.fonts.resolve(&self.st.families[s.font_family as usize], s.font_weight, s.italic);
            let lh = self.fonts.normal_line(f, s.font_size);
            let text_w = |t: &str| -> i32 { t.chars().map(|c| self.fonts.advance(f, c, s.font_size).2).sum() };
            let avg = self.fonts.advance(f, '0', s.font_size).2.max(FX);
            let ty = self.dom.attr(n, "type").unwrap_or("text").to_ascii_lowercase();
            nat = Some(match (tag, ty.as_str()) {
                ("input", "checkbox") | ("input", "radio") => (13 * FX, 13 * FX),
                ("input", "submit") | ("input", "button") | ("input", "reset") => {
                    let label = self.dom.attr(n, "value").unwrap_or(match ty.as_str() { "submit" => "Submit", "reset" => "Reset", _ => "" });
                    (text_w(label) + 8 * FX, lh)
                }
                ("input", "image") => return None,
                ("input", "range") => (129 * FX, 16 * FX),
                ("input", "color") => (50 * FX, 27 * FX),
                ("input", _) => { let sz = self.dom.attr(n, "size").and_then(|v| v.trim().parse::<i32>().ok()).unwrap_or(20).clamp(1, 500);
                    // Chrome law (oracle, exhaustive size 1–120): border box = law_input_size_width(size), at the UA default font only
                    if law_ok { ((oracle_laws::law_input_size_width(sz as i64) as i32) - hframe, lh) } else { (sz * avg, lh) } }
                ("select", _) => {
                    let longest = self.dom.children(n).filter(|&c| self.dom.tag(c) == "option").map(|c| self.dom.children(c).map(|t| text_w(self.dom.text(t).trim())).sum::<i32>()).max().unwrap_or(0);
                    (longest + 24 * FX, lh)
                }
                _ => { // textarea
                    let cols = self.dom.attr(n, "cols").and_then(|v| v.trim().parse::<i32>().ok()).unwrap_or(20).clamp(1, 500);
                    let rows = self.dom.attr(n, "rows").and_then(|v| v.trim().parse::<i32>().ok()).unwrap_or(2).clamp(1, 500);
                    // Chrome laws (oracle, exhaustive cols 1–120 / rows 1–40): border boxes, at the UA default font only
                    if law_ok { ((oracle_laws::law_textarea_width(cols as i64) as i32) - hframe, (oracle_laws::law_textarea_height(rows as i64) as i32) - vframe) }
                    else { (cols * avg + 16 * FX, rows * lh) }
                }
            });
        }
        let (dw, dh) = match tag {
            "iframe" | "video" | "embed" | "object" => (300 * FX, 150 * FX), "canvas" => (300 * FX, 150 * FX),
            "input" | "select" => (150 * FX, 21 * FX), "button" => return None, "textarea" => (180 * FX, 36 * FX),
            "svg" => (300 * FX, 150 * FX), _ => (0, 0),
        };
        let (aw, ah) = (attr("width"), attr("height"));
        // a failed <img> with no alt text shows the 16×16 broken-image icon (lazy images are simply not loaded yet: 0×0)
        if tag == "img" && nat.is_none() && aw.is_none() && ah.is_none() && self.dom.attr(n, "alt").is_none()
            && self.dom.attr(n, "src").map_or(false, |v| !v.is_empty()) && self.dom.attr(n, "loading") != Some("lazy") {
            nat = Some((16 * FX, 16 * FX));
        }
        let (nw, mut nh) = nat.unwrap_or((aw.unwrap_or(dw), ah.unwrap_or(dh)));
        // aspect-ratio on a replaced element (CSS Sizing 4 §5.1): a plain <ratio> replaces the natural ratio; `auto <ratio>` only fills
        // in when there is none (bbc: absolutely positioned img, width 100%, aspect-ratio 16/9 → Chrome 346.5 px, natural ratio gave 90)
        if s.aspect > 0 && nw > 0 && (!s.aspect_auto || nat.is_none()) { nh = (nw as i64 * 1000 / s.aspect as i64) as i32; }
        // width/height attributes reach us as presentational hints in the computed style (an author `width: auto` beats them)
        let w = res(s.width, 0).filter(|_| matches!(s.width, Len::Px(_)));
        let h = res(s.height, 0).filter(|_| matches!(s.height, Len::Px(_)));
        Some(match (w, h) {
            (Some(w), Some(h)) => (w, h),
            (Some(w), None) => (w, if nw > 0 { (w as i64 * nh as i64 / nw as i64) as i32 } else { nh }),
            (None, Some(h)) => (if nh > 0 { (h as i64 * nw as i64 / nh as i64) as i32 } else { nw }, h),
            (None, None) => (nw, nh),
        })
    }

    // ───────────── block formatting ─────────────

    /// Lay out element `n` as a block-level box at (x, y) inside a containing block of width `cw`.
    /// Returns the margin-box height consumed.
    fn block(&mut self, n: u32, x: i32, y: i32, cw: i32, root: bool) -> i32 {
        let s = self.s(n).clone();
        let mt = self.top_margin(n, cw);
        let mb = self.bottom_margin(n, cw);
        let (ml, mr, w) = self.hsizes(&s, n, cw);
        self.pad_cb = Some((n, cw));
        let h = self.block_box(n, x + ml, y + mt, w, root);
        let _ = mr;
        mt + h + mb
    }

    /// Resolve horizontal margins and border-box width (CSS 2.2 §10.3.3).
    /// The border-box width an auto-width box takes through its aspect-ratio from a definite (px) height (CSS Sizing 4 §5.1:
    /// the ratio-dependent axis; Chrome does it for blocks, inline-blocks, floats, flex items and abspos alike — MDN's 0.8em
    /// `aspect-ratio: 300/167` icons: 23 px, ours 0). The ratio applies to the box-sizing box.
    fn ratio_width(&self, s: &Style, n: u32) -> Option<i32> {
        if s.aspect <= 0 || !matches!(s.width, Len::Auto) || self.replaced(n).is_some() || !self.patch(n, "patch.aspect_width") { return None; }
        let Len::Px(h) = s.height else { return None };
        let frame = self.hframe(s, 0);
        if s.border_box { Some((h as i64 * s.aspect as i64 / 1000) as i32) }
        else { Some((h as i64 * s.aspect as i64 / 1000) as i32 + frame) }
    }

    fn hsizes(&mut self, s: &Style, n: u32, cw: i32) -> (i32, i32, i32) {
        let frame = self.hframe(s, cw);
        let content_w = match s.width {
            Len::MinContent => Some(self.intrinsic_w(n).0),
            Len::MaxContent => Some(self.intrinsic_w(n).1),
            Len::FitContent => { let m = res0(s.margin[1], cw) + res0(s.margin[3], cw); let (a, b) = self.intrinsic_w(n); Some(b.min((cw - m).max(a))) }
            _ => None,
        };
        let mut w = content_w.or_else(|| res(s.width, cw).map(|w| if s.border_box { w } else { w + frame }));
        // an auto-width table is as wide as its columns need, up to the available width (CSS 2.2 §17.5.2.2)
        if w.is_none() && matches!(s.display, Display::Table | Display::InlineTable) && self.rule(n, "rule.table_shrink_to_fit") { w = Some(self.shrink_to_fit(n, cw)); }
        if w.is_none() && self.rule(n, "rule.replaced_width") { if let Some((iw, _)) = self.replaced(n) { w = Some(iw + frame); } }
        if w.is_none() { w = self.ratio_width(s, n); }
        if let (Some(mx), Some(ww), true) = (res(s.max_w, cw), w, self.rule(n, "rule.max_width")) { w = Some(ww.min(if s.border_box { mx } else { mx + frame })); }
        let ml = res(s.margin[3], cw);
        let mr = res(s.margin[1], cw);
        match w {
            None => {
                cov(line!());
                let (l, r) = (self.term(n, "size.margin_left", ml.unwrap_or(0)), self.term(n, "size.margin_right", mr.unwrap_or(0)));
                let mut bw = (cw - l - r).max(0);
                if let Some(mx) = res(s.max_w, cw) { let mx = if s.border_box { mx } else { mx + frame }; if bw > mx { bw = mx; } }
                if let Some(mn) = res(s.min_w, cw) { bw = bw.max(if s.border_box { mn } else { mn + frame }); }
                if bw < (cw - l - r) && ml.is_none() && mr.is_none() && self.rule(n, "rule.center_auto_margins") { let free = cw - bw; return (free / 2, free - free / 2, bw); }
                (l, r, bw)
            }
            Some(mut bw) => {
                cov(line!());
                if let Some(mn) = res(s.min_w, cw) { bw = bw.max(if s.border_box { mn } else { mn + frame }); }
                let free = cw - bw;
                match (ml, mr) {
                    (None, None) => (free / 2, free - free / 2, bw),
                    (None, Some(r)) => (free - r, r, bw),
                    (Some(l), _) => (l, free - l, bw),
                }
            }
        }
    }

    /// Per-node subtree content hash (reverse preorder: children first): kind, tag, attributes, text, style id.
    fn subtree_hashes(&mut self) {
        let d = self.dom; let n = d.nodes.len();
        let mut sub = vec![0u64; n];
        for i in (0..n).rev() {
            cov(line!());
            let nd = d.nodes[i];
            let mut h = lmix(nd.kind as u64 + 1);
            match nd.kind {
                Kind::Element => {
                    cov(line!());
                    h = lbytes(h, d.tag(i as u32).as_bytes());
                    // data-ir = svrt/uiir wire numbering (renumbers on every render); layout never reads it
                    for a in d.attr_list(i as u32) { let nm = &*d.names[a.name as usize].local; if nm == "data-ir" { continue; } h = lbytes(h, nm.as_bytes()); h = lbytes(h, d.span_str(a.val).as_bytes()); }
                    h = lmix(h ^ self.st.ids[i] as u64);
                }
                Kind::Text => h = lbytes(h, d.text(i as u32).as_bytes()),
                _ => {}
            }
            for c in d.children(i as u32) { h = lmix(h ^ sub[c as usize].wrapping_mul(0x9e3779b97f4a7c15)); }
            sub[i] = lmix(h ^ (nd.end as u64 - i as u64));
        }
        self.sub = sub;
    }

    /// Border box at (x, y) with border-box width w. Returns border-box height. With a memo, BFC-root subtrees go
    /// through the layout change trit (see LayoutMemo).
    fn block_box(&mut self, n: u32, x: i32, y: i32, w: i32, root: bool) -> i32 {
        if self.memo.is_none() || root || INJECT.with(|i| !i.borrow().is_empty()) || geo_any(self.dom) { return self.block_box_full(n, x, y, w, root); }
        if matches!(self.pad_cb, Some((m, cb)) if m == n && cb != w) && self.s(n).padding.iter().any(|p| matches!(p, Len::Pct(_))) && self.patch(n, "patch.pad_pct_cb") {
            return self.block_box_full(n, x, y, w, root);
        }
        let s = self.s(n);
        let par = self.dom.nodes[n as usize].parent;
        let pel = par != NONE && self.dom.nodes[par as usize].kind == Kind::Element;
        let flex_item = pel && matches!(self.s(par).display, Display::Flex | Display::InlineFlex | Display::Grid | Display::InlineGrid);
        let new_bfc = flex_item || s.float != 0 || matches!(s.position, 2 | 3) || s.overflow != 0 || matches!(s.display, Display::InlineBlock | Display::TableCell | Display::Flex | Display::Grid | Display::Table);
        let size = self.dom.nodes[n as usize].end.saturating_sub(n);
        // normal-flow (non-BFC) blocks join the trit when no outer float can intrude (and, checked after, none leaks out)
        // (a float that ends at or above this box's top cannot intrude into it)
        let nf0 = self.floats.len();
        let flow_ok = !new_bfc && self.floats.iter().all(|f| f.y1 <= y) && std::env::var("OMR_INCR_BFC_ONLY").is_err();
        { let m = self.memo.as_mut().unwrap(); m.calls += 1;
          let r = if !(new_bfc || flow_ok) { if new_bfc { 0 } else if !self.floats.iter().all(|f| f.y1 <= y) { 1 } else { 0 } } else if size < 2 { 2 } else { 3 };
          if !(new_bfc || flow_ok) || size < 2 || matches!(self.forced_h, Some((f, _)) if f == n) { m.rej[r] += 1; } }
        if !(new_bfc || flow_ok) || size < 2 || matches!(self.forced_h, Some((f, _)) if f == n) { return self.block_box_full(n, x, y, w, root); }
        let (mut eidx, mut ecnt) = (0u64, 0u64);
        if pel { for c in self.dom.children(par) { if self.dom.nodes[c as usize].kind == Kind::Element { ecnt += 1; if c == n { eidx = ecnt; } } } }
        let ph = self.cbh.last().copied().flatten();
        let key = lkey(&[self.sub[n as usize], x.rem_euclid(FX) as u64, y.rem_euclid(FX) as u64, w as u32 as u64,
            ph.map_or(u64::MAX, |v| v as u32 as u64), flex_item as u64, if pel { self.st.ids[par as usize] as u64 } else { u64::MAX },
            if pel { lbytes(0, self.dom.tag(par).as_bytes()) } else { 0 }, eidx << 32 | ecnt, self.dom.quirks as u64,
            (self.vw as u32 as u64) << 32 | self.vh as u32 as u64, new_bfc as u64]);
        let memo = self.memo.as_mut().unwrap();
        if let Some(e) = memo.map.get(&key) {
            cov(line!());
            memo.hits += 1; memo.reused_nodes += size as usize;
            for it in &e.items {
                cov(line!());
                let mut it = it.clone(); it.shift(x, y);
                if let Item::Image { node, .. } = &mut it { *node += n; }
                self.out.items.push(it);
            }
            for (bn, b) in &e.boxes { self.out.boxes.push((bn + n, [b[0] + x, b[1] + y, b[2], b[3]])); }
            if let Some(lb) = e.lb { self.last_base = lb.map(|v| v + y); }
            return e.h;
        }
        memo.misses += 1;
        let (it0, bx0, ab0, lb0) = (self.out.items.len(), self.out.boxes.len(), self.abs.len(), self.last_base);
        let h = self.block_box_full(n, x, y, w, root);
        if self.abs.len() == ab0 && (new_bfc || self.floats.len() == nf0) {
            cov(line!());
            let items: Vec<Item> = self.out.items[it0..].iter().map(|it| { let mut it = it.clone(); it.shift(-x, -y); if let Item::Image { node, .. } = &mut it { *node -= n; } it }).collect();
            let boxes: Vec<(u32, [i32; 4])> = self.out.boxes[bx0..].iter().map(|(bn, b)| (bn - n, [b[0] - x, b[1] - y, b[2], b[3]])).collect();
            let lb = if self.last_base != lb0 { Some(self.last_base.map(|v| v - y)) } else { None };
            let memo = self.memo.as_mut().unwrap();
            memo.stored_items += items.len();
            if memo.stored_items > LMEMO_CAP_ITEMS { memo.map.clear(); memo.stored_items = items.len(); }
            memo.map.insert(key, LEnt { items, boxes, h, lb });
        } else { self.memo.as_mut().unwrap().unstored += 1; }
        h
    }

    fn block_box_full(&mut self, n: u32, x: i32, y: i32, w: i32, root: bool) -> i32 {
        let geo = geo_of(self.dom, n); // RESTRUCTURE: the doctor's exact geometry for this box (route 2)
        let (x, y) = match geo { Some((dx, dy, _)) => (x + dx, y + dy), None => (x, y) };
        let w = match geo { Some((_, _, gw)) if gw >= 0 => gw, _ => w };
        let inj = injected(n);
        let w = inj.map(|(iw, _)| iw).unwrap_or(w);
        self.mark(n, "path.block_box");
        let _cur = CurNode::enter(n);
        let s = self.s(n).clone();
        let bg_at = self.out.items.len();
        let box_at = self.out.boxes.len(); // descendants' boxes are recorded before this box (post-order)
        let abs_at = self.abs.len();
        // CSS 2.2 §8.4: percentage padding refers to the width of the CONTAINING BLOCK, not the box's own width (peps: float
        // main, width 74 %, padding 3.2 % → Chrome 37.375 px = 3.2 % of the table's 1,168 px content box; ours took 3.2 % of 864)
        let pcb = match self.pad_cb.take() { Some((m, cb)) if m == n && self.patch(n, "patch.pad_pct_cb") => cb, _ => w };
        let (pt, pr, pb, pl) = (res0(s.padding[0], pcb), res0(s.padding[1], pcb), res0(s.padding[2], pcb), res0(s.padding[3], pcb));
        let (bt, br, bb, bl) = (s.border_w[0], s.border_w[1], s.border_w[2], s.border_w[3]);
        let cx = x + bl + pl;
        let cy = y + bt + pt;
        let cwid = (w - bl - br - pl - pr).max(0);
        let par = self.dom.nodes[n as usize].parent;
        let flex_item = par != NONE && self.dom.nodes[par as usize].kind == Kind::Element && matches!(self.s(par).display, Display::Flex | Display::InlineFlex | Display::Grid | Display::InlineGrid);
        let new_bfc = root || flex_item || s.float != 0 || matches!(s.position, 2 | 3) || s.overflow != 0 || matches!(s.display, Display::InlineBlock | Display::TableCell | Display::Flex | Display::Grid | Display::Table);
        let positioned = s.position != 0 || !matches!(s.translate, [Len::Px(0), Len::Px(0)]);
        if positioned { self.pos_stack.push(n); }
        // definite height (px, % of a definite containing block, or imposed by top+bottom) for this box and its children
        let frame_v = bt + bb + pt + pb;
        let parent_h = self.cbh.last().copied().flatten();
        let forced = match self.forced_h { Some((fnode, fh)) if fnode == n => { self.forced_h = None; Some(fh) } _ => None };
        let def_h: Option<i32> = forced.or_else(|| match s.height {
            Len::Px(v) => Some(if s.border_box { v } else { v + frame_v }),
            Len::Pct(p) => parent_h.map(|ph| { let v = (ph as i64 * p as i64 / 10000) as i32; if s.border_box { v } else { v + frame_v } }),
            // a symbolic height (cq units, min/max of % and px) is definite once its base is: evaluated against the parent's height
            Len::Expr(id) if parent_h.is_some() && self.patch(n, "patch.expr_height") =>
                crate::style::expr_eval(id, parent_h.unwrap()).map(|v| if s.border_box { v } else { v + frame_v }),
            // aspect-ratio (CSS Sizing 4 §5.1, clean-room; DOCTOR missing-feature card): an auto height follows the definite
            // width through the ratio, measured on the box-sizing box; replaced elements keep their own intrinsic ratio path
            // held back (open card, measured): items of an INLINE-flex/grid parent — bbc's 20 px live icon (inline-flex, blockified,
            // in an inline-flex centring parent) gets Chrome's height but its ancestors then lose 2 agreeing boxes (an inline-flex
            // baseline/line issue); block items of block-level flex/grid parents (55 on the corpus) gain
            Len::Auto if s.aspect > 0 && self.replaced(n).is_none() && !(flex_item && matches!(self.s(par).display, Display::InlineFlex | Display::InlineGrid))
                && !matches!(s.display, Display::InlineFlex | Display::InlineBlock | Display::InlineGrid | Display::InlineTable) => {
                let base = if s.border_box { w } else { cwid };
                let v = (base as i64 * 1000 / s.aspect as i64) as i32;
                Some(if s.border_box { v } else { v + frame_v })
            }
            _ => None,
        });
        self.cbh.push(def_h.map(|h| (h - frame_v).max(0)));
        // a query container (CSS Contain 3 §3.1) is the cq-unit base for its descendants: content width, and for `size` the
        // definite content height. Its own properties were resolved by its parent already; its own grid tracks still see it
        // (rare: cq units on the container itself would refer to the next container out)
        let cq = s.container != 0 && crate::layout::patch_on(PATCH_CQ_UNITS);
        if cq { crate::style::cq_push(cwid, if s.container == 2 { def_h.map(|h| (h - frame_v).max(0)) } else { None }); }
        let saved = if new_bfc { Some(std::mem::take(&mut self.floats)) } else { None };
        let content_h = if let Some((rw, ih)) = self.replaced(n) {
            // CSS 2.2 §10.6.2: an auto height of a replaced element with a ratio follows the USED width (width: 100% of the
            // containing block), not the natural width — media only, form controls keep their own sizing
            let ih = if matches!(s.height, Len::Auto) && rw > 0 && cwid > 0 && cwid != rw && matches!(self.dom.tag(n), "img" | "svg" | "video" | "canvas" | "iframe" | "embed" | "object")
                && self.patch(n, "patch.replaced_used_width") { (cwid as i64 * ih as i64 / rw as i64) as i32 } else { ih };
            if self.dom.tag(n) == "select" {
                // a closed <select> shows its chosen option's label (the `selected` one, else the first), centred vertically
                let opts: Vec<u32> = self.dom.children(n).flat_map(|c| if self.dom.tag(c) == "optgroup" { self.dom.children(c).collect::<Vec<_>>() } else { vec![c] }).filter(|&c| self.dom.tag(c) == "option").collect();
                let want = self.dom.attr(n, "value").map(|v| v.to_string());
                let chosen = want.as_ref().and_then(|w| opts.iter().copied().find(|&o| self.dom.attr(o, "value") == Some(w.as_str())))
                    .or_else(|| opts.iter().copied().find(|&o| self.dom.attr(o, "selected").is_some())).or_else(|| opts.first().copied());
                if let Some(o) = chosen {
                    cov(line!());
                    let texts: Vec<u32> = self.dom.children(o).filter(|&t| self.dom.nodes[t as usize].kind == Kind::Text).collect();
                    let lh = self.line_h(&s);
                    let at = cy + ((ih - lh) / 2).max(0);
                    let saved_items = self.out.items.len();
                    self.inline(n, &texts, cx + 2 * FX, at, (cwid - 22 * FX).max(FX));
                    let _ = saved_items;
                }
            } else if self.dom.tag(n) == "textarea" || (self.dom.tag(n) == "input" && matches!(self.dom.attr(n, "type").unwrap_or("text").to_ascii_lowercase().as_str(), "text" | "search" | "email" | "url" | "tel" | "number" | "password" | "")) {
                // text fields show their value, else the placeholder in a dimmed text colour (no image placeholder)
                let val = self.dom.attr(n, "value").unwrap_or("").to_string();
                let (txt, col) = if !val.is_empty() {
                    let t = if self.dom.attr(n, "type") == Some("password") { "•".repeat(val.chars().count()) } else { val };
                    (t, s.color)
                } else { (self.dom.attr(n, "placeholder").unwrap_or("").to_string(), (s.color & !0xff) | (((s.color & 0xff) * 55 / 100) & 0xff)) };
                if !txt.is_empty() { if let Some(it) = self.text_item(&s, txt.lines().next().unwrap_or(""), cx, cy, cwid, col) { self.out.items.push(it); } }
            } else {
                cov(line!());
                self.out.items.push(Item::Image { x: cx, y: cy, w: cwid, h: ih, node: n, mode: 0 });
            }
            ih
        } else {
            cov(line!());
            match s.display {
                Display::Table | Display::InlineTable => self.table(n, cx, cy, cwid),
                // legacy `display: -webkit-box; -webkit-box-orient: vertical` (+ `-webkit-line-clamp: N`): Chrome lays the content out as
                // a block container and clamps it after the Nth line (CSS Overflow 4 §5; ebay cards `line-clamp-2`, youtube titles)
                Display::Flex | Display::InlineFlex if s.webkit_box && s.box_vertical && self.patch(n, "patch.line_clamp") => {
                    let h = self.flow(n, cx, cy, cwid);
                    if s.line_clamp > 0 { h.min(s.line_clamp as i32 * self.line_h(&s)) } else { h }
                }
                Display::Flex | Display::InlineFlex => self.flex(n, cx, cy, cwid),
                Display::Grid | Display::InlineGrid => self.grid(n, cx, cy, cwid),
                _ => self.flow(n, cx, cy, cwid),
            }
        };
        self.cbh.pop();
        if cq { crate::style::cq_pop(); }
        let mut ch = match def_h { Some(h) => (h - frame_v).max(0), None => content_h };
        let pct_or_px = |l: Len| -> Option<i32> { match l { Len::Px(v) => Some(v), Len::Pct(p) => parent_h.map(|ph| (ph as i64 * p as i64 / 10000) as i32), _ => None } };
        if let Some(mn) = pct_or_px(s.min_h) { ch = ch.max(self.term(n, "box.min_h", if s.border_box { mn - frame_v } else { mn })); }
        if let Some(mx) = pct_or_px(s.max_h) { ch = ch.min(if s.border_box { mx - frame_v } else { mx }); }
        if new_bfc {
            cov(line!());
            // a BFC root grows to contain its floats
            let fb = self.floats.iter().map(|f| f.y1).max().unwrap_or(cy);
            if def_h.is_none() { ch = ch.max(self.term(n, "box.float_contain", fb - cy)); }
            self.floats = saved.unwrap();
        }
        if let Some((_, ih)) = inj { ch = (ih - frame_v).max(0); }   // injected: Chrome's border-box height wins over every clamp
        crate::why!(n, "box", "border box at ({}, {}) width {}; content height {} via {:?}{}{} → content {} + padding {}+{} + border {}+{} = height {}",
            crate::why::px(x), crate::why::px(y), crate::why::px(w), crate::why::px(content_h), s.display,
            def_h.map(|h| format!(", definite height {}", crate::why::px(h))).unwrap_or_default(),
            match (s.min_h, s.max_h) { (Len::Auto, Len::None) => String::new(), (a, b) => format!(", min-height {a:?} max-height {b:?}") },
            crate::why::px(ch), crate::why::px(pt), crate::why::px(pb), crate::why::px(bt), crate::why::px(bb), crate::why::px(bt + pt + ch + pb + bb));
        let h = self.term(n, "box.border_top", bt) + self.term(n, "box.pad_top", pt) + self.term(n, "box.content", ch) + self.term(n, "box.pad_bottom", pb) + self.term(n, "box.border_bottom", bb);
        // background + borders painted under content
        let mut deco = Vec::new();
        let grad_src = if s.bg_img != 0 && self.st.families[s.bg_img as usize].contains("gradient(") { Some(s.bg_img) } else { None };
        // a rounded box with nothing to paint (no background, border, shadow, glass or gradient) stays plain: no Box, no cost
        let paints = s.bg & 0xff != 0 || (0..4).any(|i| s.border_style[i] != 0 && s.border_color[i] & 0xff != 0 && s.border_w[i] > 0);
        let rich = s.visibility == 0 && w > 0 && h > 0 && ((s.radius.iter().any(|r| !matches!(r, Len::Px(0) | Len::Pct(0))) && paints)
            || s.shadow != 0 || s.backdrop != 0 || grad_src.is_some());
        if rich {
            // P2 Orbit: one decorated box carries background, gradient, borders, shadows and backdrop (paint.rs)
            let f = FX as f32;
            let (wp, hp) = (w as f32 / f, h as f32 / f);
            let rad = |l: Len, basis: i32| match l { Len::Px(v) => v as f32 / f, Len::Pct(p) => p as f32 / 10000.0 * basis as f32 / f, _ => 0.0 };
            let r = crate::paint::fit_radii([rad(s.radius[0], w.min(h)), rad(s.radius[1], w.min(h)), rad(s.radius[2], w.min(h)), rad(s.radius[3], w.min(h))], wp, hp);
            let fs = s.font_size as f32 / f;
            let shadows = if s.shadow != 0 { crate::paint::parse_shadows(&self.st.families[s.shadow as usize], s.color, fs) } else { Vec::new() };
            let (blur, sat) = if s.backdrop != 0 { crate::paint::parse_backdrop(&self.st.families[s.backdrop as usize], fs) } else { (0.0, 1.0) };
            let grad = grad_src.and_then(|g| crate::paint::parse_gradient(&self.st.families[g as usize], wp, hp, s.color, fs));
            let side = |i: usize| s.border_style[i] != 0 && s.border_color[i] & 0xff != 0;
            let bwv = [bt, br, bb, bl];
            deco.push(Item::Box(Box::new(crate::paint::Deco { x, y, w, h, r, fill: s.bg, grad,
                bw: std::array::from_fn(|i| if side(i) { bwv[i] as f32 / f } else { 0.0 }), bc: s.border_color,
                shadows, blur, sat, alpha: 255, clip: crate::paint::NO_CLIP })));
        }
        if !rich && s.bg & 0xff != 0 && s.visibility == 0 { deco.push(Item::Rect { x, y, w, h, color: s.bg }); }
        if s.bg_img != 0 && grad_src.is_none() && s.visibility == 0 && w > 0 && h > 0 {
            cov(line!());
            let mode = 1 + s.bg_repeat + match s.bg_size { 1 => 8, 2 => 16, _ => 0 } + if s.bg_center { 32 } else { 0 };
            deco.push(Item::Image { x, y, w, h, node: n, mode });
        }
        let bs = [(0, x, y, w, bt), (1, x + w - br, y, br, h), (2, x, y + h - bb, w, bb), (3, x, y, bl, h)];
        for (side, rx, ry, rw, rh) in bs {
            cov(line!());
            if !rich && rw > 0 && rh > 0 && s.border_style[side] != 0 && s.border_color[side] & 0xff != 0 && s.visibility == 0 {
                cov(line!());
                deco.push(Item::Rect { x: rx, y: ry, w: rw, h: rh, color: s.border_color[side] });
            }
        }
        if s.display == Display::ListItem && s.list_style != 0 { self.marker(n, &s, x, cy, &mut deco); }
        let deco_len = deco.len();
        self.out.items.splice(bg_at..bg_at, deco);
        // opacity: the subtree keeps its layout; its paint alpha scales (0 = invisible: images dropped too)
        if s.opacity < 255 {
            cov(line!());
            let op = s.opacity as u32;
            if op == 0 { self.out.items.truncate(bg_at); }
            else {
                cov(line!());
                for it in &mut self.out.items[bg_at..] {
                    cov(line!());
                    match it { Item::Rect { color, .. } | Item::Text { color, .. } => { *color = (*color & !0xff) | ((*color & 0xff) * op / 255); } Item::Image { .. } => {}
                        Item::Box(d) => d.alpha = (d.alpha as u32 * op / 255) as u8 }
                }
            }
        }
        let bi = self.out.boxes.len() as u32;
        self.out.boxes.push((n, [x, y, w, h]));
        if !self.inl_pending.is_empty() {
            let out = &mut self.out.inline;
            self.inl_pending.retain(|p| if p.1 == n { out.push((p.0, bi, [p.2[0] - x, p.2[1] - y, p.2[2], p.2[3]])); false } else { true });
        }
        if positioned { self.pos_stack.pop(); }
        let (tx, ty) = (self.term(n, "move.translate_x", res0(s.translate[0], w)), self.term(n, "move.translate_y", res0(s.translate[1], h)));
        let (ie, be, ae) = (self.out.items.len(), self.out.boxes.len(), self.abs.len());
        self.shift_span(bg_at..ie, box_at..be, abs_at..ae, tx, ty);
        if s.position == 1 {
            cov(line!());
            let dx = res(s.inset[3], w).or(res(s.inset[1], w).map(|r| -r)).unwrap_or(0);
            let dy = res(s.inset[0], 0).or(res(s.inset[2], 0).map(|b| -b)).unwrap_or(0);
            let (dx, dy) = (self.term(n, "move.relative_x", dx), self.term(n, "move.relative_y", dy));
            self.shift_span(bg_at..ie, box_at..be, abs_at..ae, dx, dy);
        }
        if s.overflow != 0 {
            cov(line!());
            if let Some(st) = self.dom.attr(n, "data-scroll-top").and_then(|v| v.parse::<i32>().ok()) {
                // scrolled container: content moves up by scrollTop, clamped so the last line stays at the bottom
                let inner_top = y + bt + pt;
                let content_bottom = self.out.items[(bg_at + deco_len).min(self.out.items.len())..].iter().map(|i| { let (_, iy, _, ih) = i.bounds(); iy + ih }).max().unwrap_or(inner_top);
                let max_scroll = (content_bottom - (y + h - bb - pb)).max(0);
                let dy = (st * FX).min(max_scroll);
                if dy > 0 {
                    cov(line!());
                    let (ie, be) = (self.out.items.len(), self.out.boxes.len());
                    // content only: not the container's own decoration items, not its own box (pushed last)
                    self.out.shift_range((bg_at + deco_len).min(ie)..ie, box_at..be.saturating_sub(1), 0, -dy);
                }
            }
        }
        if s.overflow == 1 || (def_h.is_some() || matches!(s.height, Len::Px(_))) && s.overflow != 0 {
            cov(line!());
            // clip to the padding box: content outside goes, rectangles are cropped, a text run crossing the top or
            // bottom edge is dropped (no half glyphs drawn over neighbours); the box's own decoration is not clipped
            let (x0, y0, x1, y1) = (x + bl, y + bt, x + w - br, y + h - bb);
            let start = (bg_at + deco_len).min(self.out.items.len());
            let tail: Vec<Item> = self.out.items.drain(start..).collect();
            for mut it in tail {
                cov(line!());
                let (ix, iy, iw, ih) = it.bounds();
                if ix >= x1 || iy >= y1 || ix + iw <= x0 || iy + ih <= y0 { continue; }
                match &mut it {
                    Item::Rect { x: rx, y: ry, w: rw, h: rh, .. } => {
                        let (nx0, ny0) = ((*rx).max(x0), (*ry).max(y0));
                        let (nx1, ny1) = ((*rx + *rw).min(x1), (*ry + *rh).min(y1));
                        *rx = nx0; *ry = ny0; *rw = nx1 - nx0; *rh = ny1 - ny0;
                    }
                    Item::Text { .. } => { if iy < y0 - 2 * FX || iy + ih > y1 + 2 * FX { continue; } }
                    Item::Image { .. } => {}
                    Item::Box(d) => { d.clip = [d.clip[0].max(x0), d.clip[1].max(y0), d.clip[2].min(x1), d.clip[3].min(y1)]; }
                }
                self.out.items.push(it);
            }
        }
        h
    }

    /// One line of text as a paint item (form-control values and placeholders), cut at `max_w`.
    fn text_item(&mut self, s: &Style, txt: &str, x: i32, top: i32, max_w: i32, color: u32) -> Option<Item> {
        let f = self.font(s);
        let lh = self.line_h(s);
        let (a, d) = self.fonts.metrics(f, s.font_size);
        let base = top + (lh - (a + d)) / 2 + a;
        let mut gl = Vec::new(); let mut adv = 0;
        for c in txt.chars() { let (fid, g, w) = self.fonts.advance(f, c, s.font_size); if adv + w > max_w { break; } gl.push((g, adv, fid)); adv += w; }
        if gl.is_empty() { return None; }
        let face = gl[0].2;
        let packed: Vec<u32> = gl.iter().map(|&(g, off, _)| (g as u32) << 16 | ((off + 8) / 16).clamp(0, 65535) as u32).collect();
        Some(Item::Text { x, y: base, px: s.font_size, color, face, glyphs: packed, deco: 0, w: adv })
    }

    fn marker(&mut self, _n: u32, s: &Style, x: i32, cy: i32, deco: &mut Vec<Item>) {
        let f = self.font(s);
        let lh = self.line_h(s);
        let (a, d) = self.fonts.metrics(f, s.font_size);
        let base = cy + (lh - (a + d)) / 2 + a;
        let ch = match s.list_style { 1 => '•', 2 => '◦', 3 => '▪', _ => '•' };
        let txt: String = if s.list_style >= 4 { "1.".into() } else { ch.to_string() };
        let mut gl = Vec::new();
        let mut adv = 0;
        for c in txt.chars() { let (fid, g, w) = self.fonts.advance(f, c, s.font_size); gl.push((g, adv, fid)); adv += w; }
        let face = gl.first().map(|g| g.2).unwrap_or(f);
        let packed: Vec<u32> = gl.iter().map(|&(g, off, _)| (g as u32) << 16 | ((off + 8) / 16).clamp(0, 65535) as u32).collect();
        deco.push(Item::Text { x: x - adv - s.font_size / 2, y: base, px: s.font_size, color: s.color, face, glyphs: packed, deco: 0, w: adv });
    }

    /// Normal flow of `n`'s children inside content box (cx, cy, cw). Returns content height.
    fn flow(&mut self, n: u32, cx: i32, cy: i32, cw: i32) -> i32 {
        self.mark(n, "path.flow");
        let kids = self.flat_children(n);
        let any_block = kids.iter().any(|&c| { let d = self.disp(c); (is_block_level(d) && self.s_float(c) == 0 && !self.is_abs(c)) || self.inline_with_block(c) });
        if !any_block {
            cov(line!());
            return self.inline(n, &kids, cx, cy, cw);
        }
        // block flow, with runs of inline content wrapped in anonymous block boxes; margins collapse
        // between siblings and through a parent without border/padding (CSS 2.2 §8.3.1)
        let absorb_top = self.collapses_top(n) && self.rule(n, "rule.collapse_first_child_margin");
        let absorb_bottom = self.collapses_bottom(n) && self.rule(n, "rule.collapse_last_child_margin");
        let mut y = cy;            // bottom border edge of the previous in-flow box
        let mut pending: i32 = 0;  // its (collapsed) bottom margin, not yet applied
        let mut first = true;
        let mut run: Vec<u32> = Vec::new();
        for (k, &c) in kids.iter().enumerate() {
            cov(line!());
            let d = self.disp(c);
            let blockish = (is_block_level(d) && self.s_float(c) == 0 && !self.is_abs(c)) || self.inline_with_block(c);
            if !blockish {
                cov(line!());
                run.push(c);
                if k + 1 < kids.len() { continue; }
            }
            if !run.is_empty() {
                cov(line!());
                let r = std::mem::take(&mut run);
                let only_ws = r.iter().all(|&t| (self.dom.nodes[t as usize].kind == Kind::Text && self.dom.text(t).trim().is_empty()) || self.is_abs(t));
                let has_float = r.iter().any(|&t| self.s_float(t) != 0);
                if !only_ws || has_float {
                    cov(line!());
                    let at = y + pending;
                    let h = self.inline(n, &r, cx, at, cw);
                    let h = if h > 0 { self.term(n, "flow.anon_inline_h", h) } else { h };
                    if h > 0 { y = at + h; pending = 0; first = false; }
                } else {
                    cov(line!());
                    for &t in &r { if self.is_abs(t) { let cb = self.cb_node(); self.abs.push((t, cx, y + pending, cb)); } }
                }
                if !blockish { continue; }
            }
            let cs = self.s(c).clone();
            if cs.clear != 0 {
                cov(line!());
                let fb = self.floats.iter().filter(|f| (cs.clear == 3) || (cs.clear == 1) == f.left).map(|f| f.y1).max().unwrap_or(y);
                if fb > y + pending { y = fb; pending = 0; }
            }
            let mt = self.top_margin(c, cw);
            let ctx = self.pctx(self.s(n).display);
            let gap = if first && absorb_top { 0 } else if first { combine(pending, mt) * program().weight("flow.margins", &ctx, 0) } else { combine(pending, mt) };
            let start = y + self.term(c, "flow.gap", gap);
            let (mut ml, _mr, mut w) = self.hsizes(&cs, c, cw);
            // CSS Box Alignment 3 §6.1 (shipped in Chrome): justify-self on a block-level box in block layout
            // shrink-fits an auto width and aligns it within the containing block
            if cs.justify_self != 0 && matches!(cs.width, Len::Auto) && self.replaced(c).is_none() {
                cov(line!());
                w = self.shrink_to_fit(c, cw);
                let (m_l, m_r) = (res0(cs.margin[3], cw), res0(cs.margin[1], cw));
                ml = match cs.justify_self { 2 => cw - w - m_r, 3 => (cw - w) / 2, _ => m_l };
            }
            // -webkit-center (<center>, align=center) centres narrower block children (HTML §15.3.3)
            if self.s(n).text_align == 5 && w < cw && matches!(cs.margin[1], Len::Px(0)) && matches!(cs.margin[3], Len::Px(0)) { ml = (cw - w) / 2; }
            crate::why!(c, "flow", "block flow in node {n}: y = previous bottom {} + gap {} ({}pending bottom margin {} ⊕ collapsed top margin {}) = {}; x = content left {} + margin-left {}; width {} of available {}",
                crate::why::px(y), crate::why::px(gap), if first && absorb_top { "first child, absorbed by parent; " } else { "" }, crate::why::px(pending), crate::why::px(mt), crate::why::px(start), crate::why::px(cx), crate::why::px(ml), crate::why::px(w), crate::why::px(cw));
            let h = self.block_box(c, cx + ml, start, w, false);
            let mb_eff = self.bottom_margin(c, cw);
            if h == 0 && self.collapses_top(c) && self.collapses_bottom(c) && self.rule(c, "rule.empty_collapse_through") {
                // empty box: its own top and bottom margins collapse together and through to the next sibling (§8.3.1)
                pending = combine(pending, combine(mt, mb_eff));
                continue;
            }
            y = start + h;
            pending = mb_eff;
            first = false;
        }
        (y - cy + if absorb_bottom { 0 } else { self.term(n, "flow.trailing_margin", pending * program().weight("flow.margins", &self.pctx(self.s(n).display), 1)) }).max(0)
    }

    fn margin_box_ok(&self, n: u32) -> bool {
        // flex/grid items establish independent formatting contexts: their children's margins stay inside (CSS Flexbox §4, Grid §6)
        let p = self.dom.nodes[n as usize].parent;
        let in_flex_grid = p != NONE && self.dom.nodes[p as usize].kind == Kind::Element
            && matches!(self.s(p).display, Display::Flex | Display::InlineFlex | Display::Grid | Display::InlineGrid);
        self.dom.nodes[n as usize].kind == Kind::Element && matches!(self.s(n).display, Display::Block | Display::ListItem)
            && self.s(n).float == 0 && !matches!(self.s(n).position, 2 | 3) && self.s(n).overflow == 0 && !in_flex_grid
    }
    fn collapses_top(&self, n: u32) -> bool {
        let s = self.s(n);
        self.margin_box_ok(n) && s.border_w[0] == 0 && matches!(s.padding[0], Len::Px(0)) && self.dom.tag(n) != "html" && self.dom.tag(n) != "body" || (self.dom.tag(n) == "body" && s.border_w[0] == 0 && matches!(s.padding[0], Len::Px(0)) && self.patch(n, "patch.body_collapse"))
    }
    fn collapses_bottom(&self, n: u32) -> bool {
        let s = self.s(n);
        self.margin_box_ok(n) && s.border_w[2] == 0 && matches!(s.padding[2], Len::Px(0)) && matches!(s.height, Len::Auto) && self.dom.tag(n) != "html"
    }
    /// First in-flow block child, if no inline content precedes it.
    fn first_block(&self, n: u32) -> Option<u32> {
        let mut floated = false;
        for c in self.flat_children(n) {
            cov(line!());
            if self.dom.nodes[c as usize].kind == Kind::Text { if self.dom.text(c).trim().is_empty() { continue; } return None; }
            if self.is_abs(c) { continue; }
            if self.s_float(c) != 0 { floated = true; continue; }
            // a box with clearance never collapses its top margin with its parent's (CSS 2.2 §8.3.1)
            if floated && self.s(c).clear != 0 { return None; }
            return if is_block_level(self.disp(c)) && !matches!(self.disp(c), Display::TableRow | Display::TableCell) { Some(c) } else { None };
        }
        None
    }
    fn last_block(&self, n: u32) -> Option<u32> {
        for c in self.flat_children(n).into_iter().rev() {
            cov(line!());
            if self.dom.nodes[c as usize].kind == Kind::Text { if self.dom.text(c).trim().is_empty() { continue; } return None; }
            if self.is_abs(c) || self.s_float(c) != 0 { continue; }
            return if is_block_level(self.disp(c)) && !matches!(self.disp(c), Display::TableRow | Display::TableCell) { Some(c) } else { None };
        }
        None
    }
    fn top_margin(&self, n: u32, cw: i32) -> i32 {
        let own = res0(self.s(n).margin[0], cw);
        if self.collapses_top(n) { if let Some(c) = self.first_block(n) { return combine(own, self.top_margin(c, cw)); } }
        own
    }
    fn bottom_margin(&self, n: u32, cw: i32) -> i32 {
        let own = res0(self.s(n).margin[2], cw);
        if self.collapses_bottom(n) { if let Some(c) = self.last_block(n) { return combine(own, self.bottom_margin(c, cw)); } }
        own
    }

    /// CSS 2.2 §9.2.1.1 block-in-inline: an inline box containing in-flow block-level boxes is split around
    /// them; we lay such an inline out as a block container (the split halves become anonymous lines).
    fn inline_with_block(&self, c: u32) -> bool {
        if self.dom.nodes[c as usize].kind != Kind::Element { return false; }
        let s = self.s(c);
        if s.display != Display::Inline || self.replaced(c).is_some() { return false; }
        self.flat_children(c).into_iter().any(|k| { let d = self.disp(k); (is_block_level(d) && self.s_float(k) == 0 && !self.is_abs(k)) || self.inline_with_block(k) })
    }

    /// Any non-whitespace text in the subtree (decides whether a box has a natural baseline).
    fn has_text(&self, n: u32) -> bool {
        self.dom.children(n).any(|c| match self.dom.nodes[c as usize].kind {
            Kind::Text => !self.dom.text(c).trim().is_empty(),
            Kind::Element => self.disp(c) != Display::None && self.has_text(c),
            _ => false,
        })
    }

    fn s_float(&self, c: u32) -> u8 { if self.dom.nodes[c as usize].kind == Kind::Element { self.s(c).float } else { 0 } }
    fn is_abs(&self, c: u32) -> bool { self.dom.nodes[c as usize].kind == Kind::Element && matches!(self.s(c).position, 2 | 3) && self.s(c).display != Display::None }

    /// Children with display:contents expanded and display:none / comments dropped.
    fn flat_children(&self, n: u32) -> Vec<u32> {
        let mut out = Vec::new();
        for c in self.dom.children(n) {
            cov(line!());
            match self.dom.nodes[c as usize].kind {
                Kind::Text => out.push(c),
                Kind::Element => {
                    cov(line!());
                    let d = self.s(c).display;
                    if d == Display::None { continue; }
                    if d == Display::Contents { out.extend(self.flat_children(c)); } else { out.push(c); }
                }
                _ => {}
            }
        }
        out
    }

    fn float_band(&self, y: i32, h: i32, x0: i32, x1: i32) -> (i32, i32) {
        let (mut l, mut r) = (x0, x1);
        for f in &self.floats {
            cov(line!());
            if f.y0 < y + h.max(1) && f.y1 > y {
                cov(line!());
                if f.left { l = l.max(f.x1); } else { r = r.min(f.x0); }
            }
        }
        (l, r.max(l))
    }

    fn place_float(&mut self, c: u32, cx: i32, y: i32, cw: i32) {
        self.mark(c, "path.float");
        let s = self.s(c).clone();
        let w = self.fit_width(&s, c, cw);
        let w = self.clamp_w(&s, w, cw);
        let (ml, mr) = (res0(s.margin[3], cw), res0(s.margin[1], cw));
        let (mt, mb) = (res0(s.margin[0], cw), res0(s.margin[2], cw));
        let mut yy = y;
        let left = s.float == 1;
        // find a band wide enough
        for _ in 0..64 {
            cov(line!());
            let (l, r) = self.float_band(yy, 1, cx, cx + cw);
            if r - l >= w + ml + mr || (l == cx && r == cx + cw) { break; }
            let next = self.floats.iter().filter(|f| f.y1 > yy).map(|f| f.y1).min().unwrap_or(yy);
            if next <= yy { break; }
            yy = next;
        }
        let (l, r) = self.float_band(yy, 1, cx, cx + cw);
        let bx = if left { l + ml } else { r - mr - w };
        let saved = std::mem::take(&mut self.floats);
        self.pad_cb = Some((c, cw));
        let h = self.block_box(c, bx, yy + mt, w, false);
        self.floats = saved;
        self.floats.push(Float { left, x0: bx - ml, x1: bx + w + mr, y0: yy, y1: yy + mt + h + mb });
    }

    // ───────────── inline formatting ─────────────

    fn collect(&self, n: u32, out: &mut Vec<Inl>) {
        for c in self.flat_children(n) {
            cov(line!());
            match self.dom.nodes[c as usize].kind {
                Kind::Text => out.push(Inl::Text(c)),
                _ => {
                    cov(line!());
                    let s = self.s(c);
                    if self.dom.tag(c) == "br" { out.push(Inl::Br); continue; }
                    if matches!(s.position, 2 | 3) || s.float != 0 { out.push(Inl::Atomic(c)); continue; }
                    match s.display {
                        Display::Inline if self.replaced(c).is_none() => { out.push(Inl::Open(c)); self.collect(c, out); out.push(Inl::Close(c)); }
                        _ => out.push(Inl::Atomic(c)),
                    }
                }
            }
        }
    }

    /// Inline formatting context for `items` (children of `n`) in content box (cx, cy, cw). Returns height.
    fn inline(&mut self, n: u32, kids: &[u32], cx: i32, cy: i32, cw: i32) -> i32 {
        self.mark(n, "path.inline");
        let mut items = Vec::new();
        for &c in kids {
            cov(line!());
            match self.dom.nodes[c as usize].kind {
                Kind::Text => items.push(Inl::Text(c)),
                _ => {
                    cov(line!());
                    let s = self.s(c);
                    if self.dom.tag(c) == "br" { items.push(Inl::Br); }
                    else if matches!(s.position, 2 | 3) || s.float != 0 { items.push(Inl::Atomic(c)); }
                    else if s.display == Display::Inline && self.replaced(c).is_none() { items.push(Inl::Open(c)); self.collect(c, &mut items); items.push(Inl::Close(c)); }
                    else if is_block_level(s.display) { items.push(Inl::Atomic(c)); }
                    else { items.push(Inl::Atomic(c)); }
                }
            }
        }
        let ps = self.s(n).clone();
        let mut lb = LineBuilder::new(cx, cy, cw, ps.text_align, res0(ps.text_indent, cw));
        lb.owner = n;
        let strut = { let lh = self.line_h(&ps); let f = self.font(&ps); let (a, d) = self.fonts.metrics(f, ps.font_size); (lh, a, d) };
        lb.strut = strut;
        let mut stack: Vec<u32> = vec![n];
        let mut pending_space = false;
        for it in items {
            cov(line!());
            match it {
                Inl::Br => { lb.flush(self, true); pending_space = false; }
                Inl::Open(e) => {
                    cov(line!());
                    let s = self.s(e);
                    let lead = res0(s.margin[3], cw) + s.border_w[3] + res0(s.padding[3], cw);
                    lb.open(e, lead);
                    stack.push(e);
                }
                Inl::Close(e) => {
                    cov(line!());
                    let s = self.s(e);
                    let trail = res0(s.margin[1], cw) + s.border_w[1] + res0(s.padding[1], cw);
                    lb.close(e, trail, self);
                    stack.pop();
                }
                Inl::Atomic(c) => {
                    cov(line!());
                    let s = self.s(c).clone();
                    if matches!(s.position, 2 | 3) {
                        cov(line!());
                        let cb = self.cb_node();
                        // block-level originals start a new line at the content edge (CSS 2.2 §10.3.7 static position)
                        let (sx, sy) = if s.was_inline { (lb.x, lb.y) } else if lb.at_line_start() { (cx, lb.y) } else { (cx, lb.y + lb.strut.0) };
                        self.abs.push((c, sx, sy, cb));
                        continue;
                    }
                    if s.float != 0 { self.place_float(c, cx, lb.y, cw); lb.refit(self); continue; }
                    pending_space = false;
                    // lay out the atomic box at the origin, then move it into the line
                    let it0 = self.out.items.len();
                    let bx0 = self.out.boxes.len();
                    let w = self.fit_width(&s, c, cw);
                    let w = self.clamp_w(&s, w, cw);
                    let saved = std::mem::take(&mut self.floats);
                    let outer_base = self.last_base.take();
                    let ab0 = self.abs.len();
                    let h = self.block_box(c, 0, 0, w, false);
                    let inner_base = self.last_base.take();
                    self.last_base = outer_base;
                    self.floats = saved;
                    let (ml, mr) = (res0(s.margin[3], cw), res0(s.margin[1], cw));
                    let (mt, mb) = (res0(s.margin[0], cw), res0(s.margin[2], cw));
                    // CSS 2.2 §10.8.1: inline-block baseline = its last line box, else the bottom margin edge
                    let mut base = match inner_base { Some(b) if s.overflow == 0 && self.replaced(c).is_none() => mt + b, _ => mt + h + mb };
                    // inline-flex: baseline of the first item; an item without text synthesizes it from its bottom border edge (Flexbox §8.5)
                    if matches!(s.display, Display::InlineFlex) {
                        cov(line!());
                        let first = self.flat_children(c).into_iter().find(|&k| self.dom.nodes[k as usize].kind == Kind::Element && !self.is_abs(k) && self.disp(k) != Display::None);
                        if let Some(k) = first {
                            cov(line!());
                            if !self.has_text(k) { if let Some(b) = self.out.boxes[bx0..].iter().find(|b| b.0 == k) { base = mt + b.1[1] + b.1[3]; } }
                        }
                    }
                    lb.atomic(self, it0, bx0, ab0, ml, w, mr, mt + h + mb, mt, s.vertical_align, base);
                }
                Inl::Text(t) => {
                    cov(line!());
                    let p = *stack.last().unwrap();
                    let s = self.s(p).clone();
                    let txt = self.dom.text(t);
                    let txt: std::borrow::Cow<str> = match s.text_transform { 1 => txt.to_uppercase().into(), 2 => txt.to_lowercase().into(), _ => txt.into() };
                    let preserve = matches!(s.white_space, 1 | 3);
                    let nl_break = matches!(s.white_space, 1 | 3 | 4);
                    let wrap = !matches!(s.white_space, 1 | 2);
                    let f = self.font(&s);
                    let lh = self.line_h(&s);
                    let (a, d) = self.fonts.metrics(f, s.font_size);
                    let shift = match s.vertical_align { 4 => s.font_size / 5, 5 => -s.font_size / 3, _ => 0 };
                    let run = RunStyle { ls: s.letter_spacing, font: f, px: s.font_size, color: s.color, deco: s.decoration, lh, asc: a, desc: d, shift, wrap, vis: s.visibility == 0, kern: self.kern_on(p, &s) };
                    let brk = self.patch(p, "patch.linebreak");
                    if preserve {
                        cov(line!());
                        for (li, line) in txt.split('\n').enumerate() {
                            cov(line!());
                            if li > 0 && nl_break { lb.flush(self, true); }
                            let line = line.replace('\t', "        ");
                            for (k, word) in line.split(' ').enumerate() {
                                cov(line!());
                                if k > 0 { lb.word(self, &run, " ", true); }
                                if !word.is_empty() { lb.word(self, &run, word, false); }
                            }
                        }
                        pending_space = false;
                    } else {
                        cov(line!());
                        let mut first = true;
                        let lead_ws = txt.starts_with(|c: char| c.is_ascii_whitespace());
                        if lead_ws && !pending_space && !lb.at_line_start() { lb.word(self, &run, " ", true); }
                        pending_space = false;
                        let mut emitted_lead = lead_ws;
                        for (li, seg) in if nl_break { txt.split('\n').collect::<Vec<_>>() } else { vec![&txt[..]] }.into_iter().enumerate() {
                            if li > 0 { lb.flush(self, true); pending_space = false; }
                            for word in seg.split_ascii_whitespace() {
                                cov(line!());
                                if !first && !emitted_lead && !lb.at_line_start() { lb.word(self, &run, " ", true); }
                                emitted_lead = false;
                                if brk { for p in pieces(word, true) { lb.word(self, &run, p, false); } } else { lb.word(self, &run, word, false); }
                                first = false;
                            }
                        }
                        // a collapsible space at the end is emitted here, in this run's style; the next
                        // text's leading space then collapses into it (CSS Text §4.1.1)
                        if txt.ends_with(|c: char| c.is_ascii_whitespace()) && !txt.trim().is_empty() && !lb.at_line_start() {
                            cov(line!());
                            lb.word(self, &run, " ", true);
                            pending_space = true;
                        } else if txt.trim().is_empty() && lead_ws { pending_space = true; } else { pending_space = false; }
                    }
                }
            }
        }
        lb.flush(self, false);
        lb.y - cy
    }
}

#[derive(Clone, Copy)]
struct RunStyle { ls: i32, font: FontId, px: i32, color: u32, deco: u8, lh: i32, asc: i32, desc: i32, shift: i32, wrap: bool, vis: bool, kern: bool }

enum Frag {
    Glyphs { x: i32, run: RunStyle, glyphs: Vec<(u16, i32, FontId)>, w: i32, space: bool },
    Atomic { x: i32, it0: usize, bx0: usize, it1: usize, bx1: usize, ab0: usize, ab1: usize, w: i32, h: i32, mt: i32, va: u8, base: i32 },
}

struct LineBuilder {
    x0: i32, w: i32, y: i32, align: u8, indent: i32,
    lx0: i32, lx1: i32,   // current line's available band (after floats)
    x: i32,
    frags: Vec<Frag>,
    strut: (i32, i32, i32),
    first_line: bool,
    open: Vec<(u32, i32)>, // inline boxes open on this line: node, start x
    inl: Vec<(u32, i32, i32)>, // inline boxes closed on this line: node, start x, end x (hit-test side channel)
    pending_lead: i32,
    lines: i32,
    owner: u32,
}

impl LineBuilder {
    fn new(x0: i32, y: i32, w: i32, align: u8, indent: i32) -> Self {
        LineBuilder { x0, w, y, align, indent, lx0: x0, lx1: x0 + w, x: x0 + indent, frags: Vec::new(), strut: (0, 0, 0), first_line: true,
                      open: Vec::new(), inl: Vec::new(), pending_lead: 0, lines: 0, owner: NONE }
    }
    fn at_line_start(&self) -> bool { self.frags.iter().all(|f| matches!(f, Frag::Glyphs { space: true, .. })) }
    fn refit(&mut self, l: &Layout) {
        let (a, b) = l.float_band(self.y, self.strut.0, self.x0, self.x0 + self.w);
        if self.frags.is_empty() { self.lx0 = a; self.lx1 = b; self.x = a + if self.first_line { self.indent } else { 0 }; }
    }
    fn open(&mut self, e: u32, lead: i32) { self.open.push((e, self.x)); self.pending_lead += lead; }
    fn close(&mut self, _e: u32, trail: i32, _l: &mut Layout) { if let Some((e, x0)) = self.open.pop() { self.inl.push((e, x0, self.x)); } self.x += trail + std::mem::take(&mut self.pending_lead) * 0; }
    fn space(&mut self, l: &mut Layout) {
        let r = RunStyle { ls: 0, font: 0, px: 16 * FX, color: 0, deco: 0, lh: 0, asc: 0, desc: 0, shift: 0, wrap: true, vis: false, kern: false };
        let (_, _, sp) = l.fonts.advance(r.font, ' ', self.strut.1 + self.strut.2);
        if !self.at_line_start() { self.frags.push(Frag::Glyphs { x: self.x, run: r, glyphs: Vec::new(), w: sp, space: true }); self.x += sp; }
    }
    fn word(&mut self, l: &mut Layout, run: &RunStyle, word: &str, is_space: bool) {
        if self.frags.is_empty() && self.lines == 0 && self.x == self.x0 + self.indent { self.refit(l); }
        let lead = std::mem::take(&mut self.pending_lead);
        let mut gl = Vec::with_capacity(word.len());
        let mut adv = 0;
        for ch in word.chars() {
            cov(line!());
            let (fid, g, a) = l.fonts.advance(run.font, ch, run.px);
            if run.kern { if let Some(&(pg, _, pf)) = gl.last() { if pf == fid { adv += l.fonts.kern(fid, pg, g, run.px); } } }
            gl.push((g, adv, fid));
            adv += a + run.ls;
        }
        if is_space && self.at_line_start() { return; }
        if !is_space && run.wrap && self.x + lead + adv > self.lx1 && !self.at_line_start() {
            cov(line!());
            self.flush(l, false);
            self.refit(l);
        }
        self.x += lead;
        self.frags.push(Frag::Glyphs { x: self.x, run: *run, glyphs: gl, w: adv, space: is_space });
        self.x += adv;
    }
    fn atomic(&mut self, l: &mut Layout, it0: usize, bx0: usize, ab0: usize, ml: i32, w: i32, mr: i32, h: i32, mt: i32, va: u8, base: i32) {
        if self.x + ml + w > self.lx1 && !self.at_line_start() { self.flush(l, false); self.refit(l); }
        let lead = std::mem::take(&mut self.pending_lead);
        self.x += lead + ml;
        let (it1, bx1, ab1) = (l.out.items.len(), l.out.boxes.len(), l.abs.len());
        self.frags.push(Frag::Atomic { x: self.x, it0, bx0, it1, bx1, ab0, ab1, w, h, mt, va, base });
        self.x += w + mr;
    }
    fn flush(&mut self, l: &mut Layout, forced: bool) {
        // drop trailing spaces
        while matches!(self.frags.last(), Some(Frag::Glyphs { space: true, .. })) { if let Some(Frag::Glyphs { w, .. }) = self.frags.pop() { self.x -= w; } }
        if self.frags.is_empty() {
            cov(line!());
            if forced { self.y += self.strut.0; self.lines += 1; }
            self.x = self.lx0;
            self.first_line = false;
            return;
        }
        // line box: baseline from half-leading of every run + atomic heights
        let (slh, sa, sd) = self.strut;
        let half = (slh - (sa + sd)) / 2;
        // the line box is a MAX over strut, text and atomic extents (max-plus algebra): every candidate is weighed by its knob,
        // and the ledger records only the WINNER's tropical marginal (winner − runner-up) = exactly how much the line shrinks
        // when that term is switched off; losing terms record 0 (switching them off changes nothing)
        let ow = self.owner;
        let (ka, kb, kta, ktb, kaa, kab) = (l.kw(ow, "line.strut_above"), l.kw(ow, "line.strut_below"), l.kw(ow, "line.text_above"), l.kw(ow, "line.text_below"), l.kw(ow, "line.atomic_above"), l.kw(ow, "line.atomic_below"));
        let mut ca: Vec<(&'static str, i32)> = vec![("line.strut_above", (half + sa) * ka)];
        let mut cb: Vec<(&'static str, i32)> = vec![("line.strut_below", (slh - (half + sa)) * kb)];
        if l.dom.quirks && l.rule(ow, "rule.quirks_empty_line") && !self.frags.iter().any(|f| matches!(f, Frag::Glyphs { space: false, .. })) { ca[0].1 = 0; cb[0].1 = 0; }
        let tb_on = l.patch(ow, "patch.va_top_bottom");
        let (mut tb_top, mut tb_bot) = (0i32, 0i32);
        for f in &self.frags {
            cov(line!());
            match f {
                Frag::Glyphs { run, space: false, .. } => {
                    let h = (run.lh - (run.asc + run.desc)) / 2;
                    ca.push(("line.text_above", (h + run.asc - run.shift) * kta));
                    cb.push(("line.text_below", (run.lh - h - run.asc + run.shift) * ktb));
                }
                // vertical-align top / bottom (CSS 2.2 §10.8.1): aligned to the line box edges, not the baseline — they only
                // grow the line when taller than it (github file cells: overflow:hidden inline-block, baseline = bottom edge,
                // aligned `top` → Chrome 21 px line, ours 26.8 when it was treated as baseline-aligned)
                Frag::Atomic { h, va, .. } if tb_on && (*va == 2 || *va == 3) => { if *va == 2 { tb_top = tb_top.max(*h); } else { tb_bot = tb_bot.max(*h); } }
                Frag::Atomic { h, va, base, .. } => {
                    if *va == 1 { ca.push(("line.atomic_mid", h / 2 + sa / 3)); cb.push(("line.atomic_mid", h - h / 2 - sa / 3)); }
                    else { ca.push(("line.atomic_above", *base * kaa)); cb.push(("line.atomic_below", (h - base) * kab)); }
                }
                _ => {}
            }
        }
        let trop = |c: &[(&'static str, i32)]| -> (i32, &'static str, i32) {
            let (mut top, mut key, mut second) = (i32::MIN, "", i32::MIN);
            for &(k, v) in c { if v > top { second = top; top = v; key = k; } else if v > second { second = v; } }
            (top, key, if second == i32::MIN { top } else { top - second.max(0) })
        };
        let (above, wa, ma) = trop(&ca); let (below, wb, mb) = trop(&cb);
        let (above, below) = { let (mut a, mut b) = (above, below); if tb_top > a + b { b = tb_top - a; } if tb_bot > a + b { a = tb_bot - b; } (a, b) };
        if wa != "line.atomic_mid" { l.note(ow, wa, ma); }
        if wb != "line.atomic_mid" { l.note(ow, wb, mb); }
        let used = self.x - self.lx0;
        let free = (self.lx1 - self.lx0) - used;
        let dx = match self.align { 2 => free, 3 | 5 => free / 2, _ => 0 }.max(0);
        let base = self.y + above;
        // words on a line that share face/size/colour/decoration/baseline become ONE run (spaces become gaps)
        let mut open: Option<Item> = None;
        let close = |open: &mut Option<Item>, items: &mut Vec<Item>| { if let Some(it) = open.take() { items.push(it); } };
        for f in self.frags.drain(..) {
            cov(line!());
            match f {
                Frag::Glyphs { x, run, glyphs, w, space } => {
                    if space || glyphs.is_empty() || !run.vis { if run.deco != 0 && space { l.out.items.push(Item::Rect { x: x + dx, y: base + run.px / 10, w, h: (run.px / 14).max(FX), color: run.color }); } continue; }
                    let y = base + run.shift;
                    if run.deco & 1 != 0 { l.out.items.push(Item::Rect { x: x + dx, y: y + run.px / 10, w, h: (run.px / 14).max(FX), color: run.color }); }
                    if run.deco & 2 != 0 { l.out.items.push(Item::Rect { x: x + dx, y: y - run.px * 3 / 10, w, h: (run.px / 14).max(FX), color: run.color }); }
                    for &(g, off, face) in &glyphs {
                        cov(line!());
                        let gx = x + dx + off; // absolute glyph x
                        let fits = matches!(&open, Some(Item::Text { y: oy, px: opx, color: oc, face: of, deco: od, x: ox, .. })
                            if *oy == y && *opx == run.px && *oc == run.color && *of == face && *od == run.deco && gx - *ox < 16000 * 16);
                        if !fits {
                            cov(line!());
                            close(&mut open, &mut l.out.items);
                            open = Some(Item::Text { x: gx, y, px: run.px, color: run.color, face, glyphs: Vec::new(), deco: run.deco, w: 0 });
                        }
                        if let Some(Item::Text { x: ox, glyphs: gv, w: ow, .. }) = &mut open {
                            gv.push((g as u32) << 16 | ((gx - *ox + 8) / 16).clamp(0, 65535) as u32);
                            *ow = (gx + w - off - *ox).max(*ow).max(gx - *ox);
                        }
                    }
                    if let Some(Item::Text { x: ox, w: ow, .. }) = &mut open { *ow = (*ow).max(x + dx + w - *ox); }
                }
                Frag::Atomic { x, it0, bx0, it1, bx1, ab0, ab1, h, mt, va, base: ab, .. } => {
                    close(&mut open, &mut l.out.items);
                    let top = if va == 1 { base - h / 2 - self.strut.1 / 3 } else if tb_on && va == 2 { base - above } else if tb_on && va == 3 { base + below - h } else { base - ab };
                    for i in &mut l.out.items[it0..it1] { i.shift(x + dx, top + mt); }
                    let wn = crate::why::watched();
                    if wn != u32::MAX && l.out.boxes[bx0..bx1].iter().any(|b| b.0 == wn) {
                        cov(line!());
                        crate::why::note("line", format!("atomic inline box moved into its line by ({}, {}): line x {} + align {}, line baseline {} − box baseline {} + margin-top {}{}",
                            crate::why::px(x + dx), crate::why::px(top + mt), crate::why::px(x), crate::why::px(dx), crate::why::px(base), crate::why::px(ab), crate::why::px(mt), if va == 1 { " (vertical-align: middle)" } else { "" }));
                    }
                    if wn != u32::MAX && l.abs[ab0..ab1].iter().any(|a| a.0 == wn) { crate::why::note("line", format!("static position carried with the atomic inline box by ({}, {})", crate::why::px(x + dx), crate::why::px(top + mt))); }
                    for b in &mut l.out.boxes[bx0..bx1] { b.1[0] += x + dx; b.1[1] += top + mt; }
                    // out-of-flow descendants queued while the atomic box sat at the origin move with it (static position)
                    for a in &mut l.abs[ab0..ab1] { a.1 += x + dx; a.2 += top + mt; }
                }
            }
        }
        close(&mut open, &mut l.out.items);
        let lh = above + below;
        for (e, x0, x1) in self.inl.drain(..) { if x1 > x0 { l.inl_pending.push((e, self.owner, [x0 + dx, self.y, x1 - x0, lh])); } }
        for (e, x0) in &self.open { if self.x > *x0 { l.inl_pending.push((*e, self.owner, [*x0 + dx, self.y, self.x - *x0, lh])); } }
        self.y = base + below;
        l.last_base = Some(base);
        self.lines += 1;
        self.first_line = false;
        let (a, b) = l.float_band(self.y, self.strut.0, self.x0, self.x0 + self.w);
        self.lx0 = a; self.lx1 = b;
        self.x = a;
        for o in &mut self.open { o.1 = a; } // an element continuing on the next line starts at its edge
    }
}

// ───────────── tables and flex ─────────────

impl<'a> Layout<'a> {
    /// Rows in visual order (header groups, bodies/direct rows, footers). Cells directly inside a table or a
    /// row group are wrapped in an anonymous row (CSS Tables 3 §3.2 fixup) — row node NONE.
    fn table_rows(&self, n: u32) -> Vec<(u32, Vec<u32>)> {
        let is_el = |c: u32| self.dom.nodes[c as usize].kind == Kind::Element;
        let rows_of = |parent: u32| -> Vec<(u32, Vec<u32>)> {
            let mut out: Vec<(u32, Vec<u32>)> = Vec::new();
            let mut anon: Vec<u32> = Vec::new();
            for c in self.flat_children(parent) {
                cov(line!());
                if !is_el(c) { continue; }
                match self.s(c).display {
                    Display::TableRow => {
                        cov(line!());
                        if !anon.is_empty() { out.push((NONE, std::mem::take(&mut anon))); }
                        let mut cells: Vec<u32> = self.flat_children(c).into_iter().filter(|&x| is_el(x) && !matches!(self.s(x).display, Display::None | Display::TableColumn | Display::TableColumnGroup)).collect();
                        // CSS 2.2 §17.2.1: a row whose content is not cells (text, inline boxes) wraps it in ONE anonymous cell — the row
                        // itself stands in for that cell (cppreference `.t-lines > span{display:table-row}`: ours 2 px, Chrome 68 px)
                        if self.patch(c, "patch.anon_cell") && !self.flat_children(c).into_iter().any(|x| is_el(x) && self.s(x).display == Display::TableCell)
                            && self.flat_children(c).into_iter().any(|x| !is_el(x) && !self.dom.text(x).trim().is_empty() || is_el(x) && self.s(x).display != Display::None) {
                            cells = vec![c];
                        }
                        out.push((c, cells));
                    }
                    Display::TableCell => anon.push(c),
                    _ => {}
                }
            }
            if !anon.is_empty() { out.push((NONE, anon)); }
            out
        };
        let mut groups: Vec<(u8, u32)> = Vec::new();
        let mut direct = false;
        for c in self.flat_children(n) {
            cov(line!());
            if !is_el(c) { continue; }
            match self.s(c).display {
                Display::TableHeaderGroup => groups.push((0, c)),
                Display::TableRowGroup => groups.push((1, c)),
                Display::TableFooterGroup => groups.push((2, c)),
                Display::TableRow | Display::TableCell => direct = true,
                _ => {}
            }
        }
        let mut out = Vec::new();
        for pass in 0..3u8 {
            cov(line!());
            for &(k, g) in &groups { if k == pass { out.extend(rows_of(g)); } }
            if pass == 1 && direct { out.extend(rows_of(n)); }
        }
        out
    }

    fn table(&mut self, n: u32, cx: i32, cy: i32, cw: i32) -> i32 {
        self.mark(n, "path.table");
        // captions (caption-side: top) take the table's width
        let mut top = cy;
        for c in self.flat_children(n) {
            cov(line!());
            if self.dom.nodes[c as usize].kind == Kind::Element && self.s(c).display == Display::TableCaption {
                cov(line!());
                let cs = self.s(c).clone();
                let (ml, _mr, w) = self.hsizes(&cs, c, cw);
                let mt = res0(cs.margin[0], cw);
                top += mt + self.block_box(c, cx + ml, top + mt, w, false) + res0(cs.margin[2], cw);
            }
        }
        let cy0 = cy;
        let cy = top;
        let rows_cells = self.table_rows(n);
        let rows: Vec<u32> = rows_cells.iter().map(|r| r.0).collect();
        let cells: Vec<Vec<u32>> = rows_cells.into_iter().map(|r| r.1).collect();
        let ncol = cells.iter().map(|r| r.iter().map(|&c| self.colspan(c)).sum::<usize>()).max().unwrap_or(0);
        if ncol == 0 {
            cov(line!());
            // no rows: the non-caption content flows normally (anonymous table box)
            let kids: Vec<u32> = self.flat_children(n).into_iter().filter(|&c| !(self.dom.nodes[c as usize].kind == Kind::Element && self.s(c).display == Display::TableCaption)).collect();
            let _ = kids;
            return self.flow_except_captions(n, cx, cy, cw) + (cy - cy0);
        }
        let spacing = self.term(n, "table.spacing", self.css_spacing(n));
        let (mut mn, mut mx) = (vec![0i32; ncol], vec![0i32; ncol]);
        let mut fixed = vec![false; ncol]; // columns with a cell of specified length width (CSS 2.2 §17.5.2.2 auto layout)
        // DOCTOR port (PATCH station, PROPOSED): donor = this file's intrinsic_w table branch (spanning cells widen only what they
        // must, CSS 2.2 §17.5.2.2), found by reverse-PIFS (collage err 0.28, map cmn→mn cmx→mx sp→span); dormant unless the
        // program sets patch.table_span_widen[ctx] = −1 through the core's gate
        let mut spans: Vec<(usize, usize, i32, i32)> = Vec::new();
        for r in &cells {
            cov(line!());
            let mut col = 0;
            for &c in r {
                cov(line!());
                let span = self.colspan(c);
                let (a, b) = self.intrinsic_w(c);
                let (a, b) = (self.term(c, "table.cell_min", a), self.term(c, "table.cell_max", b));
                let cs = self.s(c).clone();
                let spec = match cs.width { Len::Px(w) if self.rule(c, "rule.table_cell_spec_width") => Some(if cs.border_box { w } else { w + self.hframe(&cs, cw) }), _ => None };
                let b = spec.map(|w| w.max(a)).unwrap_or(b);
                if span == 1 && col < ncol { mn[col] = mn[col].max(a); mx[col] = mx[col].max(b); if spec.is_some() { fixed[col] = true; } } else if span > 1 && col < ncol && self.patch(n, "patch.table_span_widen") { spans.push((col, span.min(ncol - col), a, b)); }
                col += span;
            }
        }
        for (col, sp, a, b) in spans {
            cov(line!());
            let end = (col + sp).min(ncol);
            let gaps = spacing * (sp as i32 - 1);
            let (hm, hx): (i32, i32) = (mn[col..end].iter().sum::<i32>() + gaps, mx[col..end].iter().sum::<i32>() + gaps);
            // Chrome black-box law (oracle_synth table-span-col1, 88/88 within 1/64 px): a spanning cell's excess goes to the spanned
            // columns IN PROPORTION TO THEIR MAX-CONTENT widths, col_k += excess · mx_k / Σmx — not an equal split (the BUGLIB tables
            // gatherer wrote both; the oracle decided). Equal shares only when every spanned max-content width is 0.
            let prop = self.patch(n, "patch.table_span_prop");
            let wsum: i64 = mx[col..end].iter().map(|&v| v as i64).sum();
            let split = |excess: i32, k: usize, w: &[i32]| -> i32 { if prop && wsum > 0 { (excess as i64 * w[k] as i64 / wsum) as i32 } else { excess / sp as i32 } };
            let mx0 = mx.clone();
            // shares must add up to the excess exactly (truncated shares left the span a few 1/64 px short → its text wrapped):
            // the remainder goes to the last spanned column
            if a > hm { let ex = a - hm; let mut given = 0; for k in col..end { let d = if k + 1 == end && prop { ex - given } else { split(ex, k, &mx0) }; mn[k] += d; given += d; } }
            if b > hx { let ex = b - hx; let mut given = 0; for k in col..end { let d = if k + 1 == end && prop { ex - given } else { split(ex, k, &mx0) }; mx[k] += d; given += d; } }
        }
        let s = self.s(n).clone();
        let avail = (cw - spacing * (ncol as i32 + 1)).max(0);
        let fixed_w = res(s.width, cw).is_some();
        let (smn, smx): (i32, i32) = (mn.iter().sum(), mx.iter().sum());
        // DOCTOR (PROPOSED, dormant unless patch.table_layout_fixed[ctx] = −1): fixed table layout, CSS 2.2 §17.5.2.1, clean-room
        // from the spec text — column widths come from the FIRST ROW's cells with a specified width (split across their span),
        // the remaining columns share the remaining width equally, cell content is never measured; a table wider than its
        // columns gives the extra to every column. Applies only when the table's own width is not auto (§17.5.2.1).
        // Diagnosed by the doctor: 18 of the 21 "no knob" too-narrow cells sit in github's table-layout:fixed tables.
        let fixed_layout = s.table_fixed && fixed_w && self.patch(n, "patch.table_layout_fixed");
        let widths: Vec<i32> = if fixed_layout {
            let mut w: Vec<Option<i32>> = vec![None; ncol];
            if let Some(r) = cells.first() {
                cov(line!());
                let mut col = 0;
                for &c in r {
                    cov(line!());
                    let span = self.colspan(c).min(ncol.saturating_sub(col)).max(1);
                    let cs = self.s(c).clone();
                    if let Some(cwid) = res(cs.width, avail) {
                        cov(line!());
                        let bw = if cs.border_box { cwid } else { cwid + self.hframe(&cs, cw) };
                        let each = (bw - spacing * (span as i32 - 1)).max(0) / span as i32;
                        for k in col..(col + span).min(ncol) { w[k] = Some(each); }
                    }
                    col += span;
                }
            }
            let used: i32 = w.iter().flatten().sum();
            let nfree = w.iter().filter(|x| x.is_none()).count() as i32;
            let mut v: Vec<i32> = w.iter().map(|x| x.unwrap_or(if nfree > 0 { (avail - used).max(0) / nfree } else { 0 })).collect();
            if nfree == 0 && used < avail && ncol > 0 { let add = (avail - used) / ncol as i32; for x in &mut v { *x += add; } }
            v
        } else if smx <= avail && (!fixed_w || !self.rule(n, "rule.table_fill_specified_width")) { mx.clone() }
            else if smx <= avail {
                // extra space goes to auto columns (proportional to max-content); fixed-width columns keep their width
                let auto_mx: i64 = (0..ncol).filter(|&k| !fixed[k]).map(|k| mx[k] as i64).sum();
                let extra = self.term(n, "table.extra_auto", avail - smx) as i64;
                if auto_mx > 0 { (0..ncol).map(|k| if fixed[k] { mx[k] } else { mx[k] + (extra * mx[k] as i64 / auto_mx) as i32 }).collect() }
                else if (0..ncol).any(|k| !fixed[k]) { let na = (0..ncol).filter(|&k| !fixed[k]).count() as i64; (0..ncol).map(|k| if fixed[k] { mx[k] } else { mx[k] + (extra / na) as i32 }).collect() }
                else { mx.iter().map(|&m| if smx > 0 { (m as i64 * avail as i64 / smx as i64) as i32 } else { avail / ncol as i32 }).collect() }
            }
            else if smn >= avail { mn.clone() }
            else { let extra = self.term(n, "table.extra_minmax", avail - smn); let d = (smx - smn).max(1); mn.iter().zip(&mx).map(|(&a, &b)| a + ((b - a) as i64 * extra as i64 / d as i64) as i32).collect() };
        let mut y = cy + spacing;
        for (ri, r) in cells.iter().enumerate() {
            cov(line!());
            let mut x = cx + spacing;
            let mut col = 0;
            let mut row_h = 0;
            let start_items = self.out.items.len();
            let mut placed = Vec::new();
            for &c in r {
                cov(line!());
                let span = self.colspan(c).min(ncol.saturating_sub(col)).max(1);
                let w: i32 = widths[col..(col + span).min(ncol)].iter().sum::<i32>() + spacing * (span as i32 - 1);
                let it0 = self.out.items.len();
                let bx0 = self.out.boxes.len();
                let ab0 = self.abs.len();
                // a non-cell child sits in an anonymous cell (CSS 2.2 §17.2.1); an inline-level one keeps its shrink-to-fit width
                let bw = if matches!(self.s(c).display, Display::InlineFlex | Display::InlineBlock | Display::InlineGrid | Display::InlineTable) { self.shrink_to_fit(c, w).min(w) } else { w };
                let h = self.block_box(c, x, y, bw, false);
                placed.push((c, it0, bx0, ab0, self.abs.len(), h));
                row_h = row_h.max(h);
                x += w + spacing;
                col += span;
            }
            let _ = start_items;
            // a row's own specified height is its minimum (also for rows with no cells, e.g. spacer rows)
            if rows[ri] != NONE { if let Len::Px(rh) = self.s(rows[ri]).height { row_h = row_h.max(self.term(rows[ri], "table.row_spec_h", rh)); } }
            // cells span the row height; content aligns by vertical-align (middle = the tbody default)
            for (c, it0, bx0, ab0, ab1, h) in placed {
                cov(line!());
                if h >= row_h { continue; }
                let va = self.s(c).vertical_align;
                let dy = self.term(c, "table.valign_dy", match va { 1 => (row_h - h) / 2, 3 => row_h - h, _ => 0 });
                // cell background must stay put and grow; content moves
                let cell_bg = self.out.items[it0..].iter().position(|i| matches!(i, Item::Rect { .. })).map(|k| it0 + k);
                let it_end = self.out.items.len();
                let bx_end = self.out.boxes.len();
                if dy != 0 {
                    cov(line!());
                    for k in it0..it_end {
                        cov(line!());
                        if Some(k) == cell_bg { continue; }
                        self.out.items[k].shift(0, dy);
                    }
                    for b in &mut self.out.boxes[bx0..bx_end] { if b.0 != c { b.1[1] += dy; } }
                    for a in &mut self.abs[ab0..ab1] { a.2 += dy; } // queued static positions move with the cell content
                }
                if let Some(k) = cell_bg { if let Item::Rect { h: rh, y: ry, .. } = &mut self.out.items[k] { if *ry == y { *rh = row_h; } } }
                if let Some(b) = self.out.boxes[bx0..].iter_mut().find(|b| b.0 == c) { b.1[3] = row_h; }
            }
            if rows[ri] != NONE { self.out.boxes.push((rows[ri], [cx, y, cw, row_h])); }
            y += row_h + spacing;
        }
        y - cy0
    }

    fn flow_except_captions(&mut self, n: u32, cx: i32, cy: i32, cw: i32) -> i32 {
        self.mark(n, "path.table_flow");
        let mut y = cy;
        for c in self.flat_children(n) {
            cov(line!());
            if self.dom.nodes[c as usize].kind == Kind::Element && self.s(c).display == Display::TableCaption { continue; }
            if self.dom.nodes[c as usize].kind == Kind::Text { if self.dom.text(c).trim().is_empty() { continue; } y += self.inline(n, &[c], cx, y, cw); continue; }
            if is_block_level(self.disp(c)) && self.s_float(c) == 0 && !self.is_abs(c) { y += self.block(c, cx, y, cw, false); }
            else { y += self.inline(n, &[c], cx, y, cw); }
        }
        y - cy
    }

    /// DORMANT behind patch.css_border_spacing; the D2c condition search (311 gates) found [Table&tag=table&w_set=0] = +76, 0 lost
    /// (unconditioned: +132 / −14 — nested navbox tables and wikitables in the collapsing model lose; open card: full
    /// collapsing-border model, CSS 2.2 §17.6.2). Old rule = attribute else 2 px.
    /// Table cell spacing: the `cellspacing` attribute (presentational hint, kept first as before), else the CSS
    /// border-spacing (CSS 2.2 §17.6.1; the UA sheet gives <table> 2 px, the initial value 0 covers display:table elements),
    /// 0 in the collapsing border model (§17.6.2). DOCTOR missing-feature card: border-spacing / border-collapse.
    fn css_spacing(&self, n: u32) -> i32 {
        let s = self.s(n);
        let old = self.dom.attr(n, "cellspacing").and_then(|v| v.trim().parse::<i32>().ok()).map(|v| v * FX).unwrap_or(2 * FX);
        let new = if s.border_collapse { 0 } else { self.dom.attr(n, "cellspacing").and_then(|v| v.trim().parse::<i32>().ok()).map(|v| v * FX).unwrap_or(s.border_spacing) };
        // a display:table that is not a <table> element has no UA 2 px: its spacing is the inherited CSS value (initial 0)
        if self.patch(n, "patch.css_border_spacing") || (self.dom.tag(n) != "table" && self.patch(n, "patch.nontable_spacing")) { new } else { old }
    }
    fn colspan(&self, c: u32) -> usize { self.dom.attr(c, "colspan").and_then(|v| v.trim().parse::<usize>().ok()).unwrap_or(1).clamp(1, 64) }

    fn flex(&mut self, n: u32, cx: i32, cy: i32, cw: i32) -> i32 {
        let ab0 = self.abs.len();
        let h = self.flex_items(n, cx, cy, cw);
        // an out-of-flow child's static position = where it would sit as the sole flex item (Flexbox §4.1)
        let s = self.s(n).clone();
        let min_inner = match s.min_h { Len::Px(v) => v - if s.border_box { res0(s.padding[0], cw) + res0(s.padding[2], cw) + s.border_w[0] + s.border_w[2] } else { 0 }, _ => 0 };
        let ch = self.cbh.last().copied().flatten().unwrap_or(h).max(h).max(min_inner);
        let parent_of = |l: &Self, c: u32| l.dom.nodes[c as usize].parent;
        for k in ab0..self.abs.len() {
            cov(line!());
            let (c, sx, sy, _) = self.abs[k];
            if parent_of(self, c) != n || sx != cx || sy != cy { continue; }
            let cs = self.s(c).clone();
            let w = self.fit_width(&cs, c, cw);
            let hh = match cs.height { Len::Px(v) => v, _ => 0 };
            // the margin box is what gets aligned; place_abs then adds the start margin
            let (mw, mh) = (w + res0(cs.margin[1], cw) + res0(cs.margin[3], cw), hh + res0(cs.margin[0], cw) + res0(cs.margin[2], cw));
            let (main_free, cross_free) = if s.flex_dir >= 2 { (ch - mh, cw - mw) } else { (cw - mw, ch - mh) };
            let main = match s.justify { 1 => main_free, 2 => main_free / 2, _ => 0 };
            let cross = match s.align_items { 2 => cross_free, 3 => cross_free / 2, _ => 0 };
            let (dx, dy) = if s.flex_dir >= 2 { (cross, main) } else { (main, cross) };
            crate::why!(c, "abs-static", "sole-flex-item static position: margin box {}×{} in flex content {}×{} → offset ({}, {}) [justify {} align-items {}]", crate::why::px(mw), crate::why::px(mh), crate::why::px(cw), crate::why::px(ch), crate::why::px(dx.max(0)), crate::why::px(dy.max(0)), s.justify, s.align_items);
            self.abs[k].1 += dx.max(0);
            self.abs[k].2 += dy.max(0);
        }
        h
    }

    fn flex_items(&mut self, n: u32, cx: i32, cy: i32, cw: i32) -> i32 {
        self.mark(n, "path.flex");
        let s = self.s(n).clone();
        let mut kids: Vec<u32> = self.flat_children(n).into_iter().filter(|&c| !(self.dom.nodes[c as usize].kind == Kind::Text && self.dom.text(c).trim().is_empty()) && !self.is_abs(c)).collect();
        // order-modified document order (Flexbox §5.4); stable, so equal orders keep source order
        kids.sort_by_key(|&c| if self.dom.nodes[c as usize].kind == Kind::Element { self.s(c).order } else { 0 });
        for &c in self.flat_children(n).iter() { if self.is_abs(c) { let cb = self.cb_node(); self.abs.push((c, cx, cy, cb)); } }
        let col_gap = self.term(n, "flex.col_gap", res0(s.gap[1], cw));
        let row_gap = self.term(n, "flex.row_gap", res0(s.gap[0], cw));
        if s.flex_dir >= 2 {
            cov(line!());
            self.mark(n, "path.flex_column");
            // column: stack items; cross size = container width (stretch) or shrink-to-fit
            let def_main = self.cbh.last().copied().flatten();
            // pass 1: hypothetical heights (content), recorded so a definite-height container can flex them
            struct Col { c: u32, x: i32, w: i32, mt: i32, mb: i32, h: i32, it0: usize, bx0: usize, ab0: usize, text: bool }
            let mut cols: Vec<Col> = Vec::new();
            let mut y = cy;
            for (k, &c) in kids.iter().enumerate() {
                cov(line!());
                if k > 0 { y += row_gap; }
                let (it0, bx0, ab0) = (self.out.items.len(), self.out.boxes.len(), self.abs.len());
                if self.dom.nodes[c as usize].kind == Kind::Text { let h = self.inline(n, &[c], cx, y, cw); cols.push(Col { c, x: cx, w: cw, mt: 0, mb: 0, h, it0, bx0, ab0, text: true }); y += h; continue; }
                let cs = self.s(c).clone();
                let (mt, mb) = (res0(cs.margin[0], cw), res0(cs.margin[2], cw));
                let w = if res(cs.width, cw).is_some() || s.align_items == 0 { self.hsizes(&cs, c, cw).2 } else { self.shrink_to_fit(c, cw) };
                let x = match s.align_items { 3 => cx + (cw - w) / 2, 2 => cx + cw - w, _ => cx + res0(cs.margin[3], cw) };
                let h = self.block_box(c, x, y + mt, w, false);
                cols.push(Col { c, x, w, mt, mb, h, it0, bx0, ab0, text: false });
                y += mt + h + mb;
            }
            let Some(avail) = def_main else { return y - cy };
            // pass 2 (Flexbox §9.7 on the vertical axis): grow / shrink into the container's definite height
            // flex base size (§9.2 C/D): a definite flex-basis (px, or % of the definite main size) replaces the content height as the
            // base; the content height stays the automatic minimum (theguardian sub-links: `flex-basis: 100%` in a stretched column
            // card → Chrome 56.4 px = 232.4 − the 176 px media, ours 0)
            let basis_on = self.patch(n, "patch.flex_col_basis");
            let base: Vec<i32> = cols.iter().map(|col| {
                if !basis_on || col.text || self.dom.nodes[col.c as usize].kind != Kind::Element { return col.h; }
                let cs = self.s(col.c);
                let fv = res0(cs.padding[0], cw) + res0(cs.padding[2], cw) + cs.border_w[0] + cs.border_w[2];
                match cs.basis { Len::Px(v) => if cs.border_box { v.max(fv) } else { v + fv }, Len::Pct(_) => { let v = res0(cs.basis, avail); if cs.border_box { v.max(fv) } else { v + fv } } _ => col.h }
            }).collect();
            let used = y - cy - cols.iter().map(|c| c.h).sum::<i32>() + base.iter().sum::<i32>();
            let free = avail - used;
            let el = |l: &Self, c: u32| l.dom.nodes[c as usize].kind == Kind::Element;
            let grow_sum: i32 = cols.iter().filter(|x| !x.text && el(self, x.c)).map(|x| self.s(x.c).grow as i32).sum();
            let shrink_sum: i64 = cols.iter().enumerate().filter(|(_, x)| !x.text && el(self, x.c)).map(|(i, x)| self.s(x.c).shrink as i64 * base[i] as i64).sum();
            let based = cols.iter().zip(base.iter()).any(|(c, b)| c.h != *b);
            let flexes = (free > 0 && grow_sum > 0) || (free < 0 && shrink_sum > 0) || based;
            if !flexes {
                cov(line!());
                // auto margins on the main axis take the positive free space first, in equal shares (Flexbox §8.1 / §9.5), and
                // justify-content then sees none (theguardian card footer `margin-top: auto` in a stretched column: Chrome puts it
                // at the bottom of the 308.7 px card, ours left it under the headline)
                let am: Vec<(bool, bool)> = cols.iter().map(|c| if c.text || !el(self, c.c) { (false, false) } else {
                    let cs = self.s(c.c); (matches!(cs.margin[0], Len::Auto), matches!(cs.margin[2], Len::Auto)) }).collect();
                let n_auto: i32 = am.iter().map(|&(t, b)| t as i32 + b as i32).sum();
                if free > 0 && n_auto > 0 && self.patch(n, "patch.flex_col_auto_margin") {
                    let share = free / n_auto;
                    let (ie, be, ae) = (self.out.items.len(), self.out.boxes.len(), self.abs.len());
                    let mut acc = 0;
                    for k in 0..cols.len() {
                        if am[k].0 { acc += share; }
                        let (i1, b1, a1) = cols.get(k + 1).map(|x| (x.it0, x.bx0, x.ab0)).unwrap_or((ie, be, ae));
                        if acc > 0 { self.shift_span(cols[k].it0..i1, cols[k].bx0..b1, cols[k].ab0..a1, 0, acc); }
                        if am[k].1 { acc += share; }
                    }
                    return used.max(0);
                }
                // justify-content on the column's main axis
                let off = self.term(n, "flex.col_justify_off", match s.justify { 1 => free, 2 => free / 2, _ => 0 });
                if off > 0 { let (ie, be, ae) = (self.out.items.len(), self.out.boxes.len(), self.abs.len()); let (i0, b0, a0) = cols.first().map(|x| (x.it0, x.bx0, x.ab0)).unwrap_or((ie, be, ae)); self.shift_span(i0..ie, b0..be, a0..ae, 0, off); }
                return used.max(0);
            }
            // distribute, clamp to [floor, max], freeze the clamped, redistribute what is left (Flexbox §9.7 loop)
            let lims: Vec<(i32, i32, i32, i32)> = cols.iter().map(|col| {
                if col.text || !el(self, col.c) { return (col.h, col.h, 0, 0); }
                let cs = self.s(col.c).clone();
                // automatic minimum: a visible-overflow item never shrinks below its content; scroll containers may
                let floor = if cs.overflow == 0 && matches!(cs.min_h, Len::Auto) { col.h } else { res(cs.min_h, avail).unwrap_or(0) };
                let cap = res(cs.max_h, avail).map(|m| m.max(floor)).unwrap_or(i32::MAX);
                (floor, cap, cs.grow as i32, cs.shrink as i32)
            }).collect();
            let mut target: Vec<i32> = base.iter().enumerate().map(|(i, b)| (*b).max(lims[i].0).min(lims[i].1)).collect();
            let mut frozen: Vec<bool> = lims.iter().map(|l| if free > 0 { l.2 == 0 } else { l.3 == 0 }).collect();
            for _ in 0..6 {
                cov(line!());
                let left = avail - (used - base.iter().sum::<i32>() + target.iter().sum::<i32>());
                if left == 0 || frozen.iter().all(|f| *f) { break; }
                let gs: i64 = (0..cols.len()).filter(|&i| !frozen[i]).map(|i| if free > 0 { lims[i].2 as i64 } else { lims[i].3 as i64 * base[i] as i64 }).sum();
                if gs == 0 { break; }
                let mut clamped = false;
                let exact = self.patch(n, "patch.exact_split");
                let (mut acc_w, mut prev_c) = (0i64, 0i64);
                for i in 0..cols.len() {
                    cov(line!());
                    if frozen[i] { continue; }
                    let wgt = if free > 0 { lims[i].2 as i64 } else { lims[i].3 as i64 * base[i] as i64 };
                    let share = if exact { acc_w += wgt; let cum = left as i64 * acc_w / gs; let sh = cum - prev_c; prev_c = cum; sh as i32 } else { (left as i64 * wgt / gs) as i32 };
                    let raw = target[i] + share;
                    let t = raw.max(lims[i].0).min(lims[i].1);
                    target[i] = t.max(0);
                    if t != raw { frozen[i] = true; clamped = true; }
                }
                if !clamped { break; }
            }
            // drop pass-1 output, lay the items out again at their flexed heights
            let (i0, b0, a0) = (cols[0].it0, cols[0].bx0, cols[0].ab0);
            self.out.items.truncate(i0); self.out.boxes.truncate(b0); self.abs.truncate(a0);
            self.out.inline.retain(|e| (e.1 as usize) < b0);
            let mut y = cy;
            for (k, col) in cols.iter().enumerate() {
                cov(line!());
                if k > 0 { y += row_gap; }
                if col.text { y += self.inline(n, &[col.c], cx, y, cw); continue; }
                crate::why!(col.c, "flex", "column item: content {} → flexed {} (container {} free {})", crate::why::px(col.h), crate::why::px(target[k]), crate::why::px(avail), crate::why::px(free));
                if target[k] != col.h { self.forced_h = Some((col.c, target[k])); }
                let h = self.block_box(col.c, col.x, y + col.mt, col.w, false);
                self.forced_h = None;
                y += col.mt + h + col.mb;
            }
            return (y - cy).max(0);
        }
        // row: hypothetical main sizes from flex-basis / width / max-content
        struct It { c: u32, base: i32, w: i32, amin: i32, amax: i32, ml: i32, mr: i32, grow: i32, shrink: i32, aml: bool, amr: bool }
        let mut its: Vec<It> = Vec::new();
        for &c in &kids {
            cov(line!());
            if self.dom.nodes[c as usize].kind == Kind::Text {
                cov(line!());
                let (_, mx) = self.text_widths(c, n);
                its.push(It { c, base: mx, w: mx, amin: 0, amax: i32::MAX, ml: 0, mr: 0, grow: 0, shrink: 100, aml: false, amr: false });
                continue;
            }
            let cs = self.s(c).clone();
            let frame = self.hframe(&cs, cw);
            let base = match res(cs.basis, cw) {
                Some(b) if !matches!(cs.basis, Len::Auto) => if cs.border_box { b } else { b + frame },
                _ => match res(cs.width, cw) {
                    Some(w) => self.term(c, "flex.base_specified", if cs.border_box { w } else { w + frame }),
                    None if cs.width == Len::MinContent => self.intrinsic_w(c).0,
                    None => { let v = self.intrinsic_w(c).1; self.term(c, "flex.base_content", v) }
                },
            };
            // automatic minimum size (Flexbox §4.5): min(content size, specified size) for visible-overflow items
            let amin = if matches!(cs.min_w, Len::Auto) && cs.overflow == 0 && self.rule(c, "rule.flex_auto_min") {
                let content = self.intrinsic_w(c).0;
                match res(cs.width, cw) { Some(w) => content.min(if cs.border_box { w } else { w + frame }), None => content }
            } else { res(cs.min_w, cw).map(|m| if cs.border_box { m } else { m + frame }).unwrap_or(0) };
            let amax = res(cs.max_w, cw).map(|m| if cs.border_box { m } else { m + frame }).unwrap_or(i32::MAX);
            let base = base.max(if cs.shrink == 0 { base } else { 0 });
            its.push(It { c, base, w: base, amin, amax, ml: self.term(c, "flex.margin_l", res0(cs.margin[3], cw)), mr: self.term(c, "flex.margin_r", res0(cs.margin[1], cw)), grow: cs.grow as i32, shrink: cs.shrink as i32,
                aml: matches!(cs.margin[3], Len::Auto), amr: matches!(cs.margin[1], Len::Auto) });
        }
        if std::env::var("OMR_FLEX").map_or(false, |q| self.dom.attr(n, "class").unwrap_or("").contains(q.as_str())) {
            for it in &its { let cs = self.s(it.c); eprintln!("flex item <{} .{}> base {} grow {} shrink {} basis {:?} width {:?} cw {} wrap {}", self.dom.tag(it.c), self.dom.attr(it.c, "class").unwrap_or(""), it.base / 64, it.grow, it.shrink, cs.basis, cs.width, cw / 64, s.flex_wrap); }
        }
        // lines (wrap)
        let mut lines: Vec<std::ops::Range<usize>> = Vec::new();
        let mut st = 0;
        let mut used = 0;
        for (k, it) in its.iter().enumerate() {
            cov(line!());
            let need = it.base + it.ml + it.mr + if k > st { col_gap } else { 0 };
            if s.flex_wrap && k > st && used + need > cw { lines.push(st..k); st = k; used = it.base + it.ml + it.mr; } else { used += need; }
        }
        lines.push(st..its.len());
        let mut y = cy;
        for (li, r) in lines.into_iter().enumerate() {
            cov(line!());
            if li > 0 { y += row_gap; }
            let n_it = r.len() as i32;
            // Flexbox §9.7: distribute free space, clamp by min/max, freeze the violators, redistribute the rest
            let mut frozen = vec![false; r.len()];
            for pass in 0..4 {
                cov(line!());
                let tot: i32 = its[r.clone()].iter().enumerate().map(|(k, i)| if frozen[k] { i.w } else { i.base } + i.ml + i.mr).sum::<i32>() + col_gap * (n_it - 1).max(0);
                let free = cw - tot;
                let gsum: i32 = its[r.clone()].iter().enumerate().filter(|(k, _)| !frozen[*k]).map(|(_, i)| i.grow).sum();
                let ssum: i64 = its[r.clone()].iter().enumerate().filter(|(k, _)| !frozen[*k]).map(|(_, i)| i.shrink as i64 * i.base as i64).sum();
                let mut clamped_any = false;
                let prog = program();
                let ctxs: Vec<String> = its[r.clone()].iter().map(|i| if self.dom.nodes[i.c as usize].kind == Kind::Element { self.pctx(self.s(i.c).display) } else { "Text".into() }).collect();
                // PRISTINE split (patch.exact_split): cumulative rounding of the grow / shrink shares, so they sum to the free space exactly
                let exact = self.patch(n, "patch.exact_split");
                let (mut acc_w, mut prev_c) = (0i64, 0i64);
                for (k, i) in its[r.clone()].iter_mut().enumerate() {
                    cov(line!());
                    if frozen[k] { continue; }
                    let pw = |t: usize| prog.weight("flex.main", &ctxs[k], t);
                    let mut share = |wgt: i64, tot: i64| -> i64 { if exact { acc_w += wgt; let cum = free as i64 * acc_w / tot; let sh = cum - prev_c; prev_c = cum; sh } else { free as i64 * wgt / tot } };
                    let raw = if free > 0 && gsum > 0 { i.base + pw(0) * share(i.grow as i64, gsum as i64) as i32 }
                              else if free < 0 && ssum > 0 { (i.base + pw(1) * share(i.shrink as i64 * i.base as i64, ssum) as i32).max(0) }
                              else { i.base };
                    let capped = if pw(3) != 0 { raw.min(i.amax) } else { raw };
                    i.w = if pw(2) != 0 { capped.max(i.amin) } else { capped };
                    if i.w != raw { frozen[k] = true; clamped_any = true; }
                    crate::why!(i.c, "flex", "flex item (pass {}): base {} grow {} shrink {} line free {} → {}; clamp [min {} (auto minimum §4.5 or min-width), max {}] → main size {}",
                        pass + 1, crate::why::px(i.base), i.grow, i.shrink, crate::why::px(free), crate::why::px(raw), crate::why::px(i.amin), crate::why::px(i.amax), crate::why::px(i.w));
                }
                if !clamped_any { break; }
            }
            let used: i32 = its[r.clone()].iter().map(|i| i.w + i.ml + i.mr).sum::<i32>() + col_gap * (n_it - 1).max(0);
            let mut rem = (cw - used).max(0);
            // Flexbox §8.1: auto margins take the free space first (before justify-content)
            let n_auto: i32 = its[r.clone()].iter().map(|i| i.aml as i32 + i.amr as i32).sum();
            if n_auto > 0 && rem > 0 {
                cov(line!());
                let share = rem / n_auto;
                for i in &mut its[r.clone()] { if i.aml { i.ml += share; } if i.amr { i.mr += share; } }
                rem = 0;
            }
            let (mut x, gap) = match s.justify {
                1 => (cx + rem, col_gap), 2 => (cx + rem / 2, col_gap),
                3 if n_it > 1 => (cx, col_gap + rem / (n_it - 1)),
                4 => (cx + rem / (2 * n_it.max(1)), col_gap + rem / n_it.max(1)),
                5 => (cx + rem / (n_it + 1), col_gap + rem / (n_it + 1)),
                _ => (cx, col_gap),
            };
            if s.flex_dir == 1 { x = cx + cw - (x - cx); }
            let mut placed = Vec::new();
            let mut line_h = 0;
            for (k, i) in its[r.clone()].iter().enumerate() {
                cov(line!());
                if k > 0 { if s.flex_dir == 1 { x -= gap } else { x += gap } }
                let it0 = self.out.items.len();
                let bx0 = self.out.boxes.len();
                let ab0 = self.abs.len();
                let (bx, h) = if self.dom.nodes[i.c as usize].kind == Kind::Text {
                    let xx = if s.flex_dir == 1 { x - i.w } else { x };
                    (xx, self.inline(n, &[i.c], xx, y, i.w + FX))
                } else {
                    cov(line!());
                    let cs = self.s(i.c).clone();
                    let mt = res0(cs.margin[0], cw);
                    let xx = if s.flex_dir == 1 { x - i.mr - i.w } else { x + i.ml };
                    let h = self.block_box(i.c, xx, y + mt, i.w, false);
                    (xx, h + mt + res0(cs.margin[2], cw))
                };
                placed.push((it0, bx0, self.out.items.len(), self.out.boxes.len(), h, bx, ab0, self.abs.len()));
                line_h = line_h.max(h);
                if s.flex_dir == 1 { x -= i.w + i.ml + i.mr } else { x += i.w + i.ml + i.mr }
            }
            // a single-line container with a definite height (px, % of a definite block, or imposed) sets the line's cross size
            let def_inner = if s.flex_wrap { None } else { self.cbh.last().copied().flatten() };
            // ...and an auto-height single-line container's min-height floors it (Flexbox §9.4 step 15 clamps the container first)
            let min_inner = match s.min_h {
                Len::Px(v) if !s.flex_wrap => v - if s.border_box { res0(s.padding[0], cw) + res0(s.padding[2], cw) + s.border_w[0] + s.border_w[2] } else { 0 },
                _ => 0,
            };
            let line_h_eff = def_inner.unwrap_or(line_h).max(if def_inner.is_some() { 0 } else { line_h.max(min_inner) });
            // cross-axis alignment; stretched items (auto height) are laid out again at the line height (Flexbox §9.4 step 11)
            let mut drop_ranges: Vec<(std::ops::Range<usize>, std::ops::Range<usize>, std::ops::Range<usize>)> = Vec::new();
            for (k, (it0, bx0, it1, bx1, h, bx, ab0, ab1)) in placed.into_iter().enumerate() {
                cov(line!());
                let c = its[r.start + k].c;
                let is_el = self.dom.nodes[c as usize].kind == Kind::Element;
                let ai = if is_el { match self.s(c).align_self { 0 => s.align_items, 1 => 1, 2 => 2, 3 => 3, _ => s.align_items } } else { s.align_items };
                // a stretched item's cross size IS the line's (Flexbox §9.4 step 11): taller content overflows, it does not grow the line
                if ai == 0 && is_el && matches!(self.s(c).height, Len::Auto) && (h < line_h_eff || (def_inner.is_some() && h > line_h_eff)) {
                    cov(line!());
                    let cs = self.s(c).clone();
                    let (mt, mb) = (res0(cs.margin[0], cw), res0(cs.margin[2], cw));
                    drop_ranges.push((it0..it1, bx0..bx1, ab0..ab1));
                    self.forced_h = Some((c, (line_h_eff - mt - mb).max(0)));
                    self.block_box(c, bx, y + mt, its[r.start + k].w, false);
                    self.forced_h = None;
                    continue;
                }
                let off = self.term(c, "flex.cross_off", match ai { 3 => (line_h_eff - h) / 2, 2 => line_h_eff - h, _ => 0 });
                crate::why!(c, "flex", "cross axis: align {} in line height {} (item {}) → offset {}", ai, crate::why::px(line_h_eff), crate::why::px(h), crate::why::px(off));
                self.shift_span(it0..it1, bx0..bx1, ab0..ab1, 0, off);
            }
            for (it, b, ab) in drop_ranges.into_iter().rev() { self.out.items.drain(it); self.out.boxes.drain(b); self.abs.drain(ab); }
            y += line_h_eff;
        }
        y - cy
    }
}

impl Out {
    fn shift_range(&mut self, it: std::ops::Range<usize>, bx: std::ops::Range<usize>, dx: i32, dy: i32) {
        let w = crate::why::watched();
        if w != u32::MAX && self.boxes[bx.clone()].iter().any(|b| b.0 == w) { crate::why::note("move", format!("subtree moved by ({}, {}) — flex cross alignment / grid area placement / relative / translate / bottom inset", crate::why::px(dx), crate::why::px(dy))); }
        for i in &mut self.items[it] { i.shift(dx, dy); }
        for b in &mut self.boxes[bx] { b.1[0] += dx; b.1[1] += dy; }
    }
}

// ───────────── CSS Grid (Grid Layout 1: explicit + auto placement, fixed/auto/fr/minmax/repeat tracks) ─────────────

#[derive(Clone, Debug)]
enum Track { Fixed(i32), Fr(i32), Auto, MinC, MaxC, MinMax(Box<Track>, Box<Track>), Fit(i32) }

fn track_len(t: &[crate::css::Tok], cw: i32, fs: i32) -> Option<i32> {
    use crate::css::Tok;
    match t.first()? {
        Tok::Dim(v, u) => Some(match u.as_str() {
            "px" => v * FX as f32, "em" | "rem" => v * fs as f32, "vw" => v * 12.8 * FX as f32, "vh" => v * 8.0 * FX as f32,
            "pt" => v * 4.0 / 3.0 * FX as f32, "ch" => v * fs as f32 * 0.5, _ => return None } as i32),
        Tok::Pct(p) => Some((cw as f32 * p / 100.0) as i32),
        Tok::Num(n) if *n == 0.0 => Some(0),
        _ => None,
    }
}

fn parse_track(t: &[crate::css::Tok], cw: i32, fs: i32) -> Option<Track> {
    use crate::css::Tok;
    let t: Vec<Tok> = t.iter().filter(|x| **x != Tok::Ws).cloned().collect();
    match t.first()? {
        Tok::Dim(v, u) if u == "fr" => Some(Track::Fr((v * 100.0) as i32)),
        Tok::Ident(k) => Some(match k.to_ascii_lowercase().as_str() { "auto" => Track::Auto, "min-content" => Track::MinC, "max-content" => Track::MaxC, _ => return None }),
        Tok::Func(f) if f == "minmax" => {
            let inner = &t[1..t.len().saturating_sub(1)];
            let k = inner.iter().position(|x| *x == Tok::Comma)?;
            Some(Track::MinMax(Box::new(parse_track(&inner[..k], cw, fs)?), Box::new(parse_track(&inner[k + 1..], cw, fs)?)))
        }
        Tok::Func(f) if f == "fit-content" => Some(Track::Fit(track_len(&t[1..], cw, fs)?)),
        Tok::Func(f) if f == "calc" || f == "min" || f == "max" || f == "clamp" => Some(crate::style::eval_len_px(&t, fs, cw).map(Track::Fixed).unwrap_or(Track::Auto)),
        _ => track_len(&t, cw, fs).map(Track::Fixed),
    }
}

fn track_min(t: &Track) -> i32 { match t { Track::Fixed(v) => *v, Track::MinMax(a, _) => track_min(a), _ => 0 } }

/// Track list plus its named lines: `[a b] 1fr [c]` → line numbers (1-based) per name.
fn parse_tracks_named(src: &str, cw: i32, fs: i32, gap: i32) -> (Vec<Track>, HashMap<String, usize>) {
    use crate::css::{tokenize, Tok};
    let t: Vec<Tok> = tokenize(src);
    let mut names: HashMap<String, usize> = HashMap::new();
    // walk once to find bracketed names and the number of tracks emitted before each bracket
    let mut i = 0;
    let mut tracks: Vec<Track> = Vec::new();
    while i < t.len() {
        cov(line!());
        match &t[i] {
            Tok::LBrack => {
                cov(line!());
                let mut j = i + 1;
                while j < t.len() && t[j] != Tok::RBrack { if let Tok::Ident(n) = &t[j] { names.entry(n.clone()).or_insert(tracks.len() + 1); } j += 1; }
                i = j + 1;
            }
            Tok::Ws => i += 1,
            _ => {
                cov(line!());
                // the next track item (single token, or a function call) → expand with the plain parser
                let st = i;
                if let Tok::Func(_) = &t[i] {
                    cov(line!());
                    let mut d = 1; i += 1;
                    while i < t.len() && d > 0 { match t[i] { Tok::Func(_) | Tok::LParen => d += 1, Tok::RParen => d -= 1, _ => {} } i += 1; }
                } else { i += 1; }
                tracks.extend(parse_tracks(&crate::style::tok_str(&t[st..i]), cw, fs, gap));
            }
        }
    }
    (tracks, names)
}

/// Parse a track list; repeat(auto-fill|auto-fit|N, …) expanded against the available width.
fn parse_tracks(src: &str, cw: i32, fs: i32, gap: i32) -> Vec<Track> {
    use crate::css::{tokenize, Tok};
    let t: Vec<Tok> = tokenize(src);
    let mut out = Vec::new();
    let mut i = 0;
    while i < t.len() {
        cov(line!());
        match &t[i] {
            Tok::Ws => i += 1,
            Tok::LBrack => { while i < t.len() && t[i] != Tok::RBrack { i += 1; } i += 1; }
            Tok::Func(f) => {
                cov(line!());
                let f = f.clone();
                let mut d = 1; let mut j = i + 1;
                while j < t.len() { match t[j] { Tok::Func(_) | Tok::LParen => d += 1, Tok::RParen => { d -= 1; if d == 0 { break; } } _ => {} } j += 1; }
                let whole = &t[i..(j + 1).min(t.len())];
                if f == "repeat" {
                    let inner = &t[i + 1..j.min(t.len())];
                    if let Some(k) = inner.iter().position(|x| *x == Tok::Comma) {
                        cov(line!());
                        let body: Vec<Track> = parse_tracks(&crate::style::tok_str(&inner[k + 1..]), cw, fs, gap);
                        let count = match inner[..k].iter().find(|x| **x != Tok::Ws) {
                            Some(Tok::Num(n)) => *n as usize,
                            Some(Tok::Ident(_)) => {
                                cov(line!());
                                let unit: i32 = body.iter().map(track_min).sum::<i32>().max(FX) + gap * body.len() as i32;
                                (((cw + gap) / unit.max(1)) as usize).max(1)
                            }
                            _ => 1,
                        };
                        for _ in 0..count.min(256) { out.extend(body.iter().cloned()); }
                    }
                } else if let Some(tr) = parse_track(whole, cw, fs) { out.push(tr); }
                i = j + 1;
            }
            _ => {
                cov(line!());
                let st = i;
                i += 1;
                if let Some(tr) = parse_track(&t[st..i], cw, fs) { out.push(tr); }
            }
        }
    }
    out
}

/// grid-template-areas → name → (row0, col0, row1, col1) (end exclusive, 0-based).
fn parse_areas(src: &str) -> HashMap<String, (usize, usize, usize, usize)> {
    let mut m: HashMap<String, (usize, usize, usize, usize)> = HashMap::new();
    for (r, row) in src.split('"').skip(1).step_by(2).enumerate() {
        for (c, name) in row.split_whitespace().enumerate() {
            cov(line!());
            if name.chars().all(|ch| ch == '.') { continue; }
            let e = m.entry(name.to_string()).or_insert((r, c, r + 1, c + 1));
            e.0 = e.0.min(r); e.1 = e.1.min(c); e.2 = e.2.max(r + 1); e.3 = e.3.max(c + 1);
        }
    }
    m
}

/// One axis of a placement: "a / b", "span n", "n", "-1", area/line name. → (start 0-based or None, span)
fn parse_place(src: &str, n_lines: i32, areas: &HashMap<String, (usize, usize, usize, usize)>, col: bool, named: &HashMap<String, usize>) -> (Option<usize>, usize) {
    let parts: Vec<&str> = src.split('/').map(|x| x.trim()).collect();
    // CSS Grid §8.3 implicit named areas (doctor SHAPE → Chrome oracle, blackbox/oracle-grid-named 6/6): a <custom-ident> first
    // resolves to the line named <ident>-start on the start side / <ident>-end on the end side, and a lone ident as the start
    // also names the end (§8.4 shorthand: grid-column: a ≡ a / a)
    let named_area = patch_on("patch.grid_named_area");
    let line = |p: &str, is_end: bool| -> Option<i32> {
        if let Ok(v) = p.parse::<i32>() { return Some(if v < 0 { n_lines + 1 + v } else { v }); }
        if named_area { if let Some(&l) = named.get(&format!("{p}{}", if is_end { "-end" } else { "-start" })) { return Some(l as i32); } }
        if let Some(&l) = named.get(p) { return Some(l as i32); }
        if let Some(a) = areas.get(p.trim_end_matches("-start").trim_end_matches("-end")) {
            let (s, e) = if col { (a.1, a.3) } else { (a.0, a.2) };
            return Some(if is_end || p.ends_with("-end") { e as i32 + 1 } else { s as i32 + 1 });
        }
        None
    };
    let span_of = |p: &str| p.strip_prefix("span").and_then(|x| x.trim().parse::<usize>().ok().or(Some(1)));
    let a = parts.first().copied().unwrap_or("auto");
    let b = parts.get(1).copied();
    if let Some(sp) = span_of(a) { return (b.and_then(|b| line(b, true)).map(|e| (e - sp as i32 - 1).max(0) as usize), sp.max(1)); }
    let start = line(a, false);
    let span = match b {
        Some(b) => match span_of(b) { Some(sp) => sp, None => match (start, line(b, true)) { (Some(s), Some(e)) if e > s => (e - s) as usize, _ => 1 } },
        None => {
            cov(line!());
            // a bare area name spans the area
            if let Some(ar) = areas.get(a) { if col { ar.3 - ar.1 } else { ar.2 - ar.0 } }
            else if named_area && a.parse::<i32>().is_err() && a != "auto" { match (start, line(a, true)) { (Some(s), Some(e)) if e > s => (e - s) as usize, _ => 1 } }
            else { 1 }
        }
    };
    (start.map(|s| (s - 1).max(0) as usize), span.max(1))
}

impl<'a> Layout<'a> {
    pub(crate) fn grid(&mut self, n: u32, cx: i32, cy: i32, cw: i32) -> i32 {
        self.mark(n, "path.grid");
        let s = self.s(n).clone();
        let fs = s.font_size;
        let strs = &self.st.families;
        let (cgap, rgap) = (self.term(n, "grid.col_gap", res0(s.gap[1], cw)), self.term(n, "grid.row_gap", res0(s.gap[0], cw)));
        let areas = if s.grid_areas != 0 { parse_areas(&strs[s.grid_areas as usize]) } else { HashMap::new() };
        let (mut cols, col_names) = if s.grid_cols != 0 { parse_tracks_named(&strs[s.grid_cols as usize], cw, fs, cgap) } else { (Vec::new(), HashMap::new()) };
        let area_cols = areas.values().map(|a| a.3).max().unwrap_or(0);
        let auto_col = if s.grid_auto_cols != 0 { parse_tracks(&strs[s.grid_auto_cols as usize], cw, fs, cgap).into_iter().next() } else { None };
        // CSS Grid §7.1/§7.6: columns not sized by grid-template-columns (the ones only grid-template-areas names, and the first
        // column of a grid with no column template, which is implicit) take their size from grid-auto-columns
        let first_auto = self.patch(n, "patch.grid_auto_first");
        while cols.len() < area_cols.max(1) { cols.push(if first_auto { auto_col.clone().unwrap_or(Track::Auto) } else { Track::Auto }); }
        let (rows_t, row_names) = if s.grid_rows != 0 { parse_tracks_named(&strs[s.grid_rows as usize], cw, fs, rgap) } else { (Vec::new(), HashMap::new()) };
        let auto_row = if s.grid_auto_rows != 0 { parse_tracks(&strs[s.grid_auto_rows as usize], cw, fs, rgap).into_iter().next() } else { None };
        // grid-auto-flow: column fills down the explicit rows and adds implicit columns (CSS Grid §8.5)
        let col_flow = s.grid_flow & 1 == 1;
        let n_rows_explicit = rows_t.len().max(areas.values().map(|a| a.2).max().unwrap_or(0)).max(1);
        let kids: Vec<u32> = self.flat_children(n).into_iter()
            .filter(|&c| !(self.dom.nodes[c as usize].kind == Kind::Text && self.dom.text(c).trim().is_empty())).collect();
        for &c in &kids { if self.is_abs(c) { let cb = self.cb_node(); self.abs.push((c, cx, cy, cb)); } }
        let mut kids: Vec<u32> = kids.into_iter().filter(|&c| !self.is_abs(c)).collect();
        // CSS Grid §8.5: items are placed in ORDER-MODIFIED document order (stable sort by `order`), as flex does — Chrome
        // black-box (BUGLIB grid-00: order:2 / order:1 / none → C, A, B) and arstechnica's lg:order-N cards
        if self.patch(n, "patch.grid_order") { kids.sort_by_key(|&c| if self.dom.nodes[c as usize].kind == Kind::Element { self.s(c).order } else { 0 }); }
        // placement
        let mut ncols = cols.len();
        let mut occ: Vec<Vec<bool>> = Vec::new();
        let mut placed: Vec<(u32, usize, usize, usize, usize)> = Vec::new(); // node, row, col, rspan, cspan
        let (mut cur_r, mut cur_c) = (0usize, 0usize);
        let grow = |occ: &mut Vec<Vec<bool>>, rows: usize, nc: usize| { while occ.len() < rows { occ.push(vec![false; nc]); } }; // ensure `rows` rows exist
        for &c in &kids {
            cov(line!());
            let (mut pr, mut pc, mut rs, mut cs) = (None, None, 1usize, 1usize);
            if self.dom.nodes[c as usize].kind == Kind::Element {
                cov(line!());
                let is = self.s(c);
                if is.grid_area != 0 {
                    cov(line!());
                    let a = strs[is.grid_area as usize].trim().to_string();
                    if let Some(ar) = areas.get(&a) { pr = Some(ar.0); pc = Some(ar.1); rs = ar.2 - ar.0; cs = ar.3 - ar.1; }
                    else {
                        cov(line!());
                        let p: Vec<&str> = a.split('/').map(|x| x.trim()).collect();
                        if p.len() >= 2 { let (r0, r1) = parse_place(&format!("{} / {}", p[0], p.get(2).unwrap_or(&"auto")), 0, &areas, false, &row_names); pr = r0; rs = r1;
                                          let (c0, c1) = parse_place(&format!("{} / {}", p[1], p.get(3).unwrap_or(&"auto")), ncols as i32 + 1, &areas, true, &col_names); pc = c0; cs = c1; }
                    }
                }
                if is.grid_col != 0 { let (a, b) = parse_place(&strs[is.grid_col as usize], ncols as i32 + 1, &areas, true, &col_names); pc = a.or(pc); cs = b; }
                if is.grid_row != 0 { let (a, b) = parse_place(&strs[is.grid_row as usize], rows_t.len() as i32 + 1, &areas, false, &row_names); pr = a.or(pr); rs = b; }
            }
            let cs = cs.min(ncols.max(1));
            let (r, col) = match (pr, pc) {
                (Some(r), Some(cc)) => (r, cc.min(ncols.saturating_sub(cs))),
                (Some(r), None) => { let mut cc = 0; grow(&mut occ, r + rs, ncols); while cc + cs <= ncols && (0..cs).any(|k| occ[r][cc + k]) { cc += 1; } (r, cc.min(ncols - cs)) }
                (None, Some(cc)) => { let cc = cc.min(ncols.saturating_sub(cs)); let mut r = 0; loop { grow(&mut occ, r + rs, ncols); if (0..rs).all(|dr| (0..cs).all(|k| !occ[r + dr][cc + k])) { break; } r += 1; } (r, cc) }
                (None, None) if col_flow => {
                    cov(line!());
                    loop {
                        cov(line!());
                        if cur_r + rs > n_rows_explicit.max(rs) { cur_r = 0; cur_c += 1; }
                        while cur_c + cs > ncols {
                            cov(line!());
                            cols.push(auto_col.clone().unwrap_or(Track::Auto));
                            ncols += 1;
                            for row in occ.iter_mut() { row.push(false); }
                        }
                        grow(&mut occ, cur_r + rs, ncols);
                        if (0..rs).all(|dr| (0..cs).all(|k| !occ[cur_r + dr][cur_c + k])) { break; }
                        cur_r += 1;
                    }
                    let p = (cur_r, cur_c);
                    cur_r += rs;
                    p
                }
                (None, None) => {
                    cov(line!());
                    loop {
                        cov(line!());
                        if cur_c + cs > ncols { cur_c = 0; cur_r += 1; }
                        grow(&mut occ, cur_r + rs, ncols);
                        if (0..rs).all(|dr| (0..cs).all(|k| !occ[cur_r + dr][cur_c + k])) { break; }
                        cur_c += 1;
                    }
                    let p = (cur_r, cur_c);
                    cur_c += cs;
                    p
                }
            };
            grow(&mut occ, r + rs, ncols);
            for dr in 0..rs { for k in 0..cs { if col + k < ncols { occ[r + dr][col + k] = true; } } }
            placed.push((c, r, col, rs, cs));
        }
        // the explicit grid keeps every row of grid-template-rows / areas even when no item lands in it (CSS Grid §7.1) — an empty
        // `minmax(0, 1fr)` row still contributes its row gap (bbc index cards: min-content + empty 1fr row + 24 px gap)
        let nrows = if self.patch(n, "patch.grid_explicit_rows") { occ.len().max(n_rows_explicit).max(1) } else { occ.len().max(1) };
        // column sizing
        let avail = (cw - cgap * (ncols as i32 - 1)).max(0);
        let mut w = vec![0i32; ncols];
        let mut limit = vec![0i32; ncols];
        let mut fr = vec![0i32; ncols];
        for (k, t) in cols.iter().enumerate() {
            cov(line!());
            match t {
                Track::Fixed(v) => { w[k] = *v; limit[k] = *v; }
                Track::Fr(f) => fr[k] = *f,
                Track::MinMax(a, b) => {
                    cov(line!());
                    w[k] = track_min(a);
                    match **b { Track::Fr(f) => fr[k] = f, Track::Fixed(v) => limit[k] = v, _ => limit[k] = i32::MAX }
                }
                Track::Fit(v) => limit[k] = *v,
                _ => limit[k] = i32::MAX,
            }
        }
        // content contributions of single-column items to auto-ish tracks
        for &(c, _, col, _, cs) in &placed {
            cov(line!());
            if cs != 1 { continue; }
            let (mn, mx) = if self.dom.nodes[c as usize].kind == Kind::Text { self.text_widths(c, n) } else { self.intrinsic_w(c) };
            match &cols[col] {
                Track::Fixed(_) => {}
                Track::Fr(_) => { w[col] = w[col].max(mn.min(avail)); }
                Track::MinC => { w[col] = w[col].max(mn); limit[col] = w[col]; }
                Track::MaxC => { w[col] = w[col].max(mx); limit[col] = w[col]; }
                Track::Fit(v) => { w[col] = w[col].max(mn.min(*v)); limit[col] = mx.min(*v).max(w[col]); }
                Track::MinMax(a, b) => {
                    cov(line!());
                    if matches!(**a, Track::Auto | Track::MinC) { w[col] = w[col].max(mn); }
                    if matches!(**a, Track::MaxC) { w[col] = w[col].max(mx); }
                    if matches!(**b, Track::Auto | Track::MaxC) { limit[col] = limit[col].min(mx.max(w[col])).max(w[col]); if limit[col] == i32::MAX { limit[col] = mx; } }
                }
                Track::Auto => { w[col] = w[col].max(mn); if limit[col] == i32::MAX { limit[col] = 0; } limit[col] = limit[col].max(mx); }
            }
        }
        for k in 0..ncols { if limit[k] == i32::MAX { limit[k] = w[k]; } limit[k] = limit[k].max(w[k]); }
        let mut free = avail - w.iter().sum::<i32>();
        // grow non-fr tracks toward their limits
        if free > 0 {
            cov(line!());
            let want: i32 = (0..ncols).filter(|&k| fr[k] == 0).map(|k| limit[k] - w[k]).sum();
            if want > 0 {
                cov(line!());
                let give = free.min(want);
                if self.patch(n, "patch.grid_equal_grow") {
                    // CSS Grid 1 §12.6 Maximize Tracks: distribute the free space EQUALLY to the base sizes, freezing each track
                    // when it reaches its growth limit (DOCNEXT-S5: exposed by UAX #14 break points, PEP fit-content(30%) auto)
                    let mut left = give;
                    let mut open: Vec<usize> = (0..ncols).filter(|&k| fr[k] == 0 && limit[k] > w[k]).collect();
                    while left > 0 && !open.is_empty() {
                        cov(line!());
                        let share = (left / open.len() as i32).max(1);
                        for &k in &open { let d = share.min(limit[k] - w[k]).min(left); w[k] += d; left -= d; }
                        open.retain(|&k| limit[k] > w[k]);
                    }
                } else if self.rule(n, "rule.grid_grow_to_limit") { for k in 0..ncols { if fr[k] == 0 { w[k] += ((limit[k] - w[k]) as i64 * give as i64 / want as i64) as i32; } } }
                free -= give;
            }
        }
        let frsum: i32 = fr.iter().sum();
        if frsum > 0 && free > 0 {
            cov(line!());
            let flex_space = free + (0..ncols).filter(|&k| fr[k] > 0).map(|k| w[k]).sum::<i32>();
            // PRISTINE split (author 10-06, patch.exact_split): cumulative rounding — track k gets ⌊S·F_k/ΣF⌋ − ⌊S·F_{k−1}/ΣF⌋ (F = running fr sum),
            // so the tracks sum to the flex space EXACTLY; per-track truncation lost up to (n−1)/64 px and left the last item short of the edge
            if self.patch(n, "patch.exact_split") {
                let (mut acc, mut prev) = (0i64, 0i64);
                for k in 0..ncols { if fr[k] > 0 { acc += fr[k] as i64; let cum = flex_space as i64 * acc / frsum as i64; w[k] = w[k].max((cum - prev) as i32); prev = cum; } }
            } else {
                for k in 0..ncols { if fr[k] > 0 { w[k] = w[k].max((flex_space as i64 * fr[k] as i64 / frsum as i64) as i32); } }
            }
        } else if frsum == 0 && free > 0 {
            cov(line!());
            // justify-content: normal stretches auto tracks
            let autos: Vec<usize> = (0..ncols).filter(|&k| matches!(cols[k], Track::Auto)).collect();
            if !autos.is_empty() { let add = self.term(n, "grid.stretch_cols", free / autos.len() as i32); for &k in &autos { w[k] += add; } }
        }
        if std::env::var("OMR_GRID").map_or(false, |q| self.dom.attr(n, "class").unwrap_or("").contains(q.as_str())) {
            eprintln!("grid <{}> cw {} cols {} cgap {} widths {:?} placed {:?}", self.dom.attr(n, "class").unwrap_or(""), cw / 64, ncols, cgap / 64, w.iter().map(|x| x / 64).collect::<Vec<_>>(), placed.iter().map(|p| (p.1, p.2, p.3, p.4)).collect::<Vec<_>>());
        }
        let mut xs = vec![cx; ncols + 1];
        for k in 0..ncols { xs[k + 1] = xs[k] + w[k] + if k + 1 < ncols { cgap } else { 0 }; }
        // lay out items at origin to get heights
        struct Laid { it0: usize, it1: usize, bx0: usize, bx1: usize, ab0: usize, ab1: usize, h: i32, w: i32 }
        let mut laid = Vec::with_capacity(placed.len());
        for &(c, _, col, _, cs) in &placed {
            cov(line!());
            let aw = xs[(col + cs).min(ncols)] - xs[col] - if col + cs < ncols { cgap } else { 0 };
            let it0 = self.out.items.len();
            let bx0 = self.out.boxes.len();
            let ab0 = self.abs.len();
            let (h, iw) = if self.dom.nodes[c as usize].kind == Kind::Text {
                (self.inline(n, &[c], 0, 0, aw), aw)
            } else {
                cov(line!());
                let is = self.s(c).clone();
                // justify-items (CSS Box Alignment 3 §6.1, clean-room; DOCTOR missing-feature card) is the default justify-self.
                // (the earlier hold-back for grid-container items was lifted once grid intrinsic sizing landed: bbc 0 lost)
                let js_eff = if is.justify_self != 0 { is.justify_self } else { s.justify_items };
                let (ml, _mr, bw) = if js_eff != 0 && res(is.width, aw).is_none() { (res0(is.margin[3], aw), 0, self.shrink_to_fit(c, aw)) } else { self.hsizes(&is, c, aw) };
                let mt = res0(is.margin[0], aw);
                let saved = std::mem::take(&mut self.floats);
                let h = self.block_box(c, ml, mt, bw, false);
                self.floats = saved;
                (mt + h + res0(is.margin[2], aw), bw)
            };
            laid.push(Laid { it0, it1: self.out.items.len(), bx0, bx1: self.out.boxes.len(), ab0, ab1: self.abs.len(), h, w: iw });
        }
        // row sizing
        let mut rh = vec![0i32; nrows];
        for r in 0..nrows {
            cov(line!());
            let t = rows_t.get(r).or(auto_row.as_ref());
            if let Some(Track::Fixed(v)) = t { rh[r] = *v; }
            if let Some(Track::MinMax(a, _)) = t { rh[r] = track_min(a); }
        }
        for (k, &(_, r, _, rs, _)) in placed.iter().enumerate() {
            cov(line!());
            // a `0fr` row never grows (flex factor 0, CSS Grid §12.7) and a scroll-container item's automatic minimum is 0
            // (§6.6: only overflow-visible items get the content-based minimum) — the `grid-template-rows: 0fr → 1fr` collapse
            let zero_fr = matches!(rows_t.get(r).or(auto_row.as_ref()), Some(Track::Fr(0))) || matches!(rows_t.get(r).or(auto_row.as_ref()), Some(Track::MinMax(a, b)) if matches!(**a, Track::Auto) && matches!(**b, Track::Fr(0)));
            if rs == 1 && zero_fr && self.s(placed[k].0).overflow != 0 { continue; }
            if rs == 1 && !matches!(rows_t.get(r).or(auto_row.as_ref()), Some(Track::Fixed(_))) { rh[r] = rh[r].max(self.term(placed[k].0, "grid.item_h", laid[k].h)); }
        }
        if std::env::var("OMR_GRID").map_or(false, |q| self.dom.attr(n, "class").unwrap_or("").contains(q.as_str())) {
            eprintln!("grid rows {:?} auto_row {:?} items {:?}", rh.iter().map(|x| *x as f32 / 64.0).collect::<Vec<_>>(), auto_row, placed.iter().zip(&laid).map(|(p, l)| (p.0, self.dom.tag(p.0).to_string(), p.1, p.3, l.h as f32 / 64.0)).collect::<Vec<_>>());
        }
        // spanning items, smallest span first: extra height is shared equally by the spanned non-fixed rows (CSS Grid §11.5)
        let mut spans: Vec<usize> = (0..placed.len()).filter(|&k| placed[k].3 > 1).collect();
        spans.sort_by_key(|&k| placed[k].3);
        let fixed_row = |q: usize| matches!(rows_t.get(q).or(auto_row.as_ref()), Some(Track::Fixed(_)));
        if self.patch(n, "patch.grid_span_fill") {
            // CSS Grid §12.5 distribute extra space, as Chrome measures it (blackbox/oracle-grid-span, docs.rs main-heading): items go
            // in groups of equal span count, smallest first; within a group every item distributes against the SAME base sizes and a
            // row takes the largest increase any item asks of it (span-2 items over rows 1–2 and 2–3: 40 and 300 px → rows 20 / 150 /
            // 150). An item's space goes EQUALLY to its unlimited rows (a row holding a non-spanning item is frozen at that size, its
            // growth limit); with none it goes beyond the limits, equally over all its rows (docs.rs: 30 + 24 under 66 → 33 / 27)
            let mut i = 0;
            while i < spans.len() {
                let g = placed[spans[i]].3;
                let mut j = i; while j < spans.len() && placed[spans[j]].3 == g { j += 1; }
                let mut plan = vec![0i32; rh.len()];
                for &k in &spans[i..j] {
                    cov(line!());
                    let (_, r, _, rs, _) = placed[k];
                    let end = (r + rs).min(nrows);
                    let have: i32 = rh[r..end].iter().sum::<i32>() + rgap * (end - r).saturating_sub(1) as i32;
                    if laid[k].h <= have { continue; }
                    let flex_rows: Vec<usize> = (r..end).filter(|&q| !fixed_row(q)).collect();
                    let targets = if flex_rows.is_empty() { vec![end - 1] } else { flex_rows };
                    let unlimited: Vec<usize> = targets.iter().copied().filter(|&q| !placed.iter().any(|p| p.3 == 1 && p.1 == q)).collect();
                    let qs = if unlimited.is_empty() { targets } else { unlimited };
                    let extra = laid[k].h - have;
                    let each = extra / qs.len() as i32; let rem = extra - each * qs.len() as i32;
                    for (t, &q) in qs.iter().enumerate() { plan[q] = plan[q].max(each + if (t as i32) < rem { 1 } else { 0 }); }
                }
                for q in 0..rh.len() { rh[q] += plan[q]; }
                i = j;
            }
        } else {
        for k in spans {
            cov(line!());
            let (_, r, _, rs, _) = placed[k];
            let end = (r + rs).min(nrows);
            let have: i32 = rh[r..end].iter().sum::<i32>() + rgap * (end - r).saturating_sub(1) as i32;
            if laid[k].h <= have { continue; }
            let flex_rows: Vec<usize> = (r..end).filter(|&q| !matches!(rows_t.get(q).or(auto_row.as_ref()), Some(Track::Fixed(_)))).collect();
            let targets = if flex_rows.is_empty() { vec![end - 1] } else { flex_rows };
            let extra = laid[k].h - have;
            let share = extra / targets.len() as i32;
            for (i, &q) in targets.iter().enumerate() { rh[q] += if i + 1 == targets.len() { extra - share * (targets.len() as i32 - 1) } else { share }; }
        }
        }
        // flexible rows (CSS Grid §12.7): with an indefinite height the flex fraction is the largest base size per fr over the fr
        // rows (§12.7.1), so `1fr 1fr` rows come out equal (theguardian ul: 98 / 107 → 107 / 107, which stretches its cards and
        // gives the empty flex-basis:100% footer div its 9 px); with a definite height the leftover space is shared by fr, a row
        // whose base exceeds its share keeping its base (treated as inflexible, §12.7.1 iterated)
        if self.patch(n, "patch.grid_fr_rows") {
            let frs: Vec<(usize, i32)> = (0..nrows).filter_map(|r| match rows_t.get(r).or(auto_row.as_ref()) {
                Some(Track::Fr(f)) => Some((r, *f)),
                Some(Track::MinMax(_, b)) => if let Track::Fr(f) = **b { Some((r, f)) } else { None },
                _ => None }).filter(|x| x.1 > 0).collect();
            if !frs.is_empty() {
                match self.cbh.last().copied().flatten() {
                    None => {
                        let frac = frs.iter().map(|&(r, f)| rh[r] as i64 * 100 / f.max(100) as i64).max().unwrap_or(0);
                        for &(r, f) in &frs { rh[r] = rh[r].max((frac * f.max(100) as i64 / 100) as i32); }
                    }
                    Some(def) => {
                        let inflex: i32 = (0..nrows).filter(|r| !frs.iter().any(|x| x.0 == *r)).map(|r| rh[r]).sum::<i32>() + rgap * (nrows as i32 - 1).max(0);
                        let mut flex = frs.clone();
                        loop {
                            let rest = def - inflex - frs.iter().filter(|x| !flex.contains(x)).map(|x| rh[x.0]).sum::<i32>();
                            let fsum: i64 = flex.iter().map(|x| x.1 as i64).sum::<i64>().max(100); // a sum below 1fr counts as 1
                            let per = rest.max(0) as i64 * 100 / fsum;
                            let small: Vec<(usize, i32)> = flex.iter().copied().filter(|&(r, f)| per * f as i64 / 100 < rh[r] as i64).collect();
                            if small.is_empty() || small.len() == flex.len() { for &(r, f) in &flex { rh[r] = rh[r].max((per * f as i64 / 100) as i32); } break; }
                            flex.retain(|x| !small.contains(x));
                        }
                    }
                }
            }
        }
        // align-content: normal stretches `auto` rows to fill a definite container height (CSS Grid §11.8)
        let mut ac_free = 0i32;
        if let Some(Some(def)) = self.cbh.last().copied().map(Some) {
            cov(line!());
            if let Some(def) = def {
                cov(line!());
                let used: i32 = rh.iter().sum::<i32>() + rgap * (nrows as i32 - 1).max(0);
                // only tracks whose MAX sizing function is `auto` stretch (CSS Grid §12.8 "Stretch auto Tracks"): an implicit / `auto`
                // row or minmax(x, auto) — never min-content / max-content / fit-content rows (allrecipes footer: grid-auto-rows: min-content)
                let autos: Vec<usize> = (0..nrows).filter(|&r| match rows_t.get(r).or(auto_row.as_ref()) { None | Some(Track::Auto) => true,
                    Some(Track::MinMax(_, b)) => matches!(**b, Track::Auto), _ => false }).collect();
                if s.align_content == 0 && def > used && !autos.is_empty() { let add = self.term(n, "grid.stretch_rows", (def - used) / autos.len() as i32); for r in autos { rh[r] += add; } }
                else if s.align_content != 0 && def > used { ac_free = def - used; }
            }
        }
        // align-content other than normal (CSS Box Alignment 3 §5.1 / Grid §11.8, clean-room; DOCTOR missing-feature card): rows
        // keep their size and the free space goes before / between / around them
        let nr = nrows as i32;
        let (lead, between) = match s.align_content { 2 => (ac_free, 0), 3 => (ac_free / 2, 0), 4 if nr > 1 => (0, ac_free / (nr - 1)),
            5 if nr > 0 => (ac_free / (2 * nr), ac_free / nr), 6 => (ac_free / (nr + 1), ac_free / (nr + 1)), _ => (0, 0) };
        let mut ys = vec![cy + lead; nrows + 1];
        for r in 0..nrows { ys[r + 1] = ys[r] + rh[r] + if r + 1 < nrows { rgap + between } else { 0 }; }
        // move items into their areas (+ self alignment); stretched items (align-self normal/stretch, auto height)
        // are laid out again at their area height so their content sees the real size (CSS Grid §10.4)
        let mut drop_ranges: Vec<(std::ops::Range<usize>, std::ops::Range<usize>, std::ops::Range<usize>)> = Vec::new();
        for (k, &(c, r, col, rs, cs)) in placed.iter().enumerate() {
            cov(line!());
            let l = &laid[k];
            let area_w = xs[(col + cs).min(ncols)] - xs[col] - if col + cs < ncols { cgap } else { 0 };
            let area_h = ys[(r + rs).min(nrows)] - ys[r] - if r + rs < nrows { rgap } else { 0 };
            let is_el = self.dom.nodes[c as usize].kind == Kind::Element;
            let (js, al) = if is_el { (self.s(c).justify_self, self.s(c).align_self) } else { (0, 0) };
            let js = if js == 0 && is_el { s.justify_items } else { js };
            let al = if al == 0 && is_el { match s.align_items { 1 => 1, 2 => 2, 3 => 3, _ => 0 } } else { al };
            // stretch: an auto-height item fills its area; a scroll container also SHRINKS to it (its automatic minimum is 0, §6.6)
            if al == 0 && is_el && matches!(self.s(c).height, Len::Auto) && (l.h < area_h || (l.h > area_h && self.s(c).overflow != 0)) {
                cov(line!());
                let is = self.s(c).clone();
                let (mt, mb) = (res0(is.margin[0], area_w), res0(is.margin[2], area_w));
                let ml = match js { 2 => area_w - l.w, 3 => (area_w - l.w) / 2, _ => res0(is.margin[3], area_w) };
                drop_ranges.push((l.it0..l.it1, l.bx0..l.bx1, l.ab0..l.ab1));
                self.forced_h = Some((c, (area_h - mt - mb).max(0)));
                let saved = std::mem::take(&mut self.floats);
                self.block_box(c, xs[col] + ml, ys[r] + mt, l.w, false);
                self.floats = saved;
                self.forced_h = None;
                continue;
            }
            // the MARGIN box is aligned in the area (CSS Box Alignment 3 §6.1): the item was measured at x = margin-left, so the
            // free space excludes both horizontal margins (found by the doctor: bbc's 32 px icon wrappers with 4 px margins)
            // measured: only POSITIVE margins shrink the free space here — MDN's logo (margin-left −6 px, centred) agrees with
            // Chrome when the negative margin is left out
            let mh = if is_el { let is = self.s(c); res0(is.margin[3], area_w).max(0) + res0(is.margin[1], area_w).max(0) } else { 0 };
            let dx = xs[col] + self.term(c, "grid.justify_off", match js { 2 => area_w - l.w - mh, 3 => (area_w - l.w - mh) / 2, _ => 0 });
            let dy = ys[r] + self.term(c, "grid.align_off", match al { 2 => area_h - l.h, 3 => (area_h - l.h) / 2, _ => 0 });
            self.shift_span(l.it0..l.it1, l.bx0..l.bx1, l.ab0..l.ab1, dx, dy);
        }
        // discard the measurement passes of re-laid items (back to front keeps earlier ranges valid)
        for (it, bx, ab) in drop_ranges.into_iter().rev() {
            cov(line!());
            self.out.items.drain(it);
            self.out.boxes.drain(bx);
            self.abs.drain(ab);
        }
        ys[nrows] - cy
    }
}
